import http.server, sys, time, socketserver, gzip, urllib.parse
class H(http.server.BaseHTTPRequestHandler):
    protocol_version="HTTP/1.1"
    def log_message(self, *a): pass
    def _handle(self):
        length=int(self.headers.get('Content-Length') or 0)
        body=self.rfile.read(length) if length else b''
        with open('/tmp/requests.log','a') as f:
            f.write(f"{self.command} {self.path} {self.request_version} headers={list(self.headers.items())} body={body!r}\n")
        u=urllib.parse.urlparse(self.path); path=u.path; qs=urllib.parse.parse_qs(u.query)
        if path=='/redirect':
            loc=qs.get('to',['/target'])[0]
            code=int(qs.get('code',['302'])[0])
            self.send_response(code); self.send_header('Location',loc); self.send_header('Content-Length','0'); self.end_headers(); return
        if path=='/redirect-loop':
            self.send_response(302); self.send_header('Location','/redirect-loop'); self.send_header('Content-Length','0'); self.end_headers(); return
        if path=='/redirect-chain':
            n=int(qs.get('n',['0'])[0])
            if n>0:
                self.send_response(302); self.send_header('Location',f'/redirect-chain?n={n-1}'); self.send_header('Content-Length','0'); self.end_headers(); return
        if path=='/slow':
            time.sleep(float(qs.get('t',['0.5'])[0]))
        if path.startswith('/status/'):
            code=int(path.split('/')[2]); data=b'status-body'
            self.send_response(code); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length',str(len(data))); self.end_headers()
            if self.command!='HEAD': self.wfile.write(data)
            return
        if path=='/gzip':
            data=gzip.compress(b'gzipped content here')
            self.send_response(200); self.send_header('Content-Encoding','gzip'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/chunked':
            self.send_response(200); self.send_header('Transfer-Encoding','chunked'); self.end_headers(); self.wfile.write(b'5\r\nhello\r\n6\r\n world\r\n0\r\n\r\n'); return
        if path=='/close':
            self.send_response(200); self.send_header('Content-Length','5'); self.send_header('Connection','close'); self.end_headers(); self.wfile.write(b'hello'); self.close_connection=True; return
        if path=='/no-length-close':
            # HTTP/1.0 style?
            self.send_response(200); self.end_headers(); self.wfile.write(b'byclose'); self.close_connection=True; return
        if path=='/big':
            data=b'x'*100000
            self.send_response(200); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/headers':
            data=b'h'
            self.send_response(200); self.send_header('X-Dup','1'); self.send_header('X-Dup','2'); self.send_header('Content-Length','1'); self.end_headers(); self.wfile.write(data); return
        data=b'Hello World'
        if path=='/echo': data=body if body else b'echo'
        self.send_response(200); self.send_header('Content-Type','text/plain'); self.send_header('Content-Length',str(len(data))); self.send_header('X-Custom','yes'); self.end_headers()
        if self.command!='HEAD': self.wfile.write(data)
    do_GET=_handle; do_POST=_handle; do_PUT=_handle; do_DELETE=_handle; do_HEAD=_handle; do_PATCH=_handle; do_OPTIONS=_handle
    def __getattr__(self,name):
        if name.startswith('do_'): return self._handle
        raise AttributeError(name)

class Threaded(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads=True; allow_reuse_address=True
Threaded(('127.0.0.1',18080), H).serve_forever()
