    pub max_repeat: u32,
    pub dump_urls: Option<usize>,
    pub latency_correction: bool,
    pub no_tui: bool,
    pub fps: usize,
    pub method: Method,
    pub headers: Vec<HeaderKV>,
    pub proxy_headers: Vec<HeaderKV>,
    pub timeout: Option<Duration>,
    pub connect_timeout: Duration,
    pub accept_header: Option<String>,
    pub body_string: Option<String>,
    pub body_path: Option<String>,
    pub body_path_lines: Option<String>,
    pub form: Vec<String>,
    pub content_type: Option<String>,
    pub basic_auth: Option<String>,
    pub aws_session: Option<String>,
    pub aws_sigv4: Option<String>,
    pub proxy: Option<Url>,
    pub proxy_http_version: Option<String>,
    pub proxy_http2: bool,
    pub http_version: Option<String>,
    pub http2: bool,
    pub host: Option<String>,
    pub disable_compression: bool,
    pub redirect: usize,
    pub disable_keepalive: bool,
    pub no_pre_lookup: bool,
    pub ipv6: bool,
    pub ipv4: bool,
    pub cacert: Option<String>,
    pub cert: Option<String>,
    pub key: Option<String>,
    pub insecure: bool,
    pub connect_to: Vec<ConnectToEntry>,
    pub no_color: bool,
    pub unix_socket: Option<String>,
    pub stats_success_breakdown: bool,
    pub db_url: Option<String>,
    pub debug: bool,
    pub output: Option<String>,
    pub output_format: OutputFormat,
    pub time_unit: Option<TimeUnit>,
}

fn arg(id: &'static str) -> Arg {
    Arg::new(id)
}

pub fn build_command() -> Command {
    let mut cmd = Command::new("oha")
        .version("1.12.1")
        .about("Ohayou(おはよう), HTTP load generator, inspired by rakyll/hey with tui animation.")
        .arg(arg("url").value_name("URL").required(true).help("Target URL or file with multiple URLs."))
        .arg(arg("n_requests").short('n').value_name("N_REQUESTS").value_parser(parse_n_requests).default_value("200").help("Number of requests to run. Accepts plain numbers or suffixes: k = 1,000, m = 1,000,000 (e.g. 10k, 1m)."))
        .arg(arg("n_connections").short('c').value_name("N_CONNECTIONS").value_parser(clap::value_parser!(usize)).default_value("50").help("Number of connections to run concurrently. You may should increase limit to number of open files for larger `-c`."))
        .arg(arg("n_http2_parallel").short('p').value_name("N_HTTP2_PARALLEL").value_parser(clap::value_parser!(usize)).default_value("1").help("Number of parallel requests to send on HTTP/2. `oha` will run c * p concurrent workers in total."))
        .arg(arg("duration").short('z').value_name("DURATION").value_parser(crate::humantime::parse_duration).conflicts_with("n_requests").help("Duration of application to send requests.\nOn HTTP/1, When the duration is reached, ongoing requests are aborted and counted as \"aborted due to deadline\"\nYou can change this behavior with `-w` option.\nCurrently, on HTTP/2, When the duration is reached, ongoing requests are waited. `-w` option is ignored.\nExamples: -z 10s -z 3m."))
        .arg(arg("wait_ongoing_requests_after_deadline").short('w').long("wait-ongoing-requests-after-deadline").action(ArgAction::SetTrue).requires("duration").help("When the duration is reached, ongoing requests are waited"))
        .arg(arg("query_per_second").short('q').value_name("QUERY_PER_SECOND").value_parser(clap::value_parser!(f64)).conflicts_with_all(["burst_duration", "burst_requests"]).help("Rate limit for all, in queries per second (QPS)"))
        .arg(arg("burst_duration").long("burst-delay").value_name("BURST_DURATION").value_parser(crate::humantime::parse_duration).requires("burst_requests").help("Introduce delay between a predefined number of requests.\nNote: If qps is specified, burst will be ignored"))
        .arg(arg("burst_requests").long("burst-rate").value_name("BURST_REQUESTS").value_parser(clap::value_parser!(usize)).requires("burst_duration").help("Rates of requests for burst. Default is 1\nNote: If qps is specified, burst will be ignored"))
        .arg(arg("rand_regex_url").long("rand-regex-url").action(ArgAction::SetTrue).help("Generate URL by rand_regex crate but dot is disabled for each query e.g. http://127.0.0.1/[a-z][a-z][0-9]. Currently dynamic scheme, host and port with keep-alive do not work well. See https://docs.rs/rand_regex/latest/rand_regex/struct.Regex.html for details of syntax."))
        .arg(arg("urls_from_file").long("urls-from-file").action(ArgAction::SetTrue).help("Read the URLs to query from a file"))
        .arg(arg("max_repeat").long("max-repeat").value_name("MAX_REPEAT").value_parser(clap::value_parser!(u32)).default_value("4").requires("rand_regex_url").help("A parameter for the '--rand-regex-url'. The max_repeat parameter gives the maximum extra repeat counts the x*, x+ and x{n,} operators will become."))
        .arg(arg("dump_urls").long("dump-urls").value_name("DUMP_URLS").value_parser(clap::value_parser!(usize)).help("Dump target Urls <DUMP_URLS> times to debug --rand-regex-url"))
        .arg(arg("latency_correction").long("latency-correction").action(ArgAction::SetTrue).help("Correct latency to avoid coordinated omission problem. It's ignored if -q is not set."))
