pub fn parse_opts() -> Opts {
    let m = build_command().get_matches();
    let output_format = match m.get_one::<String>("output_format").unwrap().as_str() {
        "json" => OutputFormat::Json,
        "csv" => OutputFormat::Csv,
        "quiet" => OutputFormat::Quiet,
        _ => OutputFormat::Text,
    };
