        rand_regex_url: m.get_flag("rand_regex_url"),
        urls_from_file: m.get_flag("urls_from_file"),
        max_repeat: *m.get_one("max_repeat").unwrap(),
        dump_urls: m.get_one::<usize>("dump_urls").copied(),
        latency_correction: m.get_flag("latency_correction"),
        no_tui: m.get_flag("no_tui"),
        fps: *m.get_one("fps").unwrap(),
        method: m.get_one::<Method>("method").unwrap().clone(),
        headers: m.get_many::<HeaderKV>("headers").map(|v| v.cloned().collect()).unwrap_or_default(),
        proxy_headers: m.get_many::<HeaderKV>("proxy_headers").map(|v| v.cloned().collect()).unwrap_or_default(),
        timeout: m.get_one::<Duration>("timeout").copied(),
        connect_timeout: *m.get_one("connect_timeout").unwrap(),
        accept_header: m.get_one::<String>("accept_header").cloned(),
        body_string: m.get_one::<String>("body_string").cloned(),
        body_path: m.get_one::<String>("body_path").cloned(),
        body_path_lines: m.get_one::<String>("body_path_lines").cloned(),
        form: m.get_many::<String>("form").map(|v| v.cloned().collect()).unwrap_or_default(),
        content_type: m.get_one::<String>("content_type").cloned(),
        basic_auth: m.get_one::<String>("basic_auth").cloned(),
        aws_session: m.get_one::<String>("aws_session").cloned(),
        aws_sigv4: m.get_one::<String>("aws_sigv4").cloned(),
        proxy: m.get_one::<Url>("proxy").cloned(),
        proxy_http_version: m.get_one::<String>("proxy_http_version").cloned(),
        proxy_http2: m.get_flag("proxy_http2"),
        http_version: m.get_one::<String>("http_version").cloned(),
        http2: m.get_flag("http2"),
        host: m.get_one::<String>("host").cloned(),
        disable_compression: m.get_flag("disable_compression"),
        redirect: *m.get_one("redirect").unwrap(),
        disable_keepalive: m.get_flag("disable_keepalive"),
        no_pre_lookup: m.get_flag("no_pre_lookup"),
        ipv6: m.get_flag("ipv6"),
        ipv4: m.get_flag("ipv4"),
        cacert: m.get_one::<String>("cacert").cloned(),
        cert: m.get_one::<String>("cert").cloned(),
        key: m.get_one::<String>("key").cloned(),
