use clap::{Arg, ArgAction, Command};
use std::error::Error;
use std::time::Duration;
use url::Url;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct HeaderKV {
    pub name: String,
    pub value: Vec<u8>,
}

pub fn validate_header_name(s: &str) -> Result<String, String> {
    if s.is_empty() || !s.bytes().all(|b| matches!(b, b'!'|b'#'|b'$'|b'%'|b'&'|b'\''|b'*'|b'+'|b'-'|b'.'|b'^'|b'_'|b'`'|b'|'|b'~') || b.is_ascii_alphanumeric()) {
        return Err("invalid HTTP header name".to_string());
    }
    Ok(s.to_ascii_lowercase())
}
pub fn validate_header_value(bytes: &[u8]) -> Result<(), String> {
    if bytes.iter().all(|&b| b == b'\t' || (32..=126).contains(&b) || b >= 128) {
        Ok(())
    } else {
        Err("failed to parse header value".to_string())
    }
}
pub fn parse_header(s: &str) -> Result<HeaderKV, Box<dyn Error + Send + Sync>> {
    let Some(pos) = s.find(':') else {
        return Err("Parse header".into());
    };
    let name = validate_header_name(&s[..pos]).map_err(|e| -> Box<dyn Error + Send + Sync> { e.into() })?;
    let value_raw = s[pos + 1..].trim_start_matches(' ');
    validate_header_value(value_raw.as_bytes()).map_err(|e| -> Box<dyn Error + Send + Sync> { e.into() })?;
    Ok(HeaderKV { name, value: value_raw.as_bytes().to_vec() })
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Method(pub String);
pub fn parse_method(s: &str) -> Result<Method, Box<dyn Error + Send + Sync>> {
    if s.is_empty() || !s.bytes().all(|b| matches!(b, b'!'|b'#'|b'$'|b'%'|b'&'|b'\''|b'*'|b'+'|b'-'|b'.'|b'^'|b'_'|b'`'|b'|'|b'~') || b.is_ascii_alphanumeric()) {
        return Err("invalid HTTP method".into());
    }
    Ok(Method(s.to_string()))
}

pub fn parse_n_requests(s: &str) -> Result<usize, Box<dyn Error + Send + Sync>> {
    let trimmed = s.trim();
    let lower = trimmed.to_ascii_lowercase();
    if let Some(num) = lower.strip_suffix('k') {
        let v: f64 = num.parse()?;
        Ok((v * 1_000f64) as usize)
    } else if let Some(num) = lower.strip_suffix('m') {
        let v: f64 = num.parse()?;
        Ok((v * 1_000_000f64) as usize)
    } else {
        Ok(trimmed.parse::<usize>()?)
    }
}

#[derive(Clone, Debug)]
pub struct ConnectToEntry {
    pub requested_host: String,
    pub requested_port: u16,
    pub target_host: String,
    pub target_port: u16,
}
pub fn parse_connect_to(s: &str) -> Result<ConnectToEntry, Box<dyn Error + Send + Sync>> {
    // Peel fields from the right; requested host may contain ':' (IPv6).
    // Bracketed target hosts are handled specially.
    let syntax = || -> Box<dyn Error + Send + Sync> { "syntax for --connect-to is host:port:target_host:target_port".into() };
    let Some((rest, target_port_str)) = s.rsplit_once(':') else { return Err(syntax()) };
    let (rest, target_host) = if rest.ends_with(']') {
        if let Some(idx) = rest.rfind('[') {
            let pre = &rest[..idx];
            if !pre.is_empty() && !pre.ends_with(':') {
                return Err(syntax());
            }
            (pre.strip_suffix(':').unwrap_or(pre), &rest[idx..])
        } else if rest.contains('[') {
            return Err(syntax());
        } else {
            let Some(x) = rest.rsplit_once(':') else { return Err(syntax()) };
            x
        }
    } else {
        let Some(x) = rest.rsplit_once(':') else { return Err(syntax()) };
        x
    };
    let Some((requested_host, requested_port_str)) = rest.rsplit_once(':') else { return Err(syntax()) };
    let requested_port: u16 = requested_port_str.parse().map_err(|e| -> Box<dyn Error + Send + Sync> {
        format!("requested port must be an u16, but got {requested_port_str}: {e}").into()
    })?;
    let target_port: u16 = target_port_str.parse().map_err(|e| -> Box<dyn Error + Send + Sync> {
        format!("target port must be an u16, but got {target_port_str}: {e}").into()
    })?;
    Ok(ConnectToEntry {
        requested_host: requested_host.to_string(),
        requested_port,
        target_host: target_host.to_string(),
        target_port,
    })
}

