{"command":"cat > src/humantime.rs <<'RS'
use std::error::Error;
use std::time::Duration;

const TOO_LARGE: &str = "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)";

fn unit_value(unit: &str) -> Option<(u64, u32)> {
    // (seconds multiplier, nanoseconds multiplier) - one is used depending on magnitude
    // We represent as a full nanosecond multiplier where possible in u128 in caller via secs.
    match unit {
        "ns" | "nsec" => Some((0, 1)),
        "us" | "µs" | "usec" => Some((0, 1_000)),
        "ms" | "msec" => Some((0, 1_000_000)),
        "s" | "sec" | "secs" | "second" | "seconds" => Some((1, 0)),
        "m" | "min" | "mins" | "minute" | "minutes" => Some((60, 0)),
        "h" | "hr" | "hrs" | "hour" | "hours" => Some((3_600, 0)),
        "d" | "day" | "days" => Some((86_400, 0)),
        "w" | "week" | "weeks" => Some((604_800, 0)),
        "M" | "month" | "months" => Some((2_630_016, 0)),
        "y" | "yr" | "yrs" | "year" | "years" => Some((31_557_600, 0)),
        _ => None,
    }
}

pub fn parse_duration(s: &str) -> Result<Duration, Box<dyn Error + Send + Sync>> {
    parse_duration_str(s).map_err(|e| -> Box<dyn Error + Send + Sync> { e.into() })
}

fn parse_duration_str(s: &str) -> Result<Duration, String> {
    let chars: Vec<(usize, char)> = s.char_indices().collect();
    let mut idx = 0usize; // index in chars
    let peek = |idx: usize, chars: &Vec<(usize, char)>| chars.get(idx).copied();
    let skip_ws = |mut idx: usize, chars: &Vec<(usize, char)>| {
        while let Some((_, c)) = peek(idx, chars) {
            if c.is_whitespace() { idx += 1; } else { break; }
        }
        idx
    };
    idx = skip_ws(idx, &chars);
    if idx >= chars.len() {
        return Err("value was empty".to_string());
    }
    let mut total_secs: u128 = 0;
    let mut total_nanos_part: u128 = 0; // sub-second nanos accumulated beyond secs? We'll accumulate total as (secs, nanos) normalized using u128 secs and u64 nanos remainder handling below.
    // Instead accumulate total_nanoseconds as u128 but cap by Duration max: secs u64::MAX and nanos <1e9.
    // Represent total as u128 nanoseconds may overflow for huge secs (u64::MAX secs in nanos > u128? 1.8e19 * 1e9 =1.8e28 < 3.4e38 u128 max, fine)
    let mut total_ns: u128 = 0;
    let _ = (&mut total_secs, &mut total_nanos_part);
    let mut components = 0usize;

    while idx < chars.len() {
        idx = skip_ws(idx, &chars);
        if idx >= chars.len() { break; }
        let (num_pos, first) = chars[idx];
        if !first.is_ascii_digit() {
            return Err(format!("expected number at {}", num_pos));
        }
        // integer digits
        let int_start = idx;
        while idx < chars.len() && chars[idx].1.is_ascii_digit() { idx += 1; }
        let int_str: String = chars[int_start..idx].iter().map(|x| x.1).collect();
        let int_val: u64 = int_str.parse().map_err(|_| TOO_LARGE.to_string())?;

        // fraction
        let mut frac_str = String::new();
        let mut has_frac = false;
        // skip ws before dot? humantime allows "5 .5"
        let save_idx = idx;
        let idx_ws = skip_ws(idx, &chars);
        if idx_ws < chars.len() && chars[idx_ws].1 == '.' {
            has_frac = true;
            let dot_pos = chars[idx_ws].0;
            idx = idx_ws + 1;
            let after_dot_idx = idx;
            // lookahead skipping ws for a digit
            let j = skip_ws(idx, &chars);
            if j >= chars.len() || !chars[j].1.is_ascii_digit() {
                let err_pos = if j > after_dot_idx {
                    if j < chars.len() { chars[j].0 } else { dot_pos }
                } else { dot_pos };
                return Err(format!("invalid character at {}", err_pos));
            }
            idx = j;
            while idx < chars.len() && chars[idx].1.is_ascii_digit() {
                frac_str.push(chars[idx].1);
                idx += 1;
            }
            // if next non-ws char is '.' or ',' it's invalid char
            let k = skip_ws(idx, &chars);
            if k < chars.len() && chars[k].1 == '.' {
                return Err(format!("invalid character at {}", chars[k].0));
            }
        } else {
            idx = save_idx;
        }

        // unit
        idx = skip_ws(idx, &chars);
        if idx >= chars.len() {
            if components == 0 && int_val == 0 && !has_frac {
                // "0" alone
                return Ok(Duration::ZERO);
            }
            // also plain zero with frac? "0.0" -> missing unit according spec? humantime: if value is 0 and no unit yet... treat like 0? Test orig not done; use missing except exact above.
            return Err(format!("time unit needed, for example {}sec or {}ms", int_val, int_val));
        }
        let (unit_pos, uch) = chars[idx];
        if !(uch.is_ascii_alphabetic() || uch == 'µ') {
            return Err(format!("invalid character at {}", unit_pos));
        }
        let unit_start = idx;
        while idx < chars.len() && (chars[idx].1.is_ascii_alphabetic() || chars[idx].1 == 'µ') { idx += 1; }
        let unit: String = chars[unit_start..idx].iter().map(|x| x.1).collect();
        let Some((sec_mul, ns_mul)) = unit_value(&unit) else {
            return Err(format!("unknown time unit \"{}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)", unit));
        };
        // unit in nanoseconds as u128
        let unit_ns: u128 = if sec_mul > 0 { sec_mul as u128 * 1_000_000_000u128 } else { ns_mul as u128 };
        // integer part
        let add_int = (int_val as u128).checked_mul(unit_ns).ok_or(TOO_LARGE)?;
        total_ns = total_ns.checked_add(add_int).ok_or(TOO_LARGE)?;
        // fraction part
        if has_frac {
            if ns_mul == 1 {
                // any fraction for ns is imprecise in original
                return Err(TOO_LARGE.to_string());
            }
            // fraction value = frac_str / 10^len * unit_ns, must be exact integer nanoseconds
            // Trim trailing zeros beyond precision? We check exactness with big rational using u128.
            // If frac has many digits, handle by checking digits beyond resolution.
            // Compute unit_ns * frac / denom exactly if divisible.
            // Limit: if frac_str len > 38 maybe trim trailing zeros.
            let mut frac_digits = frac_str.clone();
            // Remove trailing zeros for exactness check convenience? But 1.5000 is exact anyway.
            // We'll compute using u128 if len <= 38 after trimming leading? Use string big integer via u128 parse fallback.
            // Trim trailing zeros
            while frac_digits.ends_with('0') && frac_digits.len() > 1 {
                // we need keep denominator consistent: trimming trailing zero divides both by10
                frac_digits.pop();
            }
            if frac_digits.chars().all(|c| c == '0') {
                // zero fraction: for ns unit already handled; otherwise ok even if precision digits many
            } else {
                if frac_digits.len() > 30 {
                    return Err(TOO_LARGE.to_string());
                }
                let frac_val: u128 = frac_digits.parse().map_err(|_| TOO_LARGE.to_string())?;
                let denom: u128 = 10u128.checked_pow(frac_digits.len() as u32).ok_or(TOO_LARGE)?;
                let numerator = unit_ns.checked_mul(frac_val).ok_or(TOO_LARGE.to_string())?;
                if numerator % denom != 0 {
                    return Err(TOO_LARGE.to_string());
                }
                total_ns = total_ns.checked_add(numerator / denom).ok_or(TOO_LARGE.to_string())?;
            }
        }
        // check against Duration max at each component
        let max_ns: u128 = (u64::MAX as u128) * 1_000_000_000u128 + 999_999_999u128;
        if total_ns > max_ns {
            return Err(TOO_LARGE.to_string());
        }
        components += 1;
    }
    let secs = (total_ns / 1_000_000_000u128) as u64;
    let nanos = (total_ns % 1_000_000_000u128) as u32;
    Ok(Duration::new(secs, nanos))
}
RS
"}

