            if k < chars.len() && chars[k].1 == '.' {
                return Err(format!("invalid character at {}", chars[k].0));
            }
        } else {
            idx = save_idx;
        }

        // unit
        idx = skip_ws(idx, &chars);
        if idx >= chars.len() {
            if components == 0 && int_val == 0 && !has_frac {
                // "0" alone
                return Ok(Duration::ZERO);
            }
            // also plain zero with frac? "0.0" -> missing unit according spec? humantime: if value is 0 and no unit yet... treat like 0? Test orig not done; use missing except exact above.
            return Err(format!("time unit needed, for example {}sec or {}ms", int_val, int_val));
