                return Err(TOO_LARGE.to_string());
            }
            // fraction value = frac_str / 10^len * unit_ns, must be exact integer nanoseconds
            // Trim trailing zeros beyond precision? We check exactness with big rational using u128.
            // If frac has many digits, handle by checking digits beyond resolution.
            // Compute unit_ns * frac / denom exactly if divisible.
            // Limit: if frac_str len > 38 maybe trim trailing zeros.
            let mut frac_digits = frac_str.clone();
            // Remove trailing zeros for exactness check convenience? But 1.5000 is exact anyway.
            // We'll compute using u128 if len <= 38 after trimming leading? Use string big integer via u128 parse fallback.
            // Trim trailing zeros
            while frac_digits.ends_with('0') && frac_digits.len() > 1 {
                // we need keep denominator consistent: trimming trailing zero divides both by10
                frac_digits.pop();
            }
            if frac_digits.chars().all(|c| c == '0') {
                // zero fraction: for ns unit already handled; otherwise ok even if precision digits many
            } else {
                if frac_digits.len() > 30 {
                    return Err(TOO_LARGE.to_string());
                }
                let frac_val: u128 = frac_digits.parse().map_err(|_| TOO_LARGE.to_string())?;
                let denom: u128 = 10u128.checked_pow(frac_digits.len() as u32).ok_or(TOO_LARGE)?;
                let numerator = unit_ns.checked_mul(frac_val).ok_or(TOO_LARGE.to_string())?;
                if numerator % denom != 0 {
                    return Err(TOO_LARGE.to_string());
                }
                total_ns = total_ns.checked_add(numerator / denom).ok_or(TOO_LARGE.to_string())?;
