use std::collections::HashMap;
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr, UdpSocket};
use std::sync::{Mutex, OnceLock};
use std::time::Duration;

#[derive(Clone, Default)]
pub struct DnsCache {
    inner: std::sync::Arc<Mutex<HashMap<String, Vec<IpAddr>>>>,
}

struct ResolvConf {
    nameservers: Vec<IpAddr>,
    search: Vec<String>,
}

fn resolv_conf() -> &'static ResolvConf {
    static CONF: OnceLock<ResolvConf> = OnceLock::new();
    CONF.get_or_init(|| {
        let mut nameservers = Vec::new();
        let mut search = Vec::new();
        if let Ok(content) = std::fs::read_to_string("/etc/resolv.conf") {
            for line in content.lines() {
                let line = line.split(['#', ';']).next().unwrap_or("");
                let mut parts = line.split_whitespace();
                match parts.next() {
                    Some("nameserver") => {
                        if let Some(ns) = parts.next() {
                            if let Ok(ip) = ns.parse::<IpAddr>() { nameservers.push(ip); }
                        }
                    }
                    Some("search") => { search = parts.map(|s| s.to_string()).collect(); }
                    Some("domain") => { if let Some(d) = parts.next() { search = vec![d.to_string()]; } }
                    _ => {}
                }
            }
        }
        ResolvConf { nameservers, search }
    })
}

fn hosts_lookup(host: &str) -> Vec<IpAddr> {
    let host_l = host.to_ascii_lowercase();
    let mut out = Vec::new();
    if let Ok(content) = std::fs::read_to_string("/etc/hosts") {
        for line in content.lines() {
            let line = line.split('#').next().unwrap_or("");
            let mut parts = line.split_whitespace();
            if let Some(ip_str) = parts.next() {
                if let Ok(ip) = ip_str.parse::<IpAddr>() {
                    if parts.any(|n| n.to_ascii_lowercase() == host_l) {
                        out.push(ip);
                    }
                }
            }
        }
    }
    out
}

fn encode_name(packet: &mut Vec<u8>, name: &str) {
    for label in name.trim_end_matches('.').split('.') {
        if label.is_empty() { continue; }
        packet.push(label.len() as u8);
        packet.extend_from_slice(label.as_bytes());
    }
    packet.push(0);
}

fn read_name(packet: &[u8], mut off: usize) -> Option<(String, usize)> {
    let mut labels = Vec::new();
    let mut jumped = false;
    let mut end_off = off;
    let mut hops = 0;
    loop {
        if off >= packet.len() || hops > 20 { return None; }
        let len = packet[off];
        if len == 0 {
            if !jumped { end_off = off + 1; }
            break;
        } else if len & 0xC0 == 0xC0 {
            if off + 1 >= packet.len() { return None; }
            let ptr = (((len & 0x3F) as usize) << 8) | packet[off + 1] as usize;
            if !jumped { end_off = off + 2; }
            off = ptr;
            jumped = true;
            hops += 1;
        } else {
            let l = len as usize;
            if off + 1 + l > packet.len() { return None; }
            labels.push(String::from_utf8_lossy(&packet[off + 1..off + 1 + l]).to_string());
            off += 1 + l;
        }
    }
    Some((labels.join("."), end_off))
}

fn dns_query(name: &str, qtype: u16, nameserver: IpAddr) -> Result<Vec<IpAddr>, String> {
    let socket = match nameserver {
        IpAddr::V4(_) => UdpSocket::bind((Ipv4Addr::UNSPECIFIED, 0)),
        IpAddr::V6(_) => UdpSocket::bind((Ipv6Addr::UNSPECIFIED, 0)),
    }.map_err(|e| format!("proto error: io error: {}", e))?;
    socket.set_read_timeout(Some(Duration::from_secs(5))).ok();
    socket.set_write_timeout(Some(Duration::from_secs(5))).ok();
    socket.connect((nameserver, 53)).map_err(|e| format!("proto error: io error: {}", e))?;
    let id: u16 = (std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.subsec_nanos()).unwrap_or(0) ^ std::process::id() as u32) as u16;
    let mut packet = Vec::new();
    packet.extend_from_slice(&id.to_be_bytes());
    packet.extend_from_slice(&0x0100u16.to_be_bytes()); // RD
    packet.extend_from_slice(&1u16.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    encode_name(&mut packet, name);
    packet.extend_from_slice(&qtype.to_be_bytes());
    packet.extend_from_slice(&1u16.to_be_bytes());
    socket.send(&packet).map_err(|e| format!("proto error: io error: {}", e))?;
    let mut buf = vec![0u8; 4096];
    let n = socket.recv(&mut buf).map_err(|e| format!("proto error: io error: {}", e))?;
    buf.truncate(n);
    if buf.len() < 12 { return Ok(vec![]); }
    let qd = u16::from_be_bytes([buf[4], buf[5]]) as usize;
    let an = u16::from_be_bytes([buf[6], buf[7]]) as usize;
    let rcode = buf[3] & 0x0F;
    let mut off = 12usize;
    for _ in 0..qd {
        let Some((_, noff)) = read_name(&buf, off) else { return Ok(vec![]); };
        off = noff + 4;
    }
    let mut out = Vec::new();
    let mut cname_target: Option<String> = None;
    for _ in 0..an {
        let Some((_, noff)) = read_name(&buf, off) else { break; };
        off = noff;
        if off + 10 > buf.len() { break; }
        let rtype = u16::from_be_bytes([buf[off], buf[off + 1]]);
        let rdlen = u16::from_be_bytes([buf[off + 8], buf[off + 9]]) as usize;
        off += 10;
        if off + rdlen > buf.len() { break; }
        match rtype {
            1 if rdlen == 4 => out.push(IpAddr::V4(Ipv4Addr::new(buf[off], buf[off+1], buf[off+2], buf[off+3]))),
            28 if rdlen == 16 => {
                let mut b = [0u8;16]; b.copy_from_slice(&buf[off..off+16]);
                out.push(IpAddr::V6(Ipv6Addr::from(b)));
            }
            5 => {
                if let Some((cn, _)) = read_name(&buf, off) { cname_target = Some(cn); }
            }
            _ => {}
        }
        off += rdlen;
    }
    if out.is_empty() {
        if let Some(cn) = cname_target {
            // one level of CNAME follow
            if cn.to_ascii_lowercase() != name.to_ascii_lowercase() {
                return dns_query(&cn, qtype, nameserver);
            }
        }
        if rcode == 3 {
            return Ok(vec![]);
        }
    }
    Ok(out)
}

impl DnsCache {
    pub fn new() -> Self { Self::default() }
    pub fn lookup(&self, host: &str, ipv6_only: bool, ipv4_only: bool) -> Result<Vec<IpAddr>, String> {
        let host_clean = host.strip_prefix('[').and_then(|h| h.strip_suffix(']')).unwrap_or(host);
        if let Ok(ip) = host_clean.parse::<IpAddr>() {
            return Ok(vec![ip]);
        }
        // Hickory has a special case for "localhost"
        let key = format!("{}|{}|{}", host_clean.to_ascii_lowercase(), ipv6_only, ipv4_only);
        if let Some(v) = self.inner.lock().unwrap().get(&key) {
            return Ok(v.clone());
        }
        let result = self.lookup_uncached(host_clean, ipv6_only, ipv4_only)?;
        self.inner.lock().unwrap().insert(key, result.clone());
        Ok(result)
    }
    fn lookup_uncached(&self, host: &str, ipv6_only: bool, ipv4_only: bool) -> Result<Vec<IpAddr>, String> {
        // /etc/hosts first (hickory reads hosts)
        let hosts = hosts_lookup(host);
        if !hosts.is_empty() {
            let filtered: Vec<IpAddr> = if ipv6_only {
                hosts.iter().cloned().filter(|i| i.is_ipv6()).collect()
            } else if ipv4_only {
                hosts.iter().cloned().filter(|i| i.is_ipv4()).collect()
            } else { hosts.clone() };
            if !filtered.is_empty() {
                return Ok(filtered);
            }
        }
        let conf = resolv_conf();
        if conf.nameservers.is_empty() {
            return Err("proto error: io error: failed to lookup address information".to_string());
        }
        // candidate names
        let mut candidates: Vec<String> = Vec::new();
        let host_trim = host.trim_end_matches('.').to_string();
        let has_dot = host_trim.contains('.');
        if has_dot || conf.search.is_empty() || host.ends_with('.') {
            candidates.push(host_trim.clone());
            for s in &conf.search { candidates.push(format!("{}.{}", host_trim, s)); }
        } else {
            for s in &conf.search { candidates.push(format!("{}.{}", host_trim, s)); }
            candidates.push(host_trim.clone());
        }
        let qtypes: Vec<u16> = if ipv6_only { vec![28] } else if ipv4_only { vec![1] } else { vec![1, 28] };
        let ns = conf.nameservers[0];
        let mut last_err: Option<String> = None;
        for cand in &candidates {
            let mut all = Vec::new();
            for &qt in &qtypes {
                match dns_query(cand, qt, ns) {
                    Ok(mut v) => all.append(&mut v),
                    Err(e) => { last_err = Some(e.clone()); return Err(e); }
                }
            }
            if !all.is_empty() {
                return Ok(all);
            }
        }
        if let Some(e) = last_err { return Err(e); }
        // NXDOMAIN / no records: approximate hickory message
        Err(format!("no record found for name: {}", host))
    }
}
RS
