fn last_openssl_error() -> String {
    unsafe {
        let e = ERR_get_error();
        if e == 0 { return String::new(); }
        let mut buf = vec![0u8; 512];
        ERR_error_string_n(e, buf.as_mut_ptr() as *mut c_char, buf.len());
