#[derive(Debug)]
#[allow(dead_code)]
enum KeyError { NoItemsFound }
#[derive(Debug)]
#[allow(dead_code)]
enum CertError { NoCertificatesPresented, InconsistentKeys(KeyMismatch) }
#[derive(Debug)]
struct KeyMismatch;

fn parse_private_key_pem(bytes: &[u8]) -> Result<(), KeyError> {
    let text = String::from_utf8_lossy(bytes);
    // rustls-pemfile looks for PKCS8 / traditional unencrypted private keys
    for label in ["PRIVATE KEY", "RSA PRIVATE KEY", "EC PRIVATE KEY"] {
        let begin = format!("-----BEGIN {}-----", label);
        if text.contains(&begin) {
            return Ok(());
        }
    }
    Err(KeyError::NoItemsFound)
}
fn parse_certs_pem(bytes: &[u8]) -> Result<(), CertError> {
    let text = String::from_utf8_lossy(bytes);
    if text.contains("-----BEGIN CERTIFICATE-----") { Ok(()) } else { Err(CertError::NoCertificatesPresented) }
}
pub struct TlsConfig {
    ctx: *mut c_void,
    pub insecure: bool,
}
unsafe impl Send for TlsConfig {}
unsafe impl Sync for TlsConfig {}
impl Drop for TlsConfig { fn drop(&mut self) { unsafe { if !self.ctx.is_null() { SSL_CTX_free(self.ctx); } } } }

impl TlsConfig {
    pub fn build(cacert: Option<&str>, cert: Option<&str>, key: Option<&str>, insecure: bool) -> anyhow::Result<std::sync::Arc<TlsConfig>> {
        unsafe {
            let ctx = SSL_CTX_new(TLS_client_method());
            if ctx.is_null() { anyhow::bail!("{}", last_openssl_error()); }
            // TLS1.2 min like rustls
            SSL_CTX_ctrl(ctx, 123, 0x0303, ptr::null_mut());
            SSL_CTX_set_default_verify_paths(ctx);
            if insecure {
                SSL_CTX_set_verify(ctx, 0, ptr::null());
            } else {
                SSL_CTX_set_verify(ctx, 0x01, ptr::null());
            }
            if let Some(path) = cacert {
                // Original reads file (errors for missing/dir), silently ignores non-cert contents
                let _contents = std::fs::read(path)?;
                if let Ok(cpath) = CString::new(path) {
                    clear_openssl_errors();
                    SSL_CTX_load_verify_locations(ctx, cpath.as_ptr(), ptr::null());
                    clear_openssl_errors();
                }
            }
            if let (Some(cert_path), Some(key_path)) = (cert, key) {
                let key_bytes = std::fs::read(key_path)?;
                let cert_bytes = std::fs::read(cert_path)?;
                parse_private_key_pem(&key_bytes).unwrap();
                parse_certs_pem(&cert_bytes).map_err(|e| e).and_then(|_| {
                    let ccert = CString::new(cert_path).unwrap_or_else(|_| CString::new("").unwrap());
                    let ckey = CString::new(key_path).unwrap_or_else(|_| CString::new("").unwrap());
                    clear_openssl_errors();
                    let r1 = SSL_CTX_use_certificate_chain_file(ctx, ccert.as_ptr());
                    let r2 = SSL_CTX_use_PrivateKey_file(ctx, ckey.as_ptr(), 1);
                    let r3 = SSL_CTX_check_private_key(ctx);
                    if r1 != 1 || r2 != 1 || r3 != 1 {
                        clear_openssl_errors();
                        Err(CertError::InconsistentKeys(KeyMismatch))
                    } else { Ok(()) }
                }).unwrap();
            }
            Ok(std::sync::Arc::new(TlsConfig { ctx, insecure }))
        }
    }
    pub fn new_ssl(&self) -> *mut c_void { unsafe { SSL_new(self.ctx) } }
}

pub struct TlsStreamRaw {
    pub ssl: *mut c_void,
    pub fd: c_int,
