pub fn ssl_connect_once(ssl: *mut c_void) -> c_int { unsafe { clear_openssl_errors(); SSL_connect(ssl) } }
pub fn ssl_read_once(ssl: *mut c_void, buf: &mut [u8]) -> c_int { unsafe { clear_openssl_errors(); SSL_read(ssl, buf.as_mut_ptr() as *mut c_void, buf.len() as c_int) } }
pub fn ssl_write_once(ssl: *mut c_void, buf: &[u8]) -> c_int { unsafe { clear_openssl_errors(); SSL_write(ssl, buf.as_ptr() as *const c_void, buf.len() as c_int) } }
pub fn ssl_get_error(ssl: *mut c_void, ret: c_int) -> c_int { unsafe { SSL_get_error(ssl, ret) } }
pub fn ssl_verify_result(ssl: *mut c_void) -> c_long { unsafe { SSL_get_verify_result(ssl) } }
pub fn ssl_shutdown(ssl: *mut c_void) { unsafe { SSL_shutdown(ssl); } }

pub fn peer_cert_info(ssl: *mut c_void) -> (bool, Vec<String>) {
    // returns (is_ca, valid names formatted like DnsName("x") / IpAddress(1.2.3.4))
    unsafe {
        let cert = SSL_get1_peer_certificate(ssl);
        if cert.is_null() { return (false, vec![]); }
        let is_ca = X509_check_ca(cert) > 0;
        let mut out_ptr: *mut c_uchar = ptr::null_mut();
        let len = i2d_X509(cert, &mut out_ptr);
        let mut names = Vec::new();
