            let der = std::slice::from_raw_parts(out_ptr, len as usize).to_vec();
            names = extract_san_names(&der);
            CRYPTO_free(out_ptr as *mut c_void, ptr::null(), 0);
        }
        X509_free(cert);
        (is_ca, names)
    }
}

// Minimal DER walk to find subjectAltName (2.5.29.17) in certificate extensions.
fn read_len(data: &[u8], pos: &mut usize) -> Option<usize> {
    if *pos >= data.len() { return None; }
    let b = data[*pos]; *pos += 1;
    if b < 0x80 { Some(b as usize) } else {
        let n = (b & 0x7F) as usize;
        if n == 0 || n > 4 || *pos + n > data.len() { return None; }
        let mut v = 0usize;
        for _ in 0..n { v = (v << 8) | data[*pos] as usize; *pos += 1; }
        Some(v)
    }
}
fn read_tlv<'a>(data: &'a [u8], pos: &mut usize) -> Option<(u8, &'a [u8])> {
    if *pos >= data.len() { return None; }
    let tag = data[*pos]; *pos += 1;
    // handle multi-byte tag minimally (not expected)
    let len = read_len(data, pos)?;
    if *pos + len > data.len() { return None; }
    let content = &data[*pos..*pos+len];
    *pos += len;
    Some((tag, content))
}
fn extract_san_names(der: &[u8]) -> Vec<String> {
    // Search byte pattern for OID 06 03 55 1D 11 (2.5.29.17), then parse following OCTET STRING(s)
    let pat = [0x06u8, 0x03, 0x55, 0x1D, 0x11];
    let mut names = Vec::new();
    for i in 0..der.len().saturating_sub(pat.len()) {
        if der[i..i+pat.len()] == pat {
            let mut pos = i + pat.len();
            // Possibly a BOOLEAN critical next, then OCTET STRING
            for _ in 0..2 {
                match read_tlv(der, &mut pos) {
                    Some((0x04, octet)) => {
                        // octet contains SEQUENCE of GeneralName
                        let mut p2 = 0usize;
                        if let Some((0x30, seq)) = read_tlv(octet, &mut p2) {
                            let mut p3 = 0usize;
                            while p3 < seq.len() {
                                if let Some((tag, content)) = read_tlv(seq, &mut p3) {
                                    // context-specific primitive tags: dNSName [2]=0x82, iPAddress [7]=0x87
                                    if tag == 0x82 {
                                        names.push(format!("DnsName(\"{}\")", String::from_utf8_lossy(content)));
                                    } else if tag == 0x87 {
                                        if content.len() == 4 {
                                            names.push(format!("IpAddress({}.{}.{}.{})", content[0], content[1], content[2], content[3]));
                                        } else if content.len() == 16 {
                                            let ip = std::net::Ipv6Addr::from(<[u8;16]>::try_from(content).unwrap());
                                            names.push(format!("IpAddress({})", ip));
                                        }
                                    }
                                } else { break; }
                            }
                        }
                        return names;
                    }
                    Some((0x01, _)) => continue,
                    _ => break,
                }
            }
