pub fn ssl_set_fd(ssl: *mut c_void, fd: c_int) -> bool { unsafe { SSL_set_fd(ssl, fd) == 1 } }
pub fn ssl_set_sni_and_host(ssl: *mut c_void, host: &str, insecure: bool) {
