            // SSL_set_tlsext_host_name is a macro via SSL_ctrl(55)
            extern "C" { fn SSL_ctrl(ssl: *mut c_void, cmd: c_int, larg: c_long, parg: *mut c_void) -> c_long; }
            if host.parse::<std::net::IpAddr>().is_err() {
