pub fn peer_cert_info(ssl: *mut c_void) -> (bool, Vec<String>) {
    // returns (is_ca, valid names formatted like DnsName("x") / IpAddress(1.2.3.4))
    unsafe {
        let cert = SSL_get1_peer_certificate(ssl);
        if cert.is_null() { return (false, vec![]); }
        let is_ca = X509_check_ca(cert) > 0;
        let mut out_ptr: *mut c_uchar = ptr::null_mut();
        let len = i2d_X509(cert, &mut out_ptr);
        let mut names = Vec::new();
        if len > 0 && !out_ptr.is_null() {
            let der = std::slice::from_raw_parts(out_ptr, len as usize).to_vec();
            names = extract_san_names(&der);
            CRYPTO_free(out_ptr as *mut c_void, ptr::null(), 0);
        }
        X509_free(cert);
        (is_ca, names)
    }
}

// Minimal DER walk to find subjectAltName (2.5.29.17) in certificate extensions.
fn read_len(data: &[u8], pos: &mut usize) -> Option<usize> {
    if *pos >= data.len() { return None; }
    let b = data[*pos]; *pos += 1;
    if b < 0x80 { Some(b as usize) } else {
        let n = (b & 0x7F) as usize;
        if n == 0 || n > 4 || *pos + n > data.len() { return None; }
        let mut v = 0usize;
        for _ in 0..n { v = (v << 8) | data[*pos] as usize; *pos += 1; }
        Some(v)
    }
}
fn read_tlv<'a>(data: &'a [u8], pos: &mut usize) -> Option<(u8, &'a [u8])> {
    if *pos >= data.len() { return None; }
    let tag = data[*pos]; *pos += 1;
    // handle multi-byte tag minimally (not expected)
    let len = read_len(data, pos)?;
    if *pos + len > data.len() { return None; }
    let content = &data[*pos..*pos+len];
    *pos += len;
    Some((tag, content))
}
fn extract_san_names(der: &[u8]) -> Vec<String> {
    // Search byte pattern for OID 06 03 55 1D 11 (2.5.29.17), then parse following OCTET STRING(s)
    let pat = [0x06u8, 0x03, 0x55, 0x1D, 0x11];
    let mut names = Vec::new();
    for i in 0..der.len().saturating_sub(pat.len()) {
        if der[i..i+pat.len()] == pat {
            let mut pos = i + pat.len();
            // Possibly a BOOLEAN critical next, then OCTET STRING
            for _ in 0..2 {
                match read_tlv(der, &mut pos) {
                    Some((0x04, octet)) => {
                        // octet contains SEQUENCE of GeneralName
                        let mut p2 = 0usize;
                        if let Some((0x30, seq)) = read_tlv(octet, &mut p2) {
                            let mut p3 = 0usize;
                            while p3 < seq.len() {
                                if let Some((tag, content)) = read_tlv(seq, &mut p3) {
                                    // context-specific primitive tags: dNSName [2]=0x82, iPAddress [7]=0x87
                                    if tag == 0x82 {
                                        names.push(format!("DnsName(\"{}\")", String::from_utf8_lossy(content)));
                                    } else if tag == 0x87 {
                                        if content.len() == 4 {
                                            names.push(format!("IpAddress({}.{}.{}.{})", content[0], content[1], content[2], content[3]));
                                        } else if content.len() == 16 {
                                            let ip = std::net::Ipv6Addr::from(<[u8;16]>::try_from(content).unwrap());
                                            names.push(format!("IpAddress({})", ip));
                                        }
                                    }
                                } else { break; }
                            }
                        }
                        return names;
                    }
                    Some((0x01, _)) => continue,
                    _ => break,
                }
            }
        }
    }
    names
}

pub fn map_tls_error(ssl: *mut c_void, host: &str, os_errno: Option<i32>) -> String {
    let verify = ssl_verify_result(ssl);
    if verify != 0 {
        let (is_ca, names) = peer_cert_info(ssl);
        if is_ca {
            return "invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))".to_string();
        }
        return match verify {
            10 => "invalid peer certificate: Expired".to_string(),
            9 => "invalid peer certificate: Expired".to_string(),
            62 => {
                if names.is_empty() {
                    format!("invalid peer certificate: certificate not valid for name \"{}\"; certificate is only valid for DnsName(\"{}\")", host, host)
                } else {
                    format!("invalid peer certificate: certificate not valid for name \"{}\"; certificate is only valid for {}", host, names.join(" or "))
                }
            }
            18 | 19 | 20 | 21 | 27 | 2 => "invalid peer certificate: UnknownIssuer".to_string(),
            _ => format!("invalid peer certificate: UnknownIssuer"),
        };
    }
    let err_str = last_openssl_error();
    let lower = err_str.to_ascii_lowercase();
    if lower.contains("handshake failure") || lower.contains("sslv3 alert handshake") || lower.contains("tlsv1 alert") {
        if lower.contains("handshake failure") { return "received fatal alert: HandshakeFailure".to_string(); }
    }
    if lower.contains("wrong version number") || lower.contains("unknown protocol") || lower.contains("packet length too long") || lower.contains("record layer failure") {
        return "received corrupt message of type InvalidContentType".to_string();
    }
    if lower.contains("unexpected eof") || lower.contains("eof while") || lower.contains("zero return") {
        return "tls handshake eof".to_string();
    }
    if let Some(errno) = os_errno {
        if errno != 0 {
            return format!("{}", std::io::Error::from_raw_os_error(errno));
        } else {
            return "tls handshake eof".to_string();
        }
    }
    if !err_str.is_empty() {
        // trim openssl prefix up to last ':'
        // rustls-ish messages are hard; return a shortened reason when recognizable
        if lower.contains("alert") {
            return "received fatal alert: HandshakeFailure".to_string();
        }
        // fall back to last component
        let reason = err_str.rsplit(':').next().unwrap_or(&err_str).trim().to_string();
        if reason.is_empty() { "tls handshake eof".to_string() } else { reason }
    } else {
        "tls handshake eof".to_string()
    }
}
RS
