use crate::core::{ReqError, TimeCtx, DeadlineKind};
use crate::tls_config as tls;
use std::io::{self, Read, Write};
use std::net::{SocketAddr, TcpStream, Shutdown};
use std::os::unix::io::{AsRawFd, FromRawFd, RawFd};
use std::os::unix::net::UnixStream;
use std::time::{Duration, Instant};

pub fn wait_ready(fd: RawFd, want_write: bool, ctx: &TimeCtx) -> Result<(), ReqError> {
    loop {
        ctx.check()?;
        let timeout = ctx.next_timeout();
        // If a deadline is extremely close we still poll once with its remaining time (or 0).
        let ms = timeout.as_millis() as libc::c_int;
        let mut pfd = libc::pollfd {
            fd,
            events: if want_write { libc::POLLOUT } else { libc::POLLIN },
            revents: 0,
        };
        let r = unsafe { libc::poll(&mut pfd, 1, ms) };
        if r > 0 {
            return Ok(());
        } else if r == 0 {
            // timeout slice; loop will check deadlines. If no deadlines and not cancelled, keep waiting.
            // But if poll timed out due to next_timeout cap, continue.
            // To avoid busy loop when next_timeout is 0 because deadline passed, check:
            ctx.check()?;
            continue;
        } else {
            let e = io::Error::last_os_error();
            if e.kind() == io::ErrorKind::Interrupted { continue; }
            return Err(ReqError::from(e));
        }
    }
}

fn set_nonblocking(fd: RawFd, nonblocking: bool) {
    unsafe {
        let flags = libc::fcntl(fd, libc::F_GETFL);
        if flags >= 0 {
            let new = if nonblocking { flags | libc::O_NONBLOCK } else { flags & !libc::O_NONBLOCK };
            libc::fcntl(fd, libc::F_SETFL, new);
        }
    }
}

pub fn connect_tcp(addr: SocketAddr, ctx: &TimeCtx) -> Result<TcpStream, ReqError> {
    let domain = if addr.is_ipv4() { libc::AF_INET } else { libc::AF_INET6 };
    let fd = unsafe { libc::socket(domain, libc::SOCK_STREAM | libc::SOCK_NONBLOCK | libc::SOCK_CLOEXEC, 0) };
    if fd < 0 { return Err(ReqError::from(io::Error::last_os_error())); }
    let result: Result<TcpStream, ReqError> = (|| {
        match addr {
            SocketAddr::V4(a) => {
                let mut sin: libc::sockaddr_in = unsafe { std::mem::zeroed() };
                sin.sin_family = libc::AF_INET as libc::sa_family_t;
                sin.sin_port = a.port().to_be();
                sin.sin_addr.s_addr = u32::to_be(u32::from(*a.ip()));
                let r = unsafe { libc::connect(fd, &sin as *const libc::sockaddr_in as *const libc::sockaddr, std::mem::size_of::<libc::sockaddr_in>() as libc::socklen_t) };
                if r != 0 {
                    let e = io::Error::last_os_error();
                    if e.raw_os_error() != Some(libc::EINPROGRESS) { return Err(ReqError::from(e)); }
                }
            }
            SocketAddr::V6(a) => {
                let mut sin: libc::sockaddr_in6 = unsafe { std::mem::zeroed() };
                sin.sin6_family = libc::AF_INET6 as libc::sa_family_t;
                sin.sin6_port = a.port().to_be();
                sin.sin6_addr = libc::in6_addr { s6_addr: a.ip().octets() };
                sin.sin6_flowinfo = a.flowinfo();
                sin.sin6_scope_id = a.scope_id();
                let r = unsafe { libc::connect(fd, &sin as *const libc::sockaddr_in6 as *const libc::sockaddr, std::mem::size_of::<libc::sockaddr_in6>() as libc::socklen_t) };
                if r != 0 {
                    let e = io::Error::last_os_error();
                    if e.raw_os_error() != Some(libc::EINPROGRESS) { return Err(ReqError::from(e)); }
                }
            }
        }
        wait_ready(fd, true, ctx)?;
        let mut err: libc::c_int = 0;
        let mut len = std::mem::size_of::<libc::c_int>() as libc::socklen_t;
        let r = unsafe { libc::getsockopt(fd, libc::SOL_SOCKET, libc::SO_ERROR, &mut err as *mut libc::c_int as *mut libc::c_void, &mut len) };
        if r != 0 { return Err(ReqError::from(io::Error::last_os_error())); }
        if err != 0 { return Err(ReqError::from(io::Error::from_raw_os_error(err))); }
        let stream = unsafe { TcpStream::from_raw_fd(fd) };
        // fd is already nonblocking; TcpStream from_raw_fd does not change flags.
        Ok(stream)
    })();
    if result.is_err() {
        unsafe { libc::close(fd); }
        // Note: if TcpStream was created it owns fd, but error paths above happen before creation except wait_ready.
        // The close above on error after from_raw_fd creation can't happen.
    }
    result
}

pub enum AnyStream {
    Tcp(TcpStream),
    Unix(UnixStream),
    Tls(Box<TlsInner>),
}
pub struct TlsInner {
    pub tcp: TcpStream,
    pub raw: tls::TlsStreamRaw,
    pub host: String,
}

impl AnyStream {
    pub fn fd(&self) -> RawFd {
        match self {
            AnyStream::Tcp(s) => s.as_raw_fd(),
            AnyStream::Unix(s) => s.as_raw_fd(),
            AnyStream::Tls(t) => t.tcp.as_raw_fd(),
        }
    }
    pub fn shutdown(&self) {
        match self {
            AnyStream::Tcp(s) => { let _ = s.shutdown(Shutdown::Both); }
            AnyStream::Unix(s) => { let _ = s.shutdown(Shutdown::Both); }
            AnyStream::Tls(t) => { tls::ssl_shutdown(t.raw.ssl); let _ = t.tcp.shutdown(Shutdown::Both); }
        }
    }
    // returns Ok(n), 0 = EOF
    pub fn read_some(&mut self, buf: &mut [u8], ctx: &TimeCtx) -> Result<usize, ReqError> {
        loop {
            match self {
                AnyStream::Tcp(s) => {
                    match s.read(buf) {
                        Ok(n) => return Ok(n),
                        Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => { wait_ready(self.fd(), false, ctx)?; }
                        Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                        Err(e) => return Err(map_io_error_ctx(e, ctx)),
                    }
                }
                AnyStream::Unix(s) => {
                    match s.read(buf) {
                        Ok(n) => return Ok(n),
                        Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => { wait_ready(self.fd(), false, ctx)?; }
                        Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                        Err(e) => return Err(map_io_error_ctx(e, ctx)),
                    }
                }
                AnyStream::Tls(t) => {
                    let ret = tls::ssl_read_once(t.raw.ssl, buf);
                    if ret > 0 {
                        return Ok(ret as usize);
                    }
                    let code = tls::ssl_get_error(t.raw.ssl, ret);
                    match code {
                        2 => { wait_ready(self.fd(), false, ctx)?; } // WANT_READ
                        3 => { wait_ready(self.fd(), true, ctx)?; } // WANT_WRITE
                        6 => return Ok(0), // ZERO_RETURN (close notify)
                        5 => {
                            // SYSCALL: ret 0 => EOF, ret -1 => errno
                            if ret == 0 { return Ok(0); }
                            let e = io::Error::last_os_error();
                            // Check error queue: if there's a TLS-level error, surface EOF semantics for parser via 0? 
                            // If errno is 0, treat as EOF.
                            if e.raw_os_error() == Some(0) || e.raw_os_error().is_none() { return Ok(0); }
                            // ECONNRESET during body: parser treats as body error via EOF marker? Original hyper may report body error.
                            // Return Ok(0) for close-like errors and let parser decide (headers incomplete / body).
                            if matches!(e.raw_os_error(), Some(libc::ECONNRESET) | Some(libc::EPIPE)) { return Ok(0); }
                            return Err(map_io_error_ctx(e, ctx));
                        }
                        _ => {
                            // SSL error during read after handshake: treat as EOF for parser mapping (hyper often maps to body/incomplete errors)
                            // Capture string but caller at header/body stage will map based on position.
                            return Ok(0);
                        }
                    }
                }
            }
        }
    }
    pub fn write_all_ctx(&mut self, mut buf: &[u8], ctx: &TimeCtx) -> Result<(), ReqError> {
        while !buf.is_empty() {
            match self {
                AnyStream::Tcp(s) => {
                    match s.write(buf) {
                        Ok(0) => return Err(ReqError::Msg("write zero".to_string())),
                        Ok(n) => { buf = &buf[n..]; }
                        Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => { wait_ready(self.fd(), true, ctx)?; }
                        Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                        Err(e) => return Err(map_io_error_ctx(e, ctx)),
                    }
                }
                AnyStream::Unix(s) => {
                    match s.write(buf) {
                        Ok(0) => return Err(ReqError::Msg("write zero".to_string())),
                        Ok(n) => { buf = &buf[n..]; }
                        Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => { wait_ready(self.fd(), true, ctx)?; }
                        Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                        Err(e) => return Err(map_io_error_ctx(e, ctx)),
                    }
                }
                AnyStream::Tls(t) => {
                    let ret = tls::ssl_write_once(t.raw.ssl, buf);
                    if ret > 0 {
                        buf = &buf[ret as usize..];
                        continue;
                    }
                    let code = tls::ssl_get_error(t.raw.ssl, ret);
                    match code {
                        2 => wait_ready(self.fd(), false, ctx)?,
                        3 => wait_ready(self.fd(), true, ctx)?,
                        5 => {
                            if ret == 0 { return Err(ReqError::Msg("tls handshake eof".to_string())); }
                            let e = io::Error::last_os_error();
                            return Err(map_io_error_ctx(e, ctx));
                        }
                        _ => {
                            let msg = tls::map_tls_error(t.raw.ssl, &t.host, None);
                            return Err(ReqError::Msg(msg));
                        }
                    }
                }
            }
        }
        Ok(())
    }
}

fn map_io_error_ctx(e: io::Error, ctx: &TimeCtx) -> ReqError {
    // If a deadline has passed, prefer its classification
    if let Err(re) = ctx.check_no_cancel() {
        let _ = &e;
        return re;
    }
    // Some hyper io errors displayed are the io error string (e.g. "Broken pipe (os error 32)" etc.)
    // But for connection reset during read, parser handles EOF; this path is for writes/connect.
    ReqError::Msg(format!("{}", e))
}

pub fn tls_handshake(tcp: TcpStream, cfg: &std::sync::Arc<tls::TlsConfig>, host: &str, alpn_h2: bool, ctx: &TimeCtx) -> Result<AnyStream, ReqError> {
    let fd = tcp.as_raw_fd();
    let ssl = cfg.new_ssl();
    if ssl.is_null() {
        return Err(ReqError::Msg("tls handshake eof".to_string()));
    }
    if !tls::ssl_set_fd(ssl, fd) {
        // free
        let mut raw = tls::TlsStreamRaw { ssl, fd };
        raw.ssl = ssl;
        drop(raw);
        return Err(ReqError::Msg("tls handshake eof".to_string()));
    }
    tls::ssl_set_sni_and_host(ssl, host, cfg.insecure);
    if alpn_h2 { tls::ssl_set_alpn_h2(ssl); }
    let raw = tls::TlsStreamRaw { ssl, fd };
    let mut inner = Box::new(TlsInner { tcp, raw, host: host.to_string() });
    loop {
        let ret = tls::ssl_connect_once(inner.raw.ssl);
        if ret == 1 {
            return Ok(AnyStream::Tls(inner));
        }
        let code = tls::ssl_get_error(inner.raw.ssl, ret);
        match code {
            2 => {
                // WANT_READ
                // check verify failure isn't signalled via connect return only
                if let Err(e) = wait_ready(inner.tcp.as_raw_fd(), false, ctx) { return Err(e); }
            }
            3 => {
                if let Err(e) = wait_ready(inner.tcp.as_raw_fd(), true, ctx) { return Err(e); }
            }
            _ => {
                let errno = if code == 5 && ret != 0 { io::Error::last_os_error().raw_os_error() } else { None };
                // Deadline classification takes precedence if passed
                if let Err(re) = ctx.check_no_cancel() { return Err(re); }
                if ctx.is_cancelled() { return Err(ReqError::Cancelled); }
                let msg = tls::map_tls_error(inner.raw.ssl, host, errno);
                return Err(ReqError::Msg(msg));
            }
        }
    }
}

pub fn connect_unix(path: &str, ctx: &TimeCtx) -> Result<UnixStream, ReqError> {
    ctx.check()?;
    let s = UnixStream::connect(path).map_err(ReqError::from)?;
    set_nonblocking(s.as_raw_fd(), true);
    ctx.check()?;
    let _ = Instant::now() + Duration::ZERO;
    let _ = DeadlineKind::Timeout;
    Ok(s)
}
