#[derive(Debug, Clone)]
pub enum ReqError {
    Msg(String),
    Timeout,
    Cancelled,
    AbortedDueToDeadline,
}
impl ReqError {
    pub fn msg(&self) -> String {
        match self {
            ReqError::Msg(s) => s.clone(),
            ReqError::Timeout => "timeout".to_string(),
            ReqError::Cancelled => "cancelled".to_string(),
            ReqError::AbortedDueToDeadline => "aborted due to deadline".to_string(),
        }
    }
}
impl From<String> for ReqError { fn from(s: String) -> Self { ReqError::Msg(s) } }
impl From<&str> for ReqError { fn from(s: &str) -> Self { ReqError::Msg(s.to_string()) } }
impl From<std::io::Error> for ReqError { fn from(e: std::io::Error) -> Self { ReqError::Msg(format!("{}", e)) } }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DeadlineKind { Timeout, Aborted, }

#[derive(Clone)]
pub struct TimeCtx {
    pub deadlines: Vec<(Instant, DeadlineKind)>,
    pub cancelled: Option<Arc<AtomicBool>>,
}
impl TimeCtx {
    pub fn new(cancelled: Option<Arc<AtomicBool>>) -> Self { Self { deadlines: vec![], cancelled } }
    pub fn add(&mut self, at: Option<Instant>, kind: DeadlineKind) { if let Some(at) = at { self.deadlines.push((at, kind)); } }
    pub fn check(&self) -> Result<(), ReqError> {
        if let Some(c) = &self.cancelled {
            if c.load(Ordering::Relaxed) { return Err(ReqError::Cancelled); }
        }
        let now = Instant::now();
        for (at, kind) in &self.deadlines {
            if now >= *at {
                return Err(match kind { DeadlineKind::Timeout => ReqError::Timeout, DeadlineKind::Aborted => ReqError::AbortedDueToDeadline });
            }
        }
        Ok(())
    }
    pub fn check_no_cancel(&self) -> Result<(), ReqError> {
        let now = Instant::now();
        for (at, kind) in &self.deadlines {
            if now >= *at {
                return Err(match kind { DeadlineKind::Timeout => ReqError::Timeout, DeadlineKind::Aborted => ReqError::AbortedDueToDeadline });
            }
        }
        Ok(())
    }
    pub fn is_cancelled(&self) -> bool { self.cancelled.as_ref().map(|c| c.load(Ordering::Relaxed)).unwrap_or(false) }
    pub fn next_timeout(&self) -> Duration {
        let now = Instant::now();
        let mut best: Option<Duration> = None;
        for (at, _) in &self.deadlines {
            let d = at.saturating_duration_since(now);
            best = Some(match best { None => d, Some(b) => b.min(d) });
        }
        best.unwrap_or(Duration::from_millis(50)).min(Duration::from_millis(50))
    }
    pub fn earliest(&self) -> Option<(Instant, DeadlineKind)> {
        self.deadlines.iter().min_by_key(|(at, _)| *at).copied()
    }
}

