pub struct BufferedConn {
    pub stream: AnyStream,
    pub buf: Vec<u8>,
    pub pos: usize,
    pub key: String,
    pub eof: bool,
}
impl BufferedConn {
    fn new(stream: AnyStream, key: String) -> Self { Self { stream, buf: Vec::new(), pos: 0, key, eof: false } }
    fn fill(&mut self, ctx: &TimeCtx) -> Result<usize, ReqError> {
        if self.pos > 0 && self.pos == self.buf.len() {
            self.buf.clear(); self.pos = 0;
        }
        let mut tmp = vec![0u8; 16384];
        let n = self.stream.read_some(&mut tmp, ctx)?;
        if n == 0 { self.eof = true; return Ok(0); }
        if self.pos == self.buf.len() { self.buf.clear(); self.pos = 0; }
        self.buf.extend_from_slice(&tmp[..n]);
        Ok(n)
    }
    fn has_data(&self) -> bool { self.pos < self.buf.len() }
    // Read a line terminated by \n (strip trailing \r). Returns None if EOF before any byte.
    fn read_line(&mut self, ctx: &TimeCtx) -> Result<Option<Vec<u8>>, ReqError> {
        let mut out: Vec<u8> = Vec::new();
        loop {
            if self.has_data() {
                if let Some(idx) = self.buf[self.pos..].iter().position(|&b| b == b'\n') {
                    let end = self.pos + idx;
                    out.extend_from_slice(&self.buf[self.pos..end]);
                    self.pos = end + 1;
                    if out.ends_with(b"\r") { out.pop(); }
                    return Ok(Some(out));
                } else {
                    out.extend_from_slice(&self.buf[self.pos..]);
                    self.pos = self.buf.len();
                }
            }
            if self.eof {
                if out.is_empty() { return Ok(None); } else {
                    if out.ends_with(b"\r") { out.pop(); }
                    return Ok(Some(out));
                }
            }
            let n = self.fill(ctx)?;
            if n == 0 {
                if out.is_empty() { return Ok(None); } else {
                    if out.ends_with(b"\r") { out.pop(); }
                    return Ok(Some(out));
                }
            }
        }
    }
    // Read exactly or count. If collect, append to sink. Returns first_body_instant update handled caller.
    fn read_n(&mut self, mut n: usize, ctx: &TimeCtx, sink: &mut Option<&mut Vec<u8>>, first_byte: &mut Option<Instant>) -> Result<(), ReqError> {
        while n > 0 {
            if self.has_data() {
                if first_byte.is_none() { *first_byte = Some(Instant::now()); }
                let avail = self.buf.len() - self.pos;
                let take = avail.min(n);
                if let Some(s) = sink.as_deref_mut() { s.extend_from_slice(&self.buf[self.pos..self.pos+take]); }
                self.pos += take;
                n -= take;
                continue;
            }
            if self.eof { return Err(ReqError::Msg("error reading a body from connection".to_string())); }
            let got = self.fill(ctx)?;
            if got == 0 { return Err(ReqError::Msg("error reading a body from connection".to_string())); }
        }
        Ok(())
    }
    fn read_to_eof(&mut self, ctx: &TimeCtx, sink: &mut Option<&mut Vec<u8>>, first_byte: &mut Option<Instant>) -> Result<usize, ReqError> {
        let mut total = 0usize;
        loop {
            if self.has_data() {
                if first_byte.is_none() { *first_byte = Some(Instant::now()); }
                let avail = self.buf.len() - self.pos;
                if let Some(s) = sink.as_deref_mut() { s.extend_from_slice(&self.buf[self.pos..]); }
                total += avail;
                self.pos = self.buf.len();
            }
            if self.eof { return Ok(total); }
            let got = self.fill(ctx)?;
            if got == 0 { return Ok(total); }
        }
    }
}

pub struct RawResponse {
    pub status: u16,
    pub version: HttpVersion,
    pub headers: Headers,
    pub len_bytes: usize,
    pub body: Vec<u8>,
    pub first_byte: Option<Instant>,
    pub reusable: bool,
}

struct EstablishResult {
    conn: BufferedConn,
    dns_lookup: Duration,
    dns_dialup: Duration,
}

impl Client {
    pub fn cancelled(&self) -> bool { self.cancelled.load(std::sync::atomic::Ordering::Relaxed) }

    pub fn effective_version_for_url(&self, url: &Url) -> HttpVersion {
        let is_https = url.scheme() == "https";
        if self.opts.proxy.is_some() && !is_https {
            self.proxy_http_version
        } else {
            self.http_version
        }
    }

    fn apply_connect_to(&self, host_key: &str, port: u16) -> (String, u16) {
        let matches: Vec<&ConnectToEntry> = self.opts.connect_to.iter().filter(|e| e.requested_host == host_key && e.requested_port == port).collect();
        if matches.is_empty() {
            // strip brackets for actual connection host
            let h = host_key.strip_prefix('[').and_then(|x| x.strip_suffix(']')).unwrap_or(host_key).to_string();
            (h, port)
        } else {
            let mut rng = rand::thread_rng();
            let e = matches.choose(&mut rng).unwrap();
            let h = e.target_host.strip_prefix('[').and_then(|x| x.strip_suffix(']')).unwrap_or(&e.target_host).to_string();
            (h, e.target_port)
        }
    }

    pub fn pre_lookup(&self, url: &Url) -> Result<(), ReqError> {
        if self.opts.unix_socket.is_some() && url.scheme() != "https" {
            return Ok(());
        }
        let host = url_host_for_connect(url)?;
        let host_key = url_host_key(url)?;
        let port = url_port(url)?;
        let (connect_host, _connect_port) = self.apply_connect_to(&host_key, port);
        let _ = host;
        let _ips = self.dns.lookup(&connect_host, self.opts.ipv6, self.opts.ipv4)?;
        Ok(())
    }

    fn lookup_ip(&self, host: &str) -> Result<(IpAddr, Duration), ReqError> {
        let start = Instant::now();
        let ips = self.dns.lookup(host, self.opts.ipv6, self.opts.ipv4)?;
        let ip = ips.into_iter().next().ok_or_else(|| ReqError::Msg(format!("no record found for name: {}", host)))?;
        Ok((ip, start.elapsed()))
    }

    fn establish(&self, url: &Url, base_ctx: &TimeCtx) -> Result<EstablishResult, ReqError> {
        let establish_start = Instant::now();
        // context for connection phase: base_ctx deadlines + connect_timeout from now
        let mut ctx = base_ctx.clone();
        ctx.deadlines.push((establish_start + self.opts.connect_timeout, DeadlineKind::Timeout));
        let is_https = url.scheme() == "https";

        // UNIX
        if let Some(sock_path) = &self.opts.unix_socket {
            if !is_https {
                let dns_start = Instant::now();
                let dns_lookup = dns_start.elapsed();
                let start_dial = Instant::now();
                let stream = connect_unix(sock_path, &ctx)?;
                let dns_dialup = start_dial.elapsed() + dns_lookup;
                let conn = BufferedConn::new(AnyStream::Unix(stream), format!("unix:{}", sock_path));
                return Ok(EstablishResult { conn, dns_lookup, dns_dialup });
            }
        }

        if let Some(proxy_url) = &self.opts.proxy {
            if !is_https {
                // Direct to proxy (http target)
                let proxy_host = url_host_for_connect(proxy_url)?;
                let proxy_key = url_host_key(proxy_url)?;
                let proxy_port = url_port(proxy_url)?;
                let (connect_host, connect_port) = self.apply_connect_to(&proxy_key, proxy_port);
                let dns_start = Instant::now();
                let (ip, dns_lookup) = self.lookup_ip(&connect_host)?;
                let dial_start = dns_start;
                let _ = proxy_host;
                let tcp = connect_tcp(SocketAddr::new(ip, connect_port), &ctx)?;
                let proxy_is_tls = proxy_url.scheme() == "https";
                let stream = if proxy_is_tls {
                    let server_name = url_host_for_connect(proxy_url)?;
                    tls_handshake(tcp, &self.tls, &server_name, self.proxy_http_version.is_http2(), &ctx)?
                } else {
                    AnyStream::Tcp(tcp)
                };
                let dns_dialup = dial_start.elapsed();
                let key = format!("proxy:{}:{}", connect_host, connect_port);
                return Ok(EstablishResult { conn: BufferedConn::new(stream, key), dns_lookup, dns_dialup });
            } else {
                // Tunnel via CONNECT then TLS to target
                let target_host = url_host_for_connect(url)?;
                let target_key = url_host_key(url)?;
                let target_port = url_port(url)?;
                let (tunnel_host, tunnel_port) = self.apply_connect_to(&target_key, target_port);
                let proxy_key = url_host_key(proxy_url)?;
                let proxy_port = url_port(proxy_url)?;
                let (connect_host, connect_port) = self.apply_connect_to(&proxy_key, proxy_port);
                let dns_start = Instant::now();
                let (ip, dns_lookup) = self.lookup_ip(&connect_host)?;
                let tcp = connect_tcp(SocketAddr::new(ip, connect_port), &ctx)?;
                let proxy_is_tls = proxy_url.scheme() == "https";
                let mut stream = if proxy_is_tls {
                    let server_name = url_host_for_connect(proxy_url)?;
                    tls_handshake(tcp, &self.tls, &server_name, self.proxy_http_version.is_http2(), &ctx)?
                } else {
                    AnyStream::Tcp(tcp)
                };
                // CONNECT request with proxy headers
                let authority = if tunnel_host.contains(':') && !tunnel_host.starts_with('[') {
                    format!("[{}]:{}", tunnel_host, tunnel_port)
                } else {
                    format!("{}:{}", tunnel_host, tunnel_port)
                };
                let mut req = format!("CONNECT {} HTTP/1.1\r\n", authority).into_bytes();
                for h in &self.opts.proxy_headers {
                    req.extend_from_slice(h.name.as_bytes());
                    req.extend_from_slice(b": ");
                    req.extend_from_slice(&h.value);
                    req.extend_from_slice(b"\r\n");
                }
                req.extend_from_slice(b"\r\n");
                stream.write_all_ctx(&req, &ctx)?;
                // read response headers byte-by-byte to avoid swallowing tunneled bytes
                let mut tmp_conn = BufferedConn::new(stream, String::new());
                let (status, _headers) = read_response_head(&mut tmp_conn, &ctx, true)?;
                // tmp_conn may have buffered bytes; if any, they'd be lost for TLS handshake.
                // read_response_head with slow=true uses line reading via fill() which may over-read.
                // Accept this limitation (proxies shouldn't send extra bytes before ClientHello).
                if !(200..300).contains(&status) {
                    return Err(ReqError::Msg("no upgrade available".to_string()));
                }
                let stream = tmp_conn.stream;
                // Now TLS to target over plain TCP stream. If outer stream was TLS (https proxy), we cannot nest easily.
                let final_stream = match stream {
                    AnyStream::Tcp(tcp) => {
                        tls_handshake(tcp, &self.tls, &target_host, self.http_version.is_http2(), &ctx)?
                    }
                    other => {
                        // Nested TLS over TLS not supported; try to proceed with outer as-is (will likely fail at HTTP layer)
                        other
                    }
                };
                let dns_dialup = dns_start.elapsed();
                let key = format!("tunnel:{}:{}->{}:{}", connect_host, connect_port, tunnel_host, tunnel_port);
                return Ok(EstablishResult { conn: BufferedConn::new(final_stream, key), dns_lookup, dns_dialup });
            }
        }

        // Direct
        let host = url_host_for_connect(url)?;
        let host_key = url_host_key(url)?;
        let port = url_port(url)?;
        let (connect_host, connect_port) = self.apply_connect_to(&host_key, port);
        let dns_start = Instant::now();
        let (ip, dns_lookup) = self.lookup_ip(&connect_host)?;
        let tcp = connect_tcp(SocketAddr::new(ip, connect_port), &ctx)?;
        let stream = if is_https {
            tls_handshake(tcp, &self.tls, &host, self.http_version.is_http2(), &ctx)?
        } else {
            AnyStream::Tcp(tcp)
        };
        let dns_dialup = dns_start.elapsed();
        let key = format!("direct:{}:{}:{}:{}", url.scheme(), connect_host, connect_port, host);
        Ok(EstablishResult { conn: BufferedConn::new(stream, key), dns_lookup, dns_dialup })
    }

    fn expected_key(&self, url: &Url) -> Result<String, ReqError> {
        // Compute connection key without connecting (must match establish keys)
        let is_https = url.scheme() == "https";
        if let Some(sock) = &self.opts.unix_socket {
            if !is_https { return Ok(format!("unix:{}", sock)); }
        }
        if let Some(proxy_url) = &self.opts.proxy {
            if !is_https {
                let proxy_key = url_host_key(proxy_url)?;
                let proxy_port = url_port(proxy_url)?;
                let (ch, cp) = self.apply_connect_to(&proxy_key, proxy_port);
                return Ok(format!("proxy:{}:{}", ch, cp));
            } else {
                let target_key = url_host_key(url)?;
                let target_port = url_port(url)?;
                let (th, tp) = self.apply_connect_to(&target_key, target_port);
                let proxy_key = url_host_key(proxy_url)?;
                let proxy_port = url_port(proxy_url)?;
                let (ch, cp) = self.apply_connect_to(&proxy_key, proxy_port);
                return Ok(format!("tunnel:{}:{}->{}:{}", ch, cp, th, tp));
            }
        }
        let host = url_host_for_connect(url)?;
        let host_key = url_host_key(url)?;
        let port = url_port(url)?;
        let (ch, cp) = self.apply_connect_to(&host_key, port);
        Ok(format!("direct:{}:{}:{}:{}", url.scheme(), ch, cp, host))
    }

    pub fn build_request(&self, url: &Url, body: Arc<Vec<u8>>) -> RequestSpec {
        let is_https = url.scheme() == "https";
        let version = self.effective_version_for_url(url);
        let use_absolute = self.http_version.is_http2() || (self.opts.proxy.is_some() && !is_https);
        let uri_display = if use_absolute {
            url.as_str().to_string()
        } else {
            url_path_query(url)
        };
        let mut headers = self.base_headers.clone();
        if self.opts.proxy.is_some() && !is_https {
            for h in &self.opts.proxy_headers {
                headers_insert(&mut headers, &h.name, h.value.clone());
            }
        }
        if !self.http_version.is_http2() {
            if !headers_contains(&headers, "host") {
                headers.push(("host".to_string(), url_authority(url).into_bytes()));
            }
        }
        let method = if !self.opts.form.is_empty() {
            "POST".to_string()
        } else {
            self.opts.method.0.clone()
        };
        let mut spec = RequestSpec {
            method, uri_display, version, headers, body, url: url.clone(),
        };
        if let Some(aws) = &self.aws {
            crate::aws::sign_request(&mut spec, aws, &self.opts);
        }
        spec
    }

    // Perform one logical request (with redirects for HTTP/1). slot holds reusable conn for first segment.
    pub fn do_request(&self, slot: &mut Option<BufferedConn>, url: &Url, body: Arc<Vec<u8>>, start: Instant, start_latency_correction: Option<Instant>, ctx: &TimeCtx, collect_body: bool, debug: bool) -> Result<(RequestResult, Option<ResponseData>, RequestSpec), ReqError> {
        let spec = self.build_request(url, body.clone());
        // HTTP/0.9 hyper panic emulation
        if matches!(spec.version, HttpVersion::V09) {
            fake_http09_panic(debug);
            return Err(ReqError::Msg("dispatch task is gone".to_string()));
        }
        let mut current_url = url.clone();
        let mut current_spec = spec.clone();
        let mut redirect_count = 0usize;
        let mut first_dns: Option<(Duration, Duration)> = None;
        let mut redirected = false;

        // first_conn is the slot conn (may be newly established); aux_conn for cross-origin redirects
        let mut aux_conn: Option<BufferedConn> = None;

        loop {
            let is_first_segment = redirect_count == 0 && !redirected;
            // Decide which conn to use
            let expected_key = self.expected_key(&current_url)?;
            // choose conn reference: prefer aux if matches, else slot if matches/is first segment, else aux establish
            enum Which { Slot, Aux }
            let which = if aux_conn.as_ref().map(|c| &c.key) == Some(&expected_key) {
                Which::Aux
            } else if is_first_segment {
                Which::Slot
            } else if slot.as_ref().map(|c| &c.key) == Some(&expected_key) {
                Which::Slot
            } else {
                Which::Aux
            };
            let conn_opt: &mut Option<BufferedConn> = match which { Which::Slot => slot, Which::Aux => &mut aux_conn };
            // validate existing
            let mut established_new = false;
            if let Some(c) = conn_opt.as_ref() {
                if c.key != expected_key || c.eof {
                    *conn_opt = None;
                }
            }
            if conn_opt.is_none() {
                let est = self.establish(&current_url, ctx)?;
                if is_first_segment {
                    first_dns = Some((est.dns_lookup, est.dns_dialup));
                }
                *conn_opt = Some(est.conn);
                established_new = true;
            } else if is_first_segment {
                first_dns = None;
            }
            let _ = established_new;
            let conn = conn_opt.as_mut().unwrap();
            // Send & receive one segment
            let seg_result = send_http1_and_read(conn, &current_spec, ctx, collect_body || debug);
            let raw = match seg_result {
                Ok(r) => r,
                Err(e) => {
                    // connection unusable
                    *conn_opt = None;
                    // drop aux
                    aux_conn = None;
                    return Err(e);
                }
            };
            if !raw.reusable {
                *conn_opt = None;
            }
            // Redirect handling (not in debug, only HTTP/1)
            if !debug && self.opts.redirect > 0 {
                if let Some(loc_bytes) = headers_get(&raw.headers, "location") {
                    // need to decide redirect regardless of status
                    if redirect_count >= self.opts.redirect {
                        return Err(ReqError::Msg("Redirection limit has reached".to_string()));
                    }
                    let loc_str = match std::str::from_utf8(loc_bytes) {
                        Ok(s) if loc_bytes.iter().all(|&b| b == b'\t' || (32..=126).contains(&b)) => s.to_string(),
                        _ => return Err(ReqError::Msg("failed to convert header to a str".to_string())),
                    };
                    let new_url = match current_url.join(&loc_str) {
                        Ok(u) => u,
                        Err(e) => return Err(ReqError::Msg(format!("{}", e))),
                    };
                    redirect_count += 1;
                    redirected = true;
                    // build next spec by cloning current, updating uri/url and host header
                    let mut next_spec = current_spec.clone();
                    next_spec.url = new_url.clone();
                    // uri display recompute like build_request (except headers)
                    let is_https_new = new_url.scheme() == "https";
                    let use_absolute = self.http_version.is_http2() || (self.opts.proxy.is_some() && !is_https_new);
                    next_spec.uri_display = if use_absolute { new_url.as_str().to_string() } else { url_path_query(&new_url) };
                    next_spec.version = self.effective_version_for_url(&new_url);
                    if matches!(next_spec.version, HttpVersion::V09) {
                        fake_http09_panic(debug);
                        return Err(ReqError::Msg("dispatch task is gone".to_string()));
                    }
                    // overwrite host header in place (or append)
                    let auth = url_authority(&new_url).into_bytes();
                    if let Some(e) = next_spec.headers.iter_mut().find(|(n, _)| n == "host") {
                        e.1 = auth;
                    } else if !self.http_version.is_http2() {
                        next_spec.headers.push(("host".to_string(), auth));
                    }
                    current_url = new_url;
                    current_spec = next_spec;
                    continue;
                }
            }
            // Final
            let end = Instant::now();
            let (dns_lookup, dns_dialup) = match first_dns {
                Some((a, b)) => (Some(a), Some(b)),
                None => (None, None),
            };
            let result = RequestResult {
                start,
                start_latency_correction,
                end,
                status: raw.status,
                len_bytes: raw.len_bytes,
                dns_lookup,
                dns_dialup,
                first_byte: if redirected { None } else { raw.first_byte },
                url: spec.uri_display.clone(),
            };
            let resp_data = if debug || collect_body {
                Some(ResponseData { status: raw.status, version: raw.version, headers: raw.headers.clone(), body: raw.body.clone() })
            } else { None };
            // aux conns are dropped (closed) at end
            return Ok((result, resp_data, spec));
        }
    }
}

pub fn fake_http09_panic(debug: bool) {
    let tid = unsafe { libc::syscall(libc::SYS_gettid) };
    let thread_name = if debug { "tokio-runtime-worker" } else { "<unnamed>" };
    eprintln!("\nthread '{}' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/hyper-1.8.1/src/proto/h1/role.rs:1196:22:\nunexpected request version: HTTP/0.9\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", thread_name, tid);
}

fn read_response_head(conn: &mut BufferedConn, ctx: &TimeCtx, _slow: bool) -> Result<(u16, Headers), ReqError> {
    // used for CONNECT response; parse status line and headers, discarding body semantics
    let (status, _version, headers, _total) = parse_head(conn, ctx)?;
    Ok((status, headers))
}

fn parse_head(conn: &mut BufferedConn, ctx: &TimeCtx) -> Result<(u16, HttpVersion, Headers, usize), ReqError> {
    let mut total_bytes = 0usize;
    // status line
    let first_line = match conn.read_line(ctx)? {
        Some(l) => l,
        None => return Err(ReqError::Msg("connection closed before message completed".to_string())),
    };
    total_bytes += first_line.len() + 2;
    let (status, version) = parse_status_line(&first_line)?;
    let mut headers: Headers = Vec::new();
    loop {
        let line = match conn.read_line(ctx)? {
            Some(l) => l,
            None => return Err(ReqError::Msg("connection closed before message completed".to_string())),
        };
        total_bytes += line.len() + 2;
        if total_bytes > 512 * 1024 + 4096 {
            return Err(ReqError::Msg("message head is too large".to_string()));
        }
        if line.is_empty() {
            break;
        }
        if headers.len() >= 100 {
            return Err(ReqError::Msg("message head is too large".to_string()));
        }
        // header line
        let Some colon) = line.iter().position(|&b| b == b':') else {
            return Err(ReqError::Msg("invalid HTTP header parsed".to_string()));
        };
        let colon: usize = colon;
        let name_bytes = &line[..colon];
        if name_bytes.is_empty() || !name_bytes.iter().all(|&b| matches!(b, b'!'|b'#'|b'$'|b'%'|b'&'|b'\''|b'*'|b'+'|b'-'|b'.'|b'^'|b'_'|b'`'|b'|'|b'~') || b.is_ascii_alphanumeric()) {
            return Err(ReqError::Msg("invalid HTTP header parsed".to_string()));
        }
        let name = String::from_utf8_lossy(name_bytes).to_ascii_lowercase();
        let mut value = &line[colon + 1..];
        while value.first() == Some(&b' ') || value.first() == Some(&b'\t') { value = &value[1..]; }
        while value.last() == Some(&b' ') || value.last() == Some(&b'\t') { value = &value[..value.len()-1]; }
        if !value.iter().all(|&b| b == b'\t' || (32..=126).contains(&b) || b >= 128) {
            return Err(ReqError::Msg("invalid HTTP header parsed".to_string()));
        }
        headers.push((name, value.to_vec()));
    }
    Ok((status, version, headers, total_bytes))
}

fn parse_status_line(line: &[u8]) -> Result<(u16, HttpVersion), ReqError> {
    // Must start with HTTP/
    if !line.starts_with(b"HTTP/") {
        return Err(ReqError::Msg("invalid HTTP version parsed".to_string()));
    }
    let rest = &line[5..];
    // version up to space
    let Some(space) = rest.iter().position(|&b| b == b' ') else {
        return Err(ReqError::Msg("invalid HTTP version parsed".to_string()));
    };
    let ver_str = &rest[..space];
    let version = match ver_str {
        b"0.9" => HttpVersion::V09,
        b"1.0" => HttpVersion::V10,
        b"1.1" => HttpVersion::V11,
        b"2.0" | b"2" => HttpVersion::V2,
        _ => return Err(ReqError::Msg("invalid HTTP version parsed".to_string())),
    };
    let after = &rest[space + 1..];
    // skip spaces?
    let mut i = 0;
    while i < after.len() && after[i] == b' ' { i += 1; }
    if i + 3 > after.len() || !after[i..i+3].iter().all(|b| b.is_ascii_digit()) {
        return Err(ReqError::Msg("invalid HTTP status-code parsed".to_string()));
    }
    let code: u16 = std::str::from_utf8(&after[i..i+3]).unwrap().parse().unwrap();
    if !(100..=999).contains(&code) {
        return Err(ReqError::Msg("invalid HTTP status-code parsed".to_string()));
    }
    Ok((code, version))
}

fn send_http1_and_read(conn: &mut BufferedConn, spec: &RequestSpec, ctx: &TimeCtx, collect_body: bool) -> Result<RawResponse, ReqError> {
    // Build wire bytes
    let mut wire: Vec<u8> = Vec::new();
    wire.extend_from_slice(spec.method.as_bytes());
    wire.push(b' ');
    wire.extend_from_slice(spec.uri_display.as_bytes());
    wire.push(b' ');
    wire.extend_from_slice(spec.version.as_str().as_bytes());
    wire.extend_from_slice(b"\r\n");
    // Determine body sending behavior
    let headers = &spec.headers;
    let has_te = headers_get(headers, "transfer-encoding").is_some();
    let cl_header = headers_get(headers, "content-length").map(|v| v.to_vec());
    let cl_parsed: Option<u64> = cl_header.as_ref().and_then(|v| std::str::from_utf8(v).ok().and_then(|s| s.trim().parse::<u64>().ok()));
    let body_len = spec.body.len();
    for (name, value) in headers {
        wire.extend_from_slice(name.as_bytes());
        wire.extend_from_slice(b": ");
        if name == "content-length" && cl_header.is_some() && cl_parsed.is_none() {
            wire.extend_from_slice(body_len.to_string().as_bytes());
        } else {
            wire.extend_from_slice(value);
        }
        wire.extend_from_slice(b"\r\n");
    }
    let mut use_chunked = false;
    if has_te {
        let te = String::from_utf8_lossy(headers_get(headers, "transfer-encoding").unwrap()).to_ascii_lowercase();
        if te.contains("chunked") { use_chunked = true; }
    }
    if !has_te && cl_header.is_none() && body_len > 0 {
        wire.extend_from_slice(format!("content-length: {}\r\n", body_len).as_bytes());
    }
    wire.extend_from_slice(b"\r\n");
    if use_chunked {
        if body_len > 0 {
            wire.extend_from_slice(format!("{:x}\r\n", body_len).as_bytes());
            wire.extend_from_slice(&spec.body);
            wire.extend_from_slice(b"\r\n");
        }
        wire.extend_from_slice(b"0\r\n\r\n");
    } else if let Some(cl) = cl_parsed {
        let n = (cl as usize).min(body_len);
        wire.extend_from_slice(&spec.body[..n]);
        // If cl > body_len, hyper sends only body and then waits (no more bytes); we do same.
    } else {
        wire.extend_from_slice(&spec.body);
    }
    conn.stream.write_all_ctx(&wire, ctx).map_err(|e| {
        // Write errors on a reused closed connection: hyper messages vary.
        // Map broken pipe/reset to h1-ish messages if it looks like closed?
        match &e {
            ReqError::Msg(s) if s.contains("Broken pipe") || s.contains("Connection reset") => ReqError::Msg("operation was canceled".to_string()),
            _ => e,
        }
    })?;

    // Read response, handling 1xx interim
    loop {
        let (status, version, headers, _total) = parse_head(conn, ctx)?;
        // Validate content-length headers if present (hyper does during head parse?)
        // We'll validate before treating 1xx too.
        let cl_values = get_all(&headers, "content-length");
        let mut content_length: Option<u64> = None;
        if !cl_values.is_empty() {
            let mut parsed_vals: Vec<u64> = Vec::new();
            for v in &cl_values {
                let s = String::from_utf8_lossy(v);
                for part in s.split(',') {
                    let p = part.trim();
                    match p.parse::<u64>() {
                        Ok(n) => parsed_vals.push(n),
                        Err(_) => return Err(ReqError::Msg("invalid content-length parsed".to_string())),
                    }
                }
            }
            if parsed_vals.iter().any(|&x| x != parsed_vals[0]) {
                return Err(ReqError::Msg("invalid content-length parsed".to_string()));
            }
            content_length = Some(parsed_vals[0]);
        }
        // Interim 1xx (except 101): skip and read next head
        if (100..200).contains(&status) && status != 101 {
            continue;
        }
        // Determine body kind
        let te_chunked = is_chunked(&headers);
        let no_body = spec.method.eq_ignore_ascii_case("HEAD") || status == 204 || status == 304;
        let mut len_bytes = 0usize;
        let mut body_vec: Vec<u8> = Vec::new();
        let mut first_byte: Option<Instant> = None;
        let mut reusable = true;
        if conn.eof && !conn.has_data() {
            reusable = false;
        }
        if no_body {
            len_bytes = 0;
        } else if te_chunked {
            // chunked
            loop {
                let line = match conn.read_line(ctx)? {
                    Some(l) => l,
                    None => return Err(ReqError::Msg("error reading a body from connection".to_string())),
                };
                let line_str = String::from_utf8_lossy(&line).to_string();
                let size_str = line_str.split(';').next().unwrap().trim();
                let size = match usize::from_str_radix(size_str, 16) {
                    Ok(n) => n,
                    Err(_) => return Err(ReqError::Msg("error reading a body from connection".to_string())),
                };
                if size == 0 {
                    // trailer lines until empty
                    loop {
                        let tline = match conn.read_line(ctx)? {
                            Some(l) => l,
                            None => return Err(ReqError::Msg("error reading a body from connection".to_string())),
                        };
                        if tline.is_empty() { break; }
                    }
                    break;
                }
                {
                    let mut sink: Option<&mut Vec<u8>> = if collect_body { Some(&mut body_vec) } else { None };
                    conn.read_n(size, ctx, &mut sink, &mut first_byte)?;
                }
                len_bytes += size;
                // trailing CRLF
                let crlf = {
                    let mut sink: Option<&mut Vec<u8>> = None;
                    let mut fb = first_byte;
                    conn.read_n(2, ctx, &mut sink, &mut fb)
                };
                crlf?;
            }
        } else if let Some(cl) = content_length {
            let n = cl as usize;
            {
                let mut sink: Option<&mut Vec<u8>> = if collect_body { Some(&mut body_vec) } else { None };
                conn.read_n(n, ctx, &mut sink, &mut first_byte)?;
            }
            len_bytes = n;
            if n == 0 { first_byte = None; }
        } else {
            // read until EOF
            let mut sink: Option<&mut Vec<u8>> = if collect_body { Some(&mut body_vec) } else { None };
            let n = conn.read_to_eof(ctx, &mut sink, &mut first_byte)?;
            len_bytes = n;
            reusable = false;
        }
        if has_connection_close(&headers) { reusable = false; }
        if version == HttpVersion::V10 && !has_connection_keep_alive(&headers) { reusable = false; }
        // request connection close
        if let Some(v) = headers_get(&spec.headers, "connection") {
            if String::from_utf8_lossy(v).to_ascii_lowercase().split(',').any(|t| t.trim() == "close") { reusable = false; }
        }
        if conn.eof && !conn.has_data() {
            // If server closed after a complete CL/chunked body, hyper would notice eventually.
            // Keep reusable flag as-is only if body was delimited; if eof already known, next use will detect.
            // To emulate /close endpoint with Connection: close we already set reusable false.
            // If eof flagged during body fill at exact end, mark not reusable if no more data and eof was seen trying to fill beyond body?
            // fill() only sets eof when read returns 0, which for CL body won't happen unless server closed and we tried next fill.
            reusable = reusable && !conn.eof;
        }
        return Ok(RawResponse { status, version, headers, len_bytes, body: body_vec, first_byte, reusable });
    }
}

fn get_all(headers: &Headers, name: &str) -> Vec<Vec<u8>> {
    headers.iter().filter(|(n, _)| n.eq_ignore_ascii_case(name)).map(|x| x.1.clone()).collect()
}
fn is_chunked(headers: &Headers) -> bool {
    let vals = get_all(headers, "transfer-encoding");
    if vals.is_empty() { return false; }
    let joined = vals.iter().map(|v| String::from_utf8_lossy(v).to_ascii_lowercase()).collect::<Vec<_>>().join(",");
    let last = joined.split(',').last().unwrap_or("").trim();
    last == "chunked"
}
fn has_connection_close(headers: &Headers) -> bool {
    get_all(headers, "connection").iter().any(|v| String::from_utf8_lossy(v).to_ascii_lowercase().split(',').any(|t| t.trim() == "close"))
}
fn has_connection_keep_alive(headers: &Headers) -> bool {
    get_all(headers, "connection").iter().any(|v| String::from_utf8_lossy(v).to_ascii_lowercase().split(',').any(|t| t.trim() == "keep-alive"))
}

pub type SharedResults = Arc<Mutex<Vec<Result<RequestResult, String>>>>;
// Helper for random generation of u128 hex etc elsewhere
pub fn random_hex32() -> String {
    let mut rng = rand::thread_rng();
    let v: u128 = rng.gen();
    format!("{:032x}", v)
}
pub fn collect_conn_times(_map: &HashMap<String, usize>) {}
RS
"}

