    let mut rest: Headers = orig.into_iter().filter(|(n, _)| !matches!(n.as_str(), "host" | "authorization" | "content-length" | "x-amz-date" | "x-amz-security-token")).collect();
    let mut new_headers: Headers = Vec::new();
    if aws.session.is_some() {
        new_headers.push(("x-amz-date".to_string(), amz_date.into_bytes()));
        new_headers.push(("host".to_string(), host_sign.into_bytes()));
        new_headers.push(("x-amz-security-token".to_string(), aws.session.clone().unwrap().into_bytes()));
        new_headers.push(("content-length".to_string(), content_length.into_bytes()));
    } else {
        new_headers.push(("host".to_string(), host_sign.into_bytes()));
        new_headers.push(("x-amz-date".to_string(), amz_date.into_bytes()));
        new_headers.push(("content-length".to_string(), content_length.into_bytes()));
    }
    new_headers.append(&mut rest);
    new_headers.push(("authorization".to_string(), auth.into_bytes()));
    spec.headers = new_headers;
}
