use std::fs::File;
use std::io::{BufRead, BufReader};
use rand::Rng;
use regex_syntax::hir::{Class, Hir, HirKind};
use url::Url;

pub enum UrlGenerator {
    Fixed(Url),
    Multi(Vec<Url>),
    Regex { hir: Hir, max_repeat: u32 },
}

impl UrlGenerator {
    pub fn new(url_str: &str, rand_regex: bool, urls_from_file: bool, max_repeat: u32) -> anyhow::Result<Self> {
        if rand_regex {
            let pattern = url_str.replace('.', "\\.");
            let hir = regex_syntax::Parser::new().parse(&pattern).map_err(|e| anyhow::anyhow!("{}", e))?;
            Ok(Self::Regex { hir, max_repeat })
        } else if urls_from_file {
            let file = File::open(url_str)?;
            let urls = BufReader::new(file)
                .lines()
                .filter_map(|line| line.ok())
                .map(|line| line.trim().to_string())
                .filter(|line| !line.is_empty())
                .map(|line| Url::parse(&line))
                .collect::<Result<Vec<Url>, _>>()?;
            assert!(!urls.is_empty());
            Ok(Self::Multi(urls))
        } else {
            Ok(Self::Fixed(Url::parse(url_str)?))
        }
    }

    pub fn generate(&self) -> anyhow::Result<Url> {
        match self {
            UrlGenerator::Fixed(u) => Ok(u.clone()),
            UrlGenerator::Multi(urls) => {
                let mut rng = rand::thread_rng();
                Ok(urls[rng.gen_range(0..urls.len())].clone())
            }
            UrlGenerator::Regex { hir, max_repeat } => {
                let mut rng = rand::thread_rng();
                let generated = gen_hir(hir, *max_repeat, &mut rng);
                Url::parse(&generated).map_err(|e| anyhow::anyhow!("{}, generated url: {}", e, generated))
            }
        }
    }
}

fn gen_hir(hir: &Hir, max_repeat: u32, rng: &mut impl Rng) -> String {
    let mut out = String::new();
    gen_into(hir, max_repeat, rng, &mut out);
    out
}

fn gen_into(hir: &Hir, max_repeat: u32, rng: &mut impl Rng, out: &mut String) {
    match hir.kind() {
        HirKind::Empty => {}
        HirKind::Literal(lit) => {
            out.push_str(&String::from_utf8_lossy(&lit.0));
        }
        HirKind::Class(class) => {
            match class {
                Class::Unicode(ranges) => {
                    let total: u64 = ranges.ranges().iter().map(|r| (r.end() as u64 - r.start() as u64) + 1).sum();
                    if total == 0 { return; }
                    let mut pick = rng.gen_range(0..total);
                    for r in ranges.ranges() {
                        let len = (r.end() as u64 - r.start() as u64) + 1;
                        if pick < len {
                            let cp = r.start() as u64 + pick;
                            if let Some(c) = char::from_u32(cp as u32) { out.push(c); }
                            return;
                        }
                        pick -= len;
                    }
                }
                Class::Bytes(ranges) => {
                    let total: u64 = ranges.ranges().iter().map(|r| (r.end() as u64 - r.start() as u64) + 1).sum();
                    if total == 0 { return; }
                    let mut pick = rng.gen_range(0..total);
                    for r in ranges.ranges() {
                        let len = (r.end() as u64 - r.start() as u64) + 1;
                        if pick < len {
                            let b = r.start() + pick as u8;
                            out.push(b as char);
                            return;
                        }
                        pick -= len;
                    }
                }
            }
        }
        HirKind::Look(_) => {}
        HirKind::Repetition(rep) => {
            let min = rep.min;
            let count = match rep.max {
                Some(max) => {
                    if max <= min { min } else { rng.gen_range(min..=max) }
                }
                None => {
                    let hi = min.saturating_add(max_repeat);
                    if hi <= min { min } else { rng.gen_range(min..=hi) }
                }
            };
            for _ in 0..count {
                gen_into(&rep.sub, max_repeat, rng, out);
            }
        }
        HirKind::Capture(cap) => {
            gen_into(&cap.sub, max_repeat, rng, out);
        }
        HirKind::Concat(seq) => {
            for sub in seq {
                gen_into(sub, max_repeat, rng, out);
            }
        }
        HirKind::Alternation(alts) => {
            if !alts.is_empty() {
                let idx = rng.gen_range(0..alts.len());
                gen_into(&alts[idx], max_repeat, rng, out);
            }
        }
    }
}
