use crate::core::*;
use crate::opts::{OutputFormat, TimeUnit};
use serde::Serialize;
use std::collections::BTreeMap;
use std::io::Write;
use std::time::Duration;

pub const PERCENTILES: [f64; 9] = [0.10, 0.25, 0.50, 0.75, 0.90, 0.95, 0.99, 0.999, 0.9999];
pub const PERCENTILE_LABELS: [&str; 9] = ["p10", "p25", "p50", "p75", "p90", "p95", "p99", "p99.9", "p99.99"];

pub fn percentile_value(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() { return f64::NAN; }
    let idx = ((sorted.len() as f64) * p) as usize;
    let idx = idx.min(sorted.len() - 1);
    sorted[idx]
}

pub fn durations_f64(results: &[RequestResult]) -> Vec<f64> {
    results.iter().map(|r| r.duration().as_secs_f64()).collect()
}

pub fn histogram_bins(durations: &[f64]) -> Vec<(f64, usize)> {
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let step = (slowest - fastest) / 10.0;
    let mut bins: Vec<(f64, usize)> = Vec::new();
    for i in 0..=10usize {
        let boundary = fastest + step * i as f64;
        let count = if i == 0 {
            durations.iter().filter(|&&d| d <= boundary).count()
        } else {
            let prev = fastest + step * (i - 1) as f64;
            durations.iter().filter(|&&d| d > prev && d <= boundary).count()
        };
        bins.push((boundary, count));
    }
    bins
}

#[derive(Clone, Copy, Debug)]
pub struct DisplayTime {
    pub unit: TimeUnit,
}
impl DisplayTime {
    pub fn auto(slowest_secs: f64) -> Self {
        let unit = if slowest_secs < 1e-6 { TimeUnit::Ns }
        else if slowest_secs < 1e-3 { TimeUnit::Us }
        else if slowest_secs < 1.0 { TimeUnit::Ms }
        else if slowest_secs < 60.0 { TimeUnit::S }
        else if slowest_secs < 3600.0 { TimeUnit::M }
        else { TimeUnit::H };
        Self { unit }
    }
    pub fn from_opt(opt: Option<TimeUnit>, slowest_secs: f64) -> Self {
        match opt { Some(unit) => Self { unit }, None => Self::auto(slowest_secs) }
    }
    pub fn factor(&self) -> f64 {
        match self.unit {
            TimeUnit::Ns => 1e9,
            TimeUnit::Us => 1e6,
            TimeUnit::Ms => 1e3,
            TimeUnit::S => 1.0,
            TimeUnit::M => 1.0 / 60.0,
            TimeUnit::H => 1.0 / 3600.0,
        }
    }
    pub fn name(&self) -> &'static str {
        match self.unit {
            TimeUnit::Ns => "ns",
            TimeUnit::Us => "us",
            TimeUnit::Ms => "ms",
            TimeUnit::S => "sec",
            TimeUnit::M => "min",
            TimeUnit::H => "hr",
        }
    }
    pub fn fmt(&self, secs: f64) -> String {
        let v = secs * self.factor();
        if v.is_nan() { format!("NaN {}", self.name()) }
        else if v.is_infinite() { format!("{} {}", if v > 0.0 { "inf" } else { "-inf" }, self.name()) }
        else { format!("{:.4} {}", v, self.name()) }
    }
    pub fn fmt_dur(&self, d: Duration) -> String { self.fmt(d.as_secs_f64()) }
}

pub fn fmt_bytes(bytes: u64) -> String {
    const UNITS: [&str; 6] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    if bytes < 1024 {
        return format!("{} B", bytes);
    }
    let mut value = bytes as f64;
    let mut idx = 0usize;
    while value >= 1024.0 && idx < UNITS.len() - 1 {
        value /= 1024.0;
        idx += 1;
    }
    format!("{:.2} {}", value, UNITS[idx])
}

pub struct StatsData {
    pub success: Vec<RequestResult>,
    pub errors: BTreeMap<String, usize>,
    pub total_time: Duration,
    pub aborted: usize,
}

impl StatsData {
    pub fn total_attempts_for_rps(&self) -> usize {
        self.success.len() + self.errors.values().sum::<usize>()
    }
    pub fn success_rate(&self) -> f64 {
        let non_aborted_errors: usize = self.errors.iter().filter(|(k, _)| k.as_str() != "aborted due to deadline").map(|(_, v)| *v).sum();
        let denom = self.success.len() + non_aborted_errors;
        if denom == 0 { f64::NAN } else { self.success.len() as f64 / denom as f64 }
    }
}

pub fn rps_values(results: &[RequestResult], start: std::time::Instant) -> Vec<f64> {
    let mut ends: Vec<f64> = results.iter().map(|r| r.end.duration_since(start).as_secs_f64()).collect();
    ends.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let mut out = Vec::new();
    let mut prev = 0.0f64;
    for e in ends {
        let gap = e - prev;
        out.push(1.0 / gap);
        prev = e;
    }
    out
}

#[derive(Serialize)]
struct JsonSummary {
    #[serde(rename = "successRate")] success_rate: f64,
    total: f64,
    slowest: f64,
    fastest: f64,
    average: f64,
    #[serde(rename = "requestsPerSec")] requests_per_sec: f64,
    #[serde(rename = "totalData")] total_data: usize,
    #[serde(rename = "sizePerRequest")] size_per_request: Option<usize>,
    #[serde(rename = "sizePerSec")] size_per_sec: f64,
}
#[derive(Serialize)]
struct JsonPercentiles {
    p10: f64, p25: f64, p50: f64, p75: f64, p90: f64, p95: f64, p99: f64,
    #[serde(rename = "p99.9")] p99_9: f64,
    #[serde(rename = "p99.99")] p99_99: f64,
}
impl JsonPercentiles {
    fn from_sorted(sorted: &[f64]) -> Self {
        Self {
            p10: percentile_value(sorted, 0.10), p25: percentile_value(sorted, 0.25), p50: percentile_value(sorted, 0.50),
            p75: percentile_value(sorted, 0.75), p90: percentile_value(sorted, 0.90), p95: percentile_value(sorted, 0.95),
            p99: percentile_value(sorted, 0.99), p99_9: percentile_value(sorted, 0.999), p99_99: percentile_value(sorted, 0.9999),
        }
    }
}
#[derive(Serialize)]
struct JsonRps {
    mean: f64, stddev: f64, max: f64, min: f64, percentiles: JsonPercentiles,
}
#[derive(Serialize)]
struct JsonDetail { average: f64, fastest: f64, slowest: f64 }
#[derive(Serialize)]
struct JsonDetails {
    #[serde(rename = "DNSDialup")] dns_dialup: JsonDetail,
    #[serde(rename = "DNSLookup")] dns_lookup: JsonDetail,
}
#[derive(Serialize)]
struct JsonOutput {
    summary: JsonSummary,
    #[serde(rename = "responseTimeHistogram")] response_time_histogram: BTreeMap<String, usize>,
    #[serde(rename = "latencyPercentiles")] latency_percentiles: JsonPercentiles,
    #[serde(rename = "responseTimeHistogramSuccessful", skip_serializing_if = "Option::is_none")] hist_succ: Option<BTreeMap<String, usize>>,
    #[serde(rename = "latencyPercentilesSuccessful", skip_serializing_if = "Option::is_none")] perc_succ: Option<JsonPercentiles>,
    #[serde(rename = "responseTimeHistogramNotSuccessful", skip_serializing_if = "Option::is_none")] hist_not: Option<BTreeMap<String, usize>>,
    #[serde(rename = "latencyPercentilesNotSuccessful", skip_serializing_if = "Option::is_none")] perc_not: Option<JsonPercentiles>,
    rps: JsonRps,
    details: JsonDetails,
    #[serde(rename = "statusCodeDistribution")] status_code_distribution: BTreeMap<String, usize>,
    #[serde(rename = "errorDistribution")] error_distribution: BTreeMap<String, usize>,
}

fn hist_to_map(bins: &[(f64, usize)]) -> BTreeMap<String, usize> {
    let mut map = BTreeMap::new();
    for (b, c) in bins {
        map.insert(format!("{}", b), *c);
    }
    map
}

fn detail_stats(values: &[Duration]) -> (f64, f64, f64) {
    if values.is_empty() { return (f64::NAN, f64::INFINITY, f64::NEG_INFINITY); }
    let secs: Vec<f64> = values.iter().map(|d| d.as_secs_f64()).collect();
    let avg = secs.iter().sum::<f64>() / secs.len() as f64;
    let fastest = secs.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = secs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (avg, fastest, slowest)
}

pub fn slowest_fastest_avg(durs: &[f64]) -> (f64, f64, f64) {
    let slowest = durs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = durs.iter().cloned().fold(f64::INFINITY, f64::min);
    let avg = if durs.is_empty() { f64::NAN } else { durs.iter().sum::<f64>() / durs.len() as f64 };
    (slowest, fastest, avg)
}

pub fn print_results<W: Write>(w: &mut W, data: &StatsData, format: OutputFormat, time_unit: Option<TimeUnit>, start: std::time::Instant, stats_success_breakdown: bool, use_color: bool) -> std::io::Result<()> {
    match format {
        OutputFormat::Quiet => Ok(()),
        OutputFormat::Csv => print_csv(w, &data.success, start),
        OutputFormat::Json => print_json(w, data, start, stats_success_breakdown),
        OutputFormat::Text => print_text(w, data, time_unit, stats_success_breakdown, use_color),
    }
}

fn print_csv<W: Write>(w: &mut W, success: &[RequestResult], start: std::time::Instant) -> std::io::Result<()> {
    writeln!(w, "request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status")?;
    let mut sorted: Vec<&RequestResult> = success.iter().collect();
    sorted.sort_by_key(|r| r.start);
    for r in sorted {
        let dns = r.dns_lookup.map(|d| d.as_secs_f64()).unwrap_or(0.0);
        let dial = r.dns_dialup.map(|d| d.as_secs_f64()).unwrap_or(0.0);
        let delay = r.first_byte.map(|fb| fb.duration_since(r.start).as_secs_f64()).unwrap_or(0.0);
        writeln!(w, "{},{},{},{},{},{},{}",
            r.start.duration_since(start).as_secs_f64(), dns, dial, delay, r.duration().as_secs_f64(), r.len_bytes, r.status)?;
    }
    Ok(())
}

fn print_json<W: Write>(w: &mut W, data: &StatsData, start: std::time::Instant, breakdown: bool) -> std::io::Result<()> {
    let success = &data.success;
    let durs = durations_f64(success);
    let (slowest, fastest, average) = slowest_fastest_avg(&durs);
    let total_secs = data.total_time.as_secs_f64();
    let total_data: usize = success.iter().map(|r| r.len_bytes).sum();
    let size_per_request = if success.is_empty() { None } else { Some(total_data / success.len()) };
    let summary = JsonSummary {
        success_rate: data.success_rate(),
        total: total_secs,
        slowest, fastest, average,
        requests_per_sec: data.total_attempts_for_rps() as f64 / total_secs,
        total_data,
        size_per_request,
        size_per_sec: total_data as f64 / total_secs,
    };
    let bins = histogram_bins(&durs);
    let mut sorted = durs.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let latency_percentiles = JsonPercentiles::from_sorted(&sorted);
    let (hist_succ, perc_succ, hist_not, perc_not) = if breakdown {
        let succ_durs: Vec<f64> = success.iter().filter(|r| (200..300).contains(&r.status)).map(|r| r.duration().as_secs_f64()).collect();
        let not_durs: Vec<f64> = success.iter().filter(|r| !(200..300).contains(&r.status)).map(|r| r.duration().as_secs_f64()).collect();
        let mut s1 = succ_durs.clone(); s1.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let mut s2 = not_durs.clone(); s2.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        (Some(hist_to_map(&histogram_bins(&succ_durs))), Some(JsonPercentiles::from_sorted(&s1)), Some(hist_to_map(&histogram_bins(&not_durs))), Some(JsonPercentiles::from_sorted(&s2)))
    } else { (None, None, None, None) };
    let rps_vals = rps_values(success, start);
    let rps_mean = if rps_vals.is_empty() { f64::NAN } else { rps_vals.iter().sum::<f64>() / rps_vals.len() as f64 };
    let rps_stddev = if rps_vals.len() < 2 {
        if rps_vals.len() == 1 { f64::NAN } else { f64::NAN }
    } else {
        let var = rps_vals.iter().map(|x| (x - rps_mean) * (x - rps_mean)).sum::<f64>() / (rps_vals.len() - 1) as f64;
        var.sqrt()
    };
    let mut rps_sorted = rps_vals.clone();
    rps_sorted.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let rps = JsonRps {
        mean: rps_mean,
        stddev: rps_stddev,
        max: rps_vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
        min: rps_vals.iter().cloned().fold(f64::INFINITY, f64::min),
        percentiles: JsonPercentiles::from_sorted(&rps_sorted),
    };
    let dial_vals: Vec<Duration> = success.iter().filter_map(|r| r.dns_dialup).collect();
    let dns_vals: Vec<Duration> = success.iter().filter_map(|r| r.dns_lookup).collect();
    let (da, df, ds) = detail_stats(&dial_vals);
    let (la, lf, ls) = detail_stats(&dns_vals);
    let details = JsonDetails {
        dns_dialup: JsonDetail { average: da, fastest: df, slowest: ds },
        dns_lookup: JsonDetail { average: la, fastest: lf, slowest: ls },
    };
    let mut status_map: BTreeMap<String, usize> = BTreeMap::new();
    for r in success { *status_map.entry(r.status.to_string()).or_insert(0) += 1; }
    let out = JsonOutput {
        summary,
        response_time_histogram: hist_to_map(&bins),
        latency_percentiles,
        hist_succ, perc_succ, hist_not, perc_not,
        rps, details,
        status_code_distribution: status_map,
        error_distribution: data.errors.clone(),
    };
    let text = serde_json::to_string_pretty(&out).unwrap();
    write!(w, "{}", text)
}

// Color helpers: when use_color, wrap lines like original (approximate)
fn colored_heading(s: &str, use_color: bool) -> String {
    if use_color { format!("\x1b[1m\x1b[4m{}\x1b[0m", s) } else { s.to_string() }
}
fn colorize_line(s: &str, color_code: u8, bold: bool, use_color: bool) -> String {
    if !use_color { return s.to_string(); }
    if bold {
        format!("\x1b[38;5;{}m\x1b[1m{}\x1b[0m", color_code, s)
    } else {
        format!("\x1b[38;5;{}m{}\x1b[39m", color_code, s)
    }
}

fn print_histogram<W: Write>(w: &mut W, title: &str, durations: &[f64], dt: &DisplayTime, use_color: bool) -> std::io::Result<()> {
    writeln!(w, "{}", colored_heading(title, use_color))?;
    let bins = histogram_bins(durations);
    // value strings in display unit with 3 decimals
    let val_strs: Vec<String> = bins.iter().map(|(b, _)| {
        let v = b * dt.factor();
        if v.is_nan() { "NaN".to_string() } else { format!("{:.3}", v) }
    }).collect();
    let max_val_len = val_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0).max(5);
    let max_count = bins.iter().map(|x| x.1).max().unwrap_or(0);
    // labels
    let labels: Vec<String> = bins.iter().zip(val_strs.iter()).map(|((_, count), vs)| {
        format!("  {:>width$} {} [{}] ", vs, dt.name(), count, width = max_val_len)
    }).collect();
    let max_label_len = labels.iter().map(|s| s.chars().count()).max().unwrap_or(0);
    for (label, (_, count)) in labels.iter().zip(bins.iter()) {
        let bars = if max_count == 0 { 0 } else { (32.0f64 * (*count as f64) / (max_count as f64)) as usize };
        let bar_str: String = "■".repeat(bars);
        if use_color {
            // Original: green label part then each block individually colored
            let padded = format!("{:<width$}", label, width = max_label_len);
            let colored_bars: String = (0..bars).map(|_| "\x1b[38;5;10m■\x1b[39m").collect();
            writeln!(w, "\x1b[38;5;10m{}|\x1b[39m{}", padded, colored_bars)?;
            let _ = bar_str;
        } else {
            writeln!(w, "{:<width$}|{}", label, bar_str, width = max_label_len)?;
        }
    }
    Ok(())
}

fn print_distribution<W: Write>(w: &mut W, title: &str, sorted: &[f64], dt: &DisplayTime, use_color: bool) -> std::io::Result<()> {
    writeln!(w, "{}", colored_heading(title, use_color))?;
    let labels: [&str;9] = ["10.00%", "25.00%", "50.00%", "75.00%", "90.00%", "95.00%", "99.00%", "99.90%", "99.99%"];
    for (i, p) in PERCENTILES.iter().enumerate() {
        let line = format!("  {} in {}", labels[i], dt.fmt(percentile_value(sorted, *p)));
        writeln!(w, "{}", colorize_line(&line, 10, false, use_color))?;
    }
    Ok(())
}

fn print_text<W: Write>(w: &mut W, data: &StatsData, time_unit: Option<TimeUnit>, breakdown: bool, use_color: bool) -> std::io::Result<()> {
    let success = &data.success;
    let durs = durations_f64(success);
    let (slowest, fastest, average) = slowest_fastest_avg(&durs);
    let dt = DisplayTime::from_opt(time_unit, slowest);
    let total_secs = data.total_time.as_secs_f64();
    let total_data: usize = success.iter().map(|r| r.len_bytes).sum();
    let success_rate = data.success_rate() * 100.0;
    writeln!(w, "{}", colored_heading("Summary:", use_color))?;
    // Success rate line coloring: green bold when 100?, approximate original: green bold if >? We'll color green(10) bold if ==100 or NaN? Original for partial likely yellow/red.
    let sr_line = format!("  Success rate:\t{:.2}%", success_rate);
    let sr_colored = if use_color {
        if success_rate >= 99.0 { colorize_line(&sr_line, 10, true, true) }
        else if success_rate >= 90.0 { format!("\x1b[38;5;11m\x1b[1m{}\x1b[0m", sr_line) }
        else { format!("\x1b[38;5;9m\x1b[1m{}\x1b[0m", sr_line) }
    } else { sr_line };
    writeln!(w, "{}", sr_colored)?;
    writeln!(w, "  Total:\t{}", dt.fmt(total_secs))?;
    writeln!(w, "{}", colorize_line(&format!("  Slowest:\t{}", dt.fmt(slowest)), 11, false, use_color))?;
    writeln!(w, "{}", colorize_line(&format!("  Fastest:\t{}", dt.fmt(fastest)), 10, false, use_color))?;
    writeln!(w, "{}", colorize_line(&format!("  Average:\t{}", dt.fmt(average)), 14, false, use_color))?;
    writeln!(w, "  Requests/sec:\t{:.4}", data.total_attempts_for_rps() as f64 / total_secs)?;
    writeln!(w)?;
    writeln!(w, "  Total data:\t{}", fmt_bytes(total_data as u64))?;
    if success.is_empty() {
        writeln!(w, "  Size/request:\tNaN")?;
    } else {
        writeln!(w, "  Size/request:\t{}", fmt_bytes((total_data / success.len()) as u64))?;
    }
    writeln!(w, "  Size/sec:\t{}", fmt_bytes((total_data as f64 / total_secs) as u64))?;
    writeln!(w)?;
    let mut sorted = durs.clone();
    sorted.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    print_histogram(w, "Response time histogram:", &durs, &dt, use_color)?;
    writeln!(w)?;
    print_distribution(w, "Response time distribution:", &sorted, &dt, use_color)?;
    if breakdown {
        let succ_durs: Vec<f64> = success.iter().filter(|r| (200..300).contains(&r.status)).map(|r| r.duration().as_secs_f64()).collect();
        let not_durs: Vec<f64> = success.iter().filter(|r| !(200..300).contains(&r.status)).map(|r| r.duration().as_secs_f64()).collect();
        let mut s1 = succ_durs.clone(); s1.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let mut s2 = not_durs.clone(); s2.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        writeln!(w)?;
        print_histogram(w, "Response time histogram (2xx only):", &succ_durs, &dt, use_color)?;
        writeln!(w)?;
        print_distribution(w, "Response time distribution (2xx only):", &s1, &dt, use_color)?;
        writeln!(w)?;
        print_histogram(w, "Response time histogram (4xx + 5xx only):", &not_durs, &dt, use_color)?;
        writeln!(w)?;
        print_distribution(w, "Response time distribution (4xx + 5xx only):", &s2, &dt, use_color)?;
    }
    writeln!(w)?;
    writeln!(w)?;
    writeln!(w, "{}", colored_heading("Details (average, fastest, slowest):", use_color))?;
    let dial_vals: Vec<Duration> = success.iter().filter_map(|r| r.dns_dialup).collect();
    let dns_vals: Vec<Duration> = success.iter().filter_map(|r| r.dns_lookup).collect();
    let (da, df, ds) = detail_stats(&dial_vals);
    let (la, lf, ls) = detail_stats(&dns_vals);
    writeln!(w, "  DNS+dialup:\t{}, {}, {}", dt.fmt(da), dt.fmt(df), dt.fmt(ds))?;
    writeln!(w, "  DNS-lookup:\t{}, {}, {}", dt.fmt(la), dt.fmt(lf), dt.fmt(ls))?;
    writeln!(w)?;
    writeln!(w, "{}", colored_heading("Status code distribution:", use_color))?;
    let mut status_counts: BTreeMap<u16, usize> = BTreeMap::new();
    for r in success { *status_counts.entry(r.status).or_insert(0) += 1; }
    let mut status_vec: Vec<(u16, usize)> = status_counts.into_iter().collect();
    status_vec.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    for (code, count) in &status_vec {
        let line = format!("  [{}] {} responses", code, count);
        let colored = if use_color {
            let c = if (200..300).contains(code) { 10 } else if (300..400).contains(code) { 14 } else if (400..500).contains(code) { 11 } else { 9 };
            colorize_line(&line, c, false, true)
        } else { line };
        writeln!(w, "{}", colored)?;
    }
    if !data.errors.is_empty() {
        writeln!(w)?;
        writeln!(w, "{}", colored_heading("Error distribution:", use_color))?;
        let mut err_vec: Vec<(&String, &usize)> = data.errors.iter().collect();
        err_vec.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
        for (msg, count) in err_vec {
            let line = format!("  [{}] {}", count, msg);
            writeln!(w, "{}", colorize_line(&line, 9, false, use_color))?;
        }
    }
    Ok(())
}
RS
"}

