use crate::core::RequestResult;
use std::ffi::{c_char, c_int, c_void, CString};
use std::ptr;
use std::time::{Instant, SystemTime, UNIX_EPOCH};

#[link(name = "sqlite3")]
extern "C" {
    fn sqlite3_open(filename: *const c_char, db: *mut *mut c_void) -> c_int;
    fn sqlite3_close(db: *mut c_void) -> c_int;
    fn sqlite3_prepare_v2(db: *mut c_void, sql: *const c_char, nbyte: c_int, stmt: *mut *mut c_void, tail: *mut *const c_char) -> c_int;
    fn sqlite3_step(stmt: *mut c_void) -> c_int;
    fn sqlite3_finalize(stmt: *mut c_void) -> c_int;
    fn sqlite3_errmsg(db: *mut c_void) -> *const c_char;
    fn sqlite3_bind_text(stmt: *mut c_void, idx: c_int, text: *const c_char, n: c_int, destructor: *mut c_void) -> c_int;
    fn sqlite3_bind_double(stmt: *mut c_void, idx: c_int, v: f64) -> c_int;
    fn sqlite3_bind_int64(stmt: *mut c_void, idx: c_int, v: i64) -> c_int;
    fn sqlite3_bind_null(stmt: *mut c_void, idx: c_int) -> c_int;
    fn sqlite3_reset(stmt: *mut c_void) -> c_int;
    fn sqlite3_exec(db: *mut c_void, sql: *const c_char, cb: *const c_void, arg: *mut c_void, errmsg: *mut *mut c_char) -> c_int;
}

fn errmsg(db: *mut c_void) -> String {
    unsafe {
        let p = sqlite3_errmsg(db);
        if p.is_null() { return "unknown error".to_string(); }
        std::ffi::CStr::from_ptr(p).to_string_lossy().to_string()
    }
}

pub fn store(db_url: &str, results: &[RequestResult], start: Instant) -> anyhow::Result<()> {
    eprintln!("Storing results to {}", db_url);
    unsafe {
        let cpath = CString::new(db_url).unwrap_or_else(|_| CString::new("").unwrap());
        let mut db: *mut c_void = ptr::null_mut();
        let rc = sqlite3_open(cpath.as_ptr(), &mut db);
        if rc != 0 {
            if !db.is_null() { sqlite3_close(db); }
            anyhow::bail!("unable to open database file: {}", db_url);
        }
        let run = || -> anyhow::Result<()> {
            // CREATE TABLE
            let sql = CString::new("CREATE TABLE IF NOT EXISTS oha (\n            url TEXT NOT NULL,\n            start REAL NOT NULL,\n            start_latency_correction REAL,\n            end REAL NOT NULL,\n            duration REAL NOT NULL,\n            status INTEGER NOT NULL,\n            len_bytes INTEGER NOT NULL,\n            run INTEGER NOT NULL\n        )").unwrap();
            let mut stmt: *mut c_void = ptr::null_mut();
            let rc = sqlite3_prepare_v2(db, sql.as_ptr(), -1, &mut stmt, ptr::null_mut());
            if rc != 0 { anyhow::bail!("{}", errmsg(db)); }
            let rc = sqlite3_step(stmt);
            sqlite3_finalize(stmt);
            if rc != 101 && rc != 0 { // DONE=101
                anyhow::bail!("{}", errmsg(db));
            }
            // INSERT prepared
            let ins = CString::new("INSERT INTO oha (url, start, start_latency_correction, end, duration, status, len_bytes, run) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)").unwrap();
            let mut stmt: *mut c_void = ptr::null_mut();
            let rc = sqlite3_prepare_v2(db, ins.as_ptr(), -1, &mut stmt, ptr::null_mut());
            if rc != 0 { anyhow::bail!("{}", errmsg(db)); }
            // Begin transaction for speed (original maybe does). Use exec; ignore result handling differently
            let run_ts = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0) as i64;
            for r in results {
                sqlite3_reset(stmt);
                let curl = CString::new(r.url.clone()).unwrap_or_else(|_| CString::new("").unwrap());
                // TRANSIENT = -1 as destructor pointer
                sqlite3_bind_text(stmt, 1, curl.as_ptr(), -1, -1isize as *mut c_void);
                sqlite3_bind_double(stmt, 2, r.start.duration_since(start).as_secs_f64());
                match r.start_latency_correction {
                    Some(t) => { sqlite3_bind_double(stmt, 3, t.duration_since(start).as_secs_f64()); }
                    None => { sqlite3_bind_null(stmt, 3); }
                }
                sqlite3_bind_double(stmt, 4, r.end.duration_since(start).as_secs_f64());
                sqlite3_bind_double(stmt, 5, r.duration().as_secs_f64());
                sqlite3_bind_int64(stmt, 6, r.status as i64);
                sqlite3_bind_int64(stmt, 7, r.len_bytes as i64);
                sqlite3_bind_int64(stmt, 8, run_ts);
                let rc = sqlite3_step(stmt);
                if rc != 101 && rc != 0 {
                    let e = errmsg(db);
                    sqlite3_finalize(stmt);
                    anyhow::bail!("{}", e);
                }
            }
            sqlite3_finalize(stmt);
            let _ = sqlite3_exec(db, CString::new("").unwrap().as_ptr(), ptr::null(), ptr::null_mut(), ptr::null_mut());
            Ok(())
        };
        let res = run();
        sqlite3_close(db);
        res
    }
}
RS
"}

