    eprintln!("Storing results to {}", db_url);
    unsafe {
        let cpath = CString::new(db_url).unwrap_or_else(|_| CString::new("").unwrap());
        let mut db: *mut c_void = ptr::null_mut();
        let rc = sqlite3_open(cpath.as_ptr(), &mut db);
        if rc != 0 {
            if !db.is_null() { sqlite3_close(db); }
            anyhow::bail!("unable to open database file: {}", db_url);
        }
        let run = || -> anyhow::Result<()> {
            // CREATE TABLE
            let sql = CString::new("CREATE TABLE IF NOT EXISTS oha (\n            url TEXT NOT NULL,\n            start REAL NOT NULL,\n            start_latency_correction REAL,\n            end REAL NOT NULL,\n            duration REAL NOT NULL,\n            status INTEGER NOT NULL,\n            len_bytes INTEGER NOT NULL,\n            run INTEGER NOT NULL\n        )").unwrap();
            let mut stmt: *mut c_void = ptr::null_mut();
            let rc = sqlite3_prepare_v2(db, sql.as_ptr(), -1, &mut stmt, ptr::null_mut());
            if rc != 0 { anyhow::bail!("{}", errmsg(db)); }
            let rc = sqlite3_step(stmt);
            sqlite3_finalize(stmt);
            if rc != 101 && rc != 0 { // DONE=101
                anyhow::bail!("{}", errmsg(db));
            }
            // INSERT prepared
            let ins = CString::new("INSERT INTO oha (url, start, start_latency_correction, end, duration, status, len_bytes, run) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)").unwrap();
