mod aws;
mod client;
mod core;
mod db;
mod dns;
mod http2;
mod humantime;
mod monitor;
mod netio;
mod opts;
mod printer;
mod tls_config;
mod url_generator;

use client::{AwsConfig, BodyGen, Client};
use core::*;
use opts::*;
use std::io::{IsTerminal, Write};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{mpsc, Arc, Mutex};
use std::time::{Duration, Instant};
use url_generator::UrlGenerator;

static CANCELLED: AtomicBool = AtomicBool::new(false);
extern "C" fn on_sigint(_sig: libc::c_int) {
    CANCELLED.store(true, Ordering::SeqCst);
}

fn parse_http_version_opt(s: &str) -> anyhow::Result<HttpVersion> { HttpVersion::parse(s) }

fn validate_aws(opts: &Opts) -> anyhow::Result<Option<AwsConfig>> {
    if let Some(sig) = &opts.aws_sigv4 {
        let Some(auth) = &opts.basic_auth else {
            anyhow::bail!("AWS credentials (--auth) required when using --aws-sigv4");
        };
        let parts: Vec<&str> = auth.split(':').collect();
        if parts.len() != 2 {
            anyhow::bail!("Invalid AWS credentials format. Expected access_key:secret_key");
        }
        let sparts: Vec<&str> = sig.split(':').collect();
        if sparts.len() != 4 || sparts[0] != "aws" || sparts[1] != "amz" {
            anyhow::bail!("Invalid AWS signing params format. Expected aws:amz:region:service");
        }
        Ok(Some(AwsConfig {
            access_key: parts[0].to_string(),
            secret_key: parts[1].to_string(),
            region: sparts[2].to_string(),
            service: sparts[3].to_string(),
            session: opts.aws_session.clone(),
        }))
    } else {
        Ok(None)
    }
}

// ---------- multipart / body ----------

struct FormPart {
    name: String,
    content: Vec<u8>,
    filename: Option<String>,
    content_type: Option<String>,
}

fn build_form(forms: &[String]) -> anyhow::Result<(Vec<u8>, String)> {
    let hex = client::random_hex32();
    let boundary = format!("----formdata-oha-{}", hex);
    let mut parts: Vec<FormPart> = Vec::new();
    for form_str in forms {
        let parse_one = || -> Option<FormPart> {
            let mut segments = form_str.split(';');
            let main = segments.next()?;
            let (name, value) = main.split_once('=')?;
            let mut filename: Option<String> = None;
            let mut content_type: Option<String> = None;
            for seg in segments {
                if seg.is_empty() { continue; }
                if let Some((k, v)) = seg.split_once('=') {
                    match k {
                        "type" => content_type = Some(v.to_string()),
                        "filename" => filename = Some(v.to_string()),
                        _ => {}
                    }
                }
            }
            let content: Vec<u8>;
            if let Some(path) = value.strip_prefix('@') {
                if path.is_empty() { return None; }
                content = std::fs::read(path).ok()?;
                if filename.is_none() {
                    let base = std::path::Path::new(path).file_name().map(|s| s.to_string_lossy().to_string());
                    filename = base;
                    if filename.is_none() { return None; }
                }
            } else if value.starts_with('<') {
                return None;
            } else {
                content = value.as_bytes().to_vec();
            }
            Some(FormPart { name: name.to_string(), content, filename, content_type })
        };
        match parse_one() {
            Some(p) => parts.push(p),
            None => anyhow::bail!("Failed to parse form data: {}", form_str),
        }
    }
    let mut body: Vec<u8> = Vec::new();
    for p in &parts {
        body.extend_from_slice(format!("--{}\r\n", boundary).as_bytes());
        let mut disp = format!("Content-Disposition: form-data; name=\"{}\"", p.name);
        if let Some(fn_) = &p.filename {
            disp.push_str(&format!("; filename=\"{}\"", fn_));
        }
        disp.push_str("\r\n");
        body.extend_from_slice(disp.as_bytes());
        if let Some(ct) = &p.content_type {
            body.extend_from_slice(format!("Content-Type: {}\r\n", ct).as_bytes());
        }
        body.extend_from_slice(b"\r\n");
        body.extend_from_slice(&p.content);
        body.extend_from_slice(b"\r\n");
    }
    body.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
    Ok((body, format!("multipart/form-data; boundary={}", boundary)))
}

fn build_body_gen(opts: &Opts) -> anyhow::Result<(BodyGen, Option<String>)> {
    if let Some(path) = &opts.body_path {
        let data = std::fs::read(path)?;
        Ok((BodyGen::Static(Arc::new(data)), None))
    } else if let Some(path) = &opts.body_path_lines {
        let data = std::fs::read(path).unwrap_or_default();
        let text = String::from_utf8(data).unwrap_or_default();
        let lines: Vec<Vec<u8>> = text.lines().map(|l| l.as_bytes().to_vec()).collect();
        Ok((BodyGen::Lines(lines), None))
    } else if !opts.form.is_empty() {
        let (body, ct) = build_form(&opts.form)?;
        Ok((BodyGen::Static(Arc::new(body)), Some(ct)))
    } else if let Some(s) = &opts.body_string {
        Ok((BodyGen::Static(Arc::new(s.as_bytes().to_vec())), None))
    } else {
        Ok((BodyGen::Static(Arc::new(Vec::new())), None))
    }
}

fn hv(s: &str) -> anyhow::Result<Vec<u8>> {
    validate_header_value(s.as_bytes()).map_err(|e| anyhow::anyhow!("{}", e))?;
    Ok(s.as_bytes().to_vec())
}

fn build_base_headers(opts: &Opts, form_content_type: Option<String>, http_version: HttpVersion, has_aws: bool) -> anyhow::Result<Headers> {
    let mut h: Headers = Vec::new();
    let accept = opts.accept_header.clone().unwrap_or_else(|| "*/*".to_string());
    headers_insert(&mut h, "accept", hv(&accept)?);
    if !opts.disable_compression {
        headers_insert(&mut h, "accept-encoding", b"gzip, compress, deflate, br".to_vec());
    }
    headers_insert(&mut h, "user-agent", b"oha/1.12.1".to_vec());
    if let Some(ct) = form_content_type {
        headers_insert(&mut h, "content-type", hv(&ct)?);
    }
    if let Some(ct) = &opts.content_type {
        headers_insert(&mut h, "content-type", hv(ct)?);
    }
    if !has_aws {
        if let Some(auth) = &opts.basic_auth {
            if auth.split_once(':').is_none() {
                anyhow::bail!("Parse auth");
            }
            use base64::Engine;
            let encoded = base64::engine::general_purpose::STANDARD.encode(auth.as_bytes());
            headers_insert(&mut h, "authorization", format!("Basic {}", encoded).into_bytes());
        }
    }
    if opts.disable_keepalive && !http_version.is_http2() {
        headers_insert(&mut h, "connection", b"close".to_vec());
    }
    if let Some(host) = &opts.host {
        headers_insert(&mut h, "host", hv(host)?);
    }
    for kv in &opts.headers {
        headers_insert(&mut h, &kv.name, kv.value.clone());
    }
    Ok(h)
}

// ---------- debug formatting ----------

fn escape_body_bytes(bytes: &[u8]) -> String {
    let mut out = String::new();
    for &b in bytes {
        match b {
            b'\t' => out.push_str("\\t"),
            b'\n' => out.push_str("\\n"),
            b'\r' => out.push_str("\\r"),
            b'"' => out.push_str("\\\""),
            b'\\' => out.push_str("\\\\"),
            0 => out.push_str("\\0"),
            0x20..=0x7e => out.push(b as char),
            _ => out.push_str(&format!("\\x{:02x}", b)),
        }
    }
    out
}
fn escape_header_value_dbg(bytes: &[u8]) -> String {
    let mut out = String::new();
    for &b in bytes {
        match b {
            b'"' => out.push_str("\\\""),
            0x09 | 0x20..=0x7e => out.push(b as char),
            _ => out.push_str(&format!("\\x{:02x}", b)),
        }
    }
    out
}

fn format_debug_request(spec: &RequestSpec) -> String {
    let mut s = String::new();
    s.push_str("Request {\n");
    s.push_str(&format!("    method: {},\n", spec.method));
    s.push_str(&format!("    uri: {},\n", spec.uri_display));
    s.push_str(&format!("    version: {},\n", spec.version.as_str().replace("HTTP/2.0", "HTTP/2.0")));
    s.push_str("    headers: {\n");
    for (name, value) in &spec.headers {
        s.push_str(&format!("        \"{}\": \"{}\",\n", name, escape_header_value_dbg(value)));
    }
    s.push_str("    },\n");
    if spec.body.is_empty() {
        s.push_str("    body: Full {\n        data: None,\n    },\n");
    } else {
        s.push_str(&format!("    body: Full {{\n        data: Some(\n            b\"{}\",\n        ),\n    }},\n", escape_body_bytes(&spec.body)));
    }
    s.push_str("}\n");
    s
}
fn format_debug_response(resp: &ResponseData) -> String {
    let mut s = String::new();
    s.push_str("Response {\n");
    s.push_str(&format!("    status: {},\n", resp.status));
    s.push_str(&format!("    version: {},\n", resp.version.as_str()));
    s.push_str("    headers: {\n");
    for (name, value) in &resp.headers {
        s.push_str(&format!("        \"{}\": \"{}\",\n", name, escape_header_value_dbg(value)));
    }
    s.push_str("    },\n");
    s.push_str(&format!("    body: b\"{}\",\n", escape_body_bytes(&resp.body)));
    s.push_str("}\n");
    s
}

// ---------- run ----------

enum OutputWriter {
    Stdout(std::io::Stdout),
    File(std::fs::File),
}
impl Write for OutputWriter {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match self { OutputWriter::Stdout(s) => s.write(buf), OutputWriter::File(f) => f.write(buf) }
    }
    fn flush(&mut self) -> std::io::Result<()> {
        match self { OutputWriter::Stdout(s) => s.flush(), OutputWriter::File(f) => f.flush() }
    }
}

fn main() -> anyhow::Result<()> {
    let opts = parse_opts();
    run(opts)
}

fn run(opts: Opts) -> anyhow::Result<()> {
    let aws = validate_aws(&opts)?;
    // HTTP version
    let http_version = if opts.http2 {
        if opts.http_version.is_some() {
            anyhow::bail!("--http2 and --http-version are exclusive");
        }
        HttpVersion::V2
    } else if let Some(v) = &opts.http_version {
        parse_http_version_opt(v)?
    } else {
        HttpVersion::V11
    };
    if matches!(http_version, HttpVersion::V3) {
        anyhow::bail!("Your Oha instance has not been built with HTTP/3 support. Try recompiling with the feature enabled.");
    }
    let proxy_http_version = if opts.proxy_http2 {
        if opts.proxy_http_version.is_some() {
            anyhow::bail!("--http2 and --http-version are exclusive");
        }
        HttpVersion::V2
    } else if let Some(v) = &opts.proxy_http_version {
        parse_http_version_opt(v)?
    } else {
        HttpVersion::V11
    };
    if matches!(proxy_http_version, HttpVersion::V3) {
        anyhow::bail!("Your Oha instance has not been built with HTTP/3 support. Try recompiling with the feature enabled.");
    }

    let opts = Arc::new(opts);
    let url_gen = UrlGenerator::new(&opts.url, opts.rand_regex_url, opts.urls_from_file, opts.max_repeat)?;
    if let Some(n) = opts.dump_urls {
        for _ in 0..n {
            let url = url_gen.generate()?;
            println!("{}", url);
        }
        return Ok(());
    }

    let (body_gen, form_ct) = build_body_gen(&opts)?;
    let base_headers = build_base_headers(&opts, form_ct, http_version, aws.is_some())?;
    let tls_cfg = tls_config::TlsConfig::build(opts.cacert.as_deref(), opts.cert.as_deref(), opts.key.as_deref(), opts.insecure)?;

    let cancelled = Arc::new(AtomicBool::new(false));
    // Install SIGINT handler for non-debug runs
    if !opts.debug {
        unsafe {
            // Use the global flag plus per-run flag: handler sets global; a watcher mirrors it? Instead point client at a combined flag:
            libc::signal(libc::SIGINT, on_sigint as usize);
        }
    }
    // Wrap cancellation: client/workers check both the per-run Arc and the global static via a combined Arc? 
    // Simpler: spawn a thread that mirrors global into the Arc.
    let mirror = cancelled.clone();
    std::thread::spawn(move || loop {
        if CANCELLED.load(Ordering::Relaxed) { mirror.store(true, Ordering::SeqCst); break; }
        if mirror.load(Ordering::Relaxed) { CANCELLED.store(true, Ordering::Relaxed); }
        std::thread::sleep(Duration::from_millis(5));
    });

    let client = Arc::new(Client {
        opts: opts.clone(),
        base_headers,
        body_gen: Arc::new(body_gen),
        tls: tls_cfg,
        dns: dns::DnsCache::new(),
        http_version,
        proxy_http_version,
        aws,
        cancelled: cancelled.clone(),
    });

    // pre-lookup
    if !opts.no_pre_lookup {
        let url = url_gen.generate()?;
        client.pre_lookup(&url).map_err(|e| anyhow::anyhow!("{}", e.msg()))?;
    }

    // sample URL for mode detection / startup validation like original's initial request build
    let sample_url = url_gen.generate()?;

    // output writer (after pre-lookup)
    let stdout_is_tty = std::io::stdout().is_terminal();
    let mut writer: OutputWriter = if let Some(path) = &opts.output {
        OutputWriter::File(std::fs::File::create(path)?)
    } else {
        OutputWriter::Stdout(std::io::stdout())
    };
    let use_color = !opts.no_color && opts.output.is_none() && stdout_is_tty && matches!(opts.output_format, OutputFormat::Text);

    if opts.debug {
        return run_debug(&client, &url_gen, &mut writer, sample_url);
    }

    let is_http2_mode = client.effective_version_for_url(&sample_url).is_http2();
    let use_tui = !opts.no_tui && stdout_is_tty;

    // Establish the start instant as late as possible
    let (stats, start) = if is_http2_mode {
        http2::run_load(client.clone(), &url_gen, cancelled.clone(), use_tui, &opts)?
    } else if use_tui {
        monitor::run_with_tui(client.clone(), &url_gen, cancelled.clone(), &opts)?
    } else {
        run_load_http1(client.clone(), &url_gen, cancelled.clone(), &opts, None)?
    };

    // sort success by start for output/db
    let mut stats = stats;
    stats.success.sort_by_key(|r| r.start);

    printer::print_results(&mut writer, &stats, opts.output_format, opts.time_unit, start, opts.stats_success_breakdown, use_color)?;
    writer.flush()?;

    if let Some(db_url) = &opts.db_url {
        db::store(db_url, &stats.success, start)?;
    }
    Ok(())
}

fn run_debug(client: &Client, url_gen: &UrlGenerator, writer: &mut OutputWriter, _sample: url::Url) -> anyhow::Result<()> {
    let url = url_gen.generate()?;
    let body = client.body_gen.generate();
    let is_http2 = client.effective_version_for_url(&url).is_http2();
    let result: Result<ResponseData, ReqError> = if is_http2 {
        http2::debug_request(client, &url, body, writer)
    } else {
        let mut slot: Option<client::BufferedConn> = None;
        let ctx = TimeCtx::new(None);
        let start = Instant::now();
        // Print request via hook inside a custom flow: build spec first for display, then do_request prints its own spec.
        // We use do_request_with_hook through a writer bridge: since writer is not Sync, do it here by building the same spec.
        let spec = client.build_request(&url, body.clone());
        write!(writer, "{}", format_debug_request(&spec))?;
        writer.flush()?;
        let r = client.do_request(&mut slot, &url, body, start, None, &ctx, true, true);
        match r {
            Ok((_res, resp, _spec)) => Ok(resp.unwrap()),
            Err(e) => Err(e),
        }
    };
    match result {
        Ok(resp) => {
            write!(writer, "{}", format_debug_response(&resp))?;
            writer.flush()?;
            Ok(())
        }
        Err(e) => Err(anyhow::anyhow!("{}", e.msg())),
    }
}

pub struct SharedRun {
    pub next_job: AtomicUsize,
    pub aborted: AtomicUsize,
}

pub fn run_load_http1(client: Arc<Client>, url_gen: &UrlGenerator, cancelled: Arc<AtomicBool>, opts: &Opts, live_tx: Option<mpsc::Sender<Result<RequestResult, String>>>) -> anyhow::Result<(printer::StatsData, Instant)> {
    let start = Instant::now();
    let deadline = opts.duration.map(|d| start + d);
    let wait = opts.wait_ongoing_requests_after_deadline;
    let n_workers = if let Some(_) = opts.duration {
        opts.n_connections
    } else {
        opts.n_connections.min(opts.n_requests)
    };
    let (tx, rx) = mpsc::channel::<Result<RequestResult, String>>();
    let shared = Arc::new(SharedRun { next_job: AtomicUsize::new(0), aborted: AtomicUsize::new(0) });

    // Rate limiting tokens
    let rate_mode = rate_limit_mode(opts);
    let (token_tx_opt, token_rx) = setup_tokens(opts, rate_mode, start, cancelled.clone());
    let token_rx = token_rx.map(|r| Arc::new(Mutex::new(r)));

    let url_gen_shared: &UrlGenerator = url_gen;
    // UrlGenerator needs to be shared across threads: it's not Sync due to? Hir/Vec are Sync. Use unsafe wrapper via Arc with a Mutex for generate? generate takes &self and uses thread_rng, safe to share if Sync. We'll wrap in a struct in worker closures by referencing it through a raw pointer wrapper.
    let url_gen_arc = SyncPtr(url_gen_shared as *const UrlGenerator);

    let mut handles = Vec::new();
    for _ in 0..n_workers {
        let client = client.clone();
        let tx = tx.clone();
        let live_tx = live_tx.clone();
        let shared = shared.clone();
        let cancelled = cancelled.clone();
        let token_rx = token_rx.clone();
        let gen_ptr = url_gen_arc.clone();
        let handle = std::thread::Builder::new().stack_size(512 * 1024).spawn(move || {
            let gen: &UrlGenerator = unsafe { &*gen_ptr.0 };
            let mut slot: Option<client::BufferedConn> = None;
            loop {
                if cancelled.load(Ordering::Relaxed) { break; }
                // Job / token acquisition
                let scheduled: Option<Instant>;
                if let Some(trx) = &token_rx {
                    match acquire_token(trx, deadline, wait, &cancelled) {
                        TokenOutcome::Token(t) => scheduled = Some(t),
                        TokenOutcome::Done => break,
                        TokenOutcome::Aborted => { shared.aborted.fetch_add(1, Ordering::Relaxed); break; }
                        TokenOutcome::Cancelled => break,
                    }
                } else if deadline.is_some() {
                    if let Some(dl) = deadline {
                        if Instant::now() >= dl {
                            if !wait { shared.aborted.fetch_add(1, Ordering::Relaxed); }
                            break;
                        }
                    }
                    scheduled = None;
                } else {
                    let job = shared.next_job.fetch_add(1, Ordering::Relaxed);
                    if job >= client.opts.n_requests { break; }
                    scheduled = None;
                }
                if cancelled.load(Ordering::Relaxed) { break; }
                let url = match gen.generate() {
                    Ok(u) => u,
                    Err(e) => {
                        let msg = format!("{}", e);
                        let _ = tx.send(Err(msg.clone()));
                        if let Some(l) = &live_tx { let _ = l.send(Err(msg)); }
                        continue;
                    }
                };
                let body = client.body_gen.generate();
                let req_start = Instant::now();
                let start_lat = if token_rx.is_some() && !client.opts.latency_correction { scheduled } else { None };
                let mut ctx = TimeCtx::new(Some(cancelled.clone()));
                if let Some(t) = client.opts.timeout { ctx.deadlines.push((req_start + t, DeadlineKind::Timeout)); }
                if let Some(dl) = deadline { if !wait { ctx.deadlines.push((dl, DeadlineKind::Aborted)); } }
                let res = client.do_request(&mut slot, &url, body, req_start, start_lat, &ctx, false, false);
                match res {
                    Ok((result, _, _)) => {
                        if let Some(l) = &live_tx { let _ = l.send(Ok(result.clone())); }
                        let _ = tx.send(Ok(result));
                    }
                    Err(ReqError::Cancelled) => break,
                    Err(ReqError::AbortedDueToDeadline) => { shared.aborted.fetch_add(1, Ordering::Relaxed); break; }
                    Err(e) => {
                        let msg = e.msg();
                        if let Some(l) = &live_tx { let _ = l.send(Err(msg.clone())); }
                        let _ = tx.send(Err(msg));
                    }
                }
            }
        }).expect("failed to spawn worker");
        handles.push(handle);
    }
    drop(tx);
    // Token sender thread is detached via its Stop flag inside setup_tokens (it ends after n tokens or when cancelled/deadline passed)
    let _ = token_tx_opt;
    let mut success = Vec::new();
    let mut errors: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for msg in rx {
        match msg {
            Ok(r) => success.push(r),
            Err(e) => { *errors.entry(e).or_insert(0) += 1; }
        }
    }
    for h in handles { let _ = h.join(); }
    let total = start.elapsed();
    let aborted = shared.aborted.load(Ordering::Relaxed);
    if aborted > 0 {
        *errors.entry("aborted due to deadline".to_string()).or_insert(0) += aborted;
    }
    Ok((printer::StatsData { success, errors, total_time: total, aborted }, start))
}

#[derive(Clone)]
struct SyncPtr(*const UrlGenerator);
unsafe impl Send for SyncPtr {}
unsafe impl Sync for SyncPtr {}

#[derive(PartialEq)]
pub enum RateMode { None, Qps, Burst }

pub fn rate_limit_mode(opts: &Opts) -> RateMode {
    if let Some(q) = opts.query_per_second {
        if q != 0.0 { return RateMode::Qps; }
    }
    if opts.burst_duration.is_some() { return RateMode::Burst; }
    RateMode::None
}

pub fn setup_tokens(opts: &Opts, mode: RateMode, start: Instant, cancelled: Arc<AtomicBool>) -> (Option<Arc<AtomicBool>>, Option<mpsc::Receiver<Instant>>) {
    match mode {
        RateMode::None => (None, None),
        RateMode::Qps => {
            let q = opts.query_per_second.unwrap();
            // This panics for negative/NaN like original (Duration::from_secs_f64)
            let interval = Duration::from_secs_f64(1.0 / q);
            let (tx, rx) = mpsc::channel::<Instant>();
            let n = if opts.duration.is_some() { None } else { Some(opts.n_requests) };
            let stop = Arc::new(AtomicBool::new(false));
            let stop2 = stop.clone();
            std::thread::spawn(move || {
                let mut i: u64 = 0;
                loop {
                    if cancelled.load(Ordering::Relaxed) || stop2.load(Ordering::Relaxed) { break; }
                    if let Some(total) = n { if i as usize >= total { break; } }
                    let sched = start + interval * (i as u32);
                    // sleep until sched in small increments
                    loop {
                        if cancelled.load(Ordering::Relaxed) || stop2.load(Ordering::Relaxed) { return; }
                        let now = Instant::now();
                        if now >= sched { break; }
                        std::thread::sleep((sched - now).min(Duration::from_millis(5)));
                    }
                    if tx.send(sched).is_err() { break; }
                    i += 1;
                }
            });
            (Some(stop), Some(rx))
        }
        RateMode::Burst => {
            let delay = opts.burst_duration.unwrap();
            let rate = opts.burst_requests.unwrap_or(1);
            let (tx, rx) = mpsc::channel::<Instant>();
            let n = if opts.duration.is_some() { None } else { Some(opts.n_requests) };
            let stop = Arc::new(AtomicBool::new(false));
            let stop2 = stop.clone();
            std::thread::spawn(move || {
                let mut sent: usize = 0;
                let mut group: u64 = 1;
                loop {
                    if cancelled.load(Ordering::Relaxed) || stop2.load(Ordering::Relaxed) { break; }
                    if let Some(total) = n { if sent >= total { break; } }
                    let sched = start + delay * (group as u32);
                    loop {
                        if cancelled.load(Ordering::Relaxed) || stop2.load(Ordering::Relaxed) { return; }
                        let now = Instant::now();
                        if now >= sched { break; }
                        std::thread::sleep((sched - now).min(Duration::from_millis(5)));
                    }
                    for _ in 0..rate {
                        if let Some(total) = n { if sent >= total { break; } }
                        if tx.send(sched).is_err() { return; }
                        sent += 1;
                    }
                    group += 1;
                }
            });
            (Some(stop), Some(rx))
        }
    }
}

pub enum TokenOutcome { Token(Instant), Done, Aborted, Cancelled }

pub fn acquire_token(rx: &Arc<Mutex<mpsc::Receiver<Instant>>>, deadline: Option<Instant>, wait: bool, cancelled: &AtomicBool) -> TokenOutcome {
    loop {
        if cancelled.load(Ordering::Relaxed) { return TokenOutcome::Cancelled; }
        if let Some(dl) = deadline {
            if Instant::now() >= dl {
                return if wait { TokenOutcome::Done } else { TokenOutcome::Aborted };
            }
        }
        // Lock only briefly? We need recv with timeout; holding lock during wait serializes workers but tokens are sequential.
        let guard = rx.lock().unwrap();
        match guard.recv_timeout(Duration::from_millis(5)) {
            Ok(t) => return TokenOutcome::Token(t),
            Err(mpsc::RecvTimeoutError::Timeout) => { drop(guard); continue; }
            Err(mpsc::RecvTimeoutError::Disconnected) => return TokenOutcome::Done,
        }
    }
}
RS
"}

actions.command:
cat > src/main.rs <<'RS'
mod aws;
mod client;
mod core;
mod db;
mod dns;
mod http2;
mod humantime;
mod monitor;
mod netio;
