{"command":"cat >> src/netio.rs <<'RS'

impl AnyStream {
    // Ok(Some(n)) read, Ok(None) would block, Ok(Some(0)) EOF
    pub fn try_read_some(&mut self, buf: &mut [u8]) -> Result<Option<usize>, ReqError> {
        match self {
            AnyStream::Tcp(s) => match s.read(buf) {
                Ok(n) => Ok(Some(n)),
                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => Ok(None),
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => Ok(None),
                Err(e) => Err(ReqError::from(e)),
            },
            AnyStream::Unix(s) => match s.read(buf) {
                Ok(n) => Ok(Some(n)),
                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => Ok(None),
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => Ok(None),
                Err(e) => Err(ReqError::from(e)),
            },
            AnyStream::Tls(t) => {
                let ret = tls::ssl_read_once(t.raw.ssl, buf);
                if ret > 0 { return Ok(Some(ret as usize)); }
                let code = tls::ssl_get_error(t.raw.ssl, ret);
                match code {
                    2 | 3 => Ok(None),
                    6 => Ok(Some(0)),
                    5 => {
                        if ret == 0 { Ok(Some(0)) } else {
                            let e = io::Error::last_os_error();
                            if matches!(e.raw_os_error(), Some(libc::ECONNRESET) | Some(libc::EPIPE) | Some(0)) { Ok(Some(0)) } else { Err(ReqError::from(e)) }
                        }
                    }
                    _ => Ok(Some(0)),
                }
            }
        }
    }
    pub fn try_write_some(&mut self, buf: &[u8]) -> Result<Option<usize>, ReqError> {
        match self {
            AnyStream::Tcp(s) => match s.write(buf) {
                Ok(n) => Ok(Some(n)),
                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => Ok(None),
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => Ok(None),
                Err(e) => Err(ReqError::from(e)),
            },
            AnyStream::Unix(s) => match s.write(buf) {
                Ok(n) => Ok(Some(n)),
                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => Ok(None),
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => Ok(None),
                Err(e) => Err(ReqError::from(e)),
            },
            AnyStream::Tls(t) => {
                let ret = tls::ssl_write_once(t.raw.ssl, buf);
                if ret > 0 { return Ok(Some(ret as usize)); }
                let code = tls::ssl_get_error(t.raw.ssl, ret);
                match code {
                    2 | 3 => Ok(None),
                    5 => {
                        if ret == 0 { Err(ReqError::Msg("tls handshake eof".to_string())) } else { Err(ReqError::from(io::Error::last_os_error())) }
                    }
                    _ => Err(ReqError::Msg(tls::map_tls_error(t.raw.ssl, &t.host, None))),
                }
            }
        }
    }
}

pub fn poll_once(fd: RawFd, want_read: bool, want_write: bool, timeout_ms: i32) -> (bool, bool) {
    let mut events = 0;
    if want_read { events |= libc::POLLIN; }
    if want_write { events |= libc::POLLOUT; }
    let mut pfd = libc::pollfd { fd, events, revents: 0 };
    let r = unsafe { libc::poll(&mut pfd, 1, timeout_ms) };
    if r > 0 {
        (pfd.revents & (libc::POLLIN | libc::POLLHUP | libc::POLLERR) != 0, pfd.revents & libc::POLLOUT != 0)
    } else { (false, false) }
}
RS
