pub struct RawEstablish {
    pub stream: AnyStream,
    pub key: String,
    pub dns_lookup: Duration,
    pub dns_dialup: Duration,
    pub initial: Vec<u8>,
}
impl Client {
    pub fn establish_any(&self, url: &Url, ctx: &TimeCtx) -> Result<RawEstablish, ReqError> {
        let est = self.establish(url, ctx)?;
        Ok(RawEstablish {
            stream: est.conn.stream,
            key: est.conn.key,
            dns_lookup: est.dns_lookup,
            dns_dialup: est.dns_dialup,
            initial: est.conn.buf[est.conn.pos..].to_vec(),
        })
    }
    pub fn expected_key_pub(&self, url: &Url) -> Result<String, ReqError> { self.expected_key(url) }
}
