    ("server", ""), ("set-cookie", ""), ("strict-transport-security", ""), ("transfer-encoding", ""),
    ("user-agent", ""), ("vary", ""), ("via", ""), ("www-authenticate", ""),
];

fn huff_map() -> &'static HashMap<(u8, u32), u8> {
    static MAP: OnceLock<HashMap<(u8, u32), u8>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
        for i in 0..256 { m.insert((HUFF_LENS[i], HUFF_CODES[i]), i as u8); }
        m
    })
}

pub fn huffman_decode(data: &[u8]) -> Result<Vec<u8>, String> {
    let map = huff_map();
    let mut out = Vec::new();
    let mut code: u32 = 0;
    let mut len: u8 = 0;
    for &byte in data {
        for shift in (0..8).rev() {
            let bit = ((byte >> shift) & 1) as u32;
            code = (code << 1) | bit;
            len += 1;
            if let Some(&sym) = map.get(&(len, code)) {
                out.push(sym);
                code = 0; len = 0;
