    if len > 0 {
        // Padding must be all ones (EOS prefix)
        let expected = (1u32 << len) - 1;
        if code != expected { return Err("http2 error".to_string()); }
    }
    Ok(out)
}

pub fn encode_integer(out: &mut Vec<u8>, prefix_bits: u8, prefix_value: u8, value: u64) {
    let max_prefix = (1u64 << prefix_bits) - 1;
    if value < max_prefix {
        out.push(prefix_value | value as u8);
    } else {
        out.push(prefix_value | max_prefix as u8);
        let mut v = value - max_prefix;
        while v >= 128 {
            out.push(((v % 128) as u8) + 128);
            v /= 128;
        }
        out.push(v as u8);
    }
}
pub fn encode_string(out: &mut Vec<u8>, data: &[u8]) {
    encode_integer(out, 7, 0, data.len() as u64);
    out.extend_from_slice(data);
}
pub fn encode_indexed(out: &mut Vec<u8>, idx: u64) { encode_integer(out, 7, 0x80, idx); }
pub fn encode_literal_name_index(out: &mut Vec<u8>, name_idx: u64, value: &[u8]) {
    encode_integer(out, 4, 0x00, name_idx);
    encode_string(out, value);
}
pub fn encode_literal(out: &mut Vec<u8>, name: &[u8], value: &[u8]) {
    encode_integer(out, 4, 0x00, 0);
    encode_string(out, name);
    encode_string(out, value);
}

pub struct Decoder {
    dynamic: VecDeque<(Vec<u8>, Vec<u8>)>,
    dynamic_size: usize,
    max_size: usize,
}
impl Decoder {
    pub fn new() -> Self { Self { dynamic: VecDeque::new(), dynamic_size: 0, max_size: 4096 } }
    fn entry_size(name: &[u8], value: &[u8]) -> usize { name.len() + value.len() + 32 }
    fn evict(&mut self) {
        while self.dynamic_size > self.max_size {
            if let Some((n, v)) = self.dynamic.pop_back() {
                self.dynamic_size -= Self::entry_size(&n, &v);
            } else { break; }
        }
    }
    fn insert(&mut self, name: Vec<u8>, value: Vec<u8>) {
        let sz = Self::entry_size(&name, &value);
        if sz > self.max_size {
            self.dynamic.clear(); self.dynamic_size = 0; return;
        }
        self.dynamic.push_front((name, value));
        self.dynamic_size += sz;
        self.evict();
    }
    fn get(&self, idx: u64) -> Result<(Vec<u8>, Vec<u8>), String> {
        if idx == 0 { return Err("http2 error".to_string()); }
        if idx <= 61 {
            let (n, v) = STATIC_TABLE[(idx - 1) as usize];
            Ok((n.as_bytes().to_vec(), v.as_bytes().to_vec()))
        } else {
            let di = (idx - 62) as usize;
            self.dynamic.get(di).cloned().ok_or_else(|| "http2 error".to_string())
        }
    }
    fn decode_integer(&self, data: &[u8], pos: &mut usize, prefix_bits: u8) -> Result<u64, String> {
        if *pos >= data.len() { return Err("http2 error".to_string()); }
        let mask = (1u16 << prefix_bits) - 1;
        let mut value = (data[*pos] as u16 & mask) as u64;
        *pos += 1;
        if value < mask as u64 { return Ok(value); }
        let mut shift = 0u32;
        loop {
            if *pos >= data.len() || shift > 56 { return Err("http2 error".to_string()); }
            let b = data[*pos]; *pos += 1;
            value += ((b & 0x7f) as u64) << shift;
            shift += 7;
            if b & 0x80 == 0 { break; }
        }
        Ok(value)
    }
    fn decode_string(&self, data: &[u8], pos: &mut usize) -> Result<Vec<u8>, String> {
        if *pos >= data.len() { return Err("http2 error".to_string()); }
        let huff = data[*pos] & 0x80 != 0;
        let len = self.decode_integer(data, pos, 7)? as usize;
        if *pos + len > data.len() { return Err("http2 error".to_string()); }
        let raw = &data[*pos..*pos + len];
        *pos += len;
        if huff { huffman_decode(raw) } else { Ok(raw.to_vec()) }
    }
    pub fn decode(&mut self, data: &[u8]) -> Result<Vec<(Vec<u8>, Vec<u8>)>, String> {
        let mut out = Vec::new();
        let mut pos = 0usize;
        while pos < data.len() {
            let b = data[pos];
            if b & 0x80 != 0 {
                let idx = self.decode_integer(data, &mut pos, 7)?;
                out.push(self.get(idx)?);
            } else if b & 0x40 != 0 {
                let idx = self.decode_integer(data, &mut pos, 6)?;
                let name = if idx == 0 { self.decode_string(data, &mut pos)? } else { self.get(idx)?.0 };
                let value = self.decode_string(data, &mut pos)?;
                self.insert(name.clone(), value.clone());
                out.push((name, value));
            } else if b & 0x20 != 0 {
                let new_size = self.decode_integer(data, &mut pos, 5)? as usize;
                self.max_size = new_size;
                self.evict();
            } else {
                // 0000 without index or 0001 never indexed
                let idx = self.decode_integer(data, &mut pos, 4)?;
                let name = if idx == 0 { self.decode_string(data, &mut pos)? } else { self.get(idx)?.0 };
                let value = self.decode_string(data, &mut pos)?;
                out.push((name, value));
            }
        }
        Ok(out)
    }
}
