// Frame types
const FT_DATA: u8 = 0;
const FT_HEADERS: u8 = 1;
const FT_PRIORITY: u8 = 2;
const FT_RST: u8 = 3;
const FT_SETTINGS: u8 = 4;
const FT_PUSH: u8 = 5;
const FT_PING: u8 = 6;
const FT_GOAWAY: u8 = 7;
const FT_WINDOW: u8 = 8;
const FT_CONTINUATION: u8 = 9;

pub struct RawH2 {
    pub status: u16,
    pub headers: Headers,
    pub len_bytes: usize,
    pub body: Vec<u8>,
    pub first_byte: Option<Instant>,
}

struct Job {
