    ctx: TimeCtx,
    collect_body: bool,
    reply: mpsc::Sender<Result<RawH2, ReqError>>,
}

struct StreamJob {
    spec_method: String,
    ctx: TimeCtx,
    collect_body: bool,
    reply: Option<mpsc::Sender<Result<RawH2, ReqError>>>,
    status: Option<u16>,
    headers: Headers,
    body: Vec<u8>,
    len_bytes: usize,
