            if let Some(mut sj) = self.streams.remove(&id) {
                if let Some(reply) = sj.reply.take() {
                    let e = match err { ReqError::Msg(s) => ReqError::Msg(s.clone()), ReqError::Timeout => ReqError::Timeout, ReqError::Cancelled => ReqError::Cancelled, ReqError::AbortedDueToDeadline => ReqError::AbortedDueToDeadline };
