            FT_WINDOW => {
                if payload.len() == 4 {
                    let inc = u32::from_be_bytes([payload[0], payload[1], payload[2], payload[3]]) & 0x7fffffff;
                    if sid == 0 { self.conn_window += inc as i64; }
                    else if let Some(sj) = self.streams.get_mut(&sid) { sj.send_window += inc as i64; }
                }
            }
            FT_PING => {
                if flags & 0x1 == 0 && payload.len() == 8 { self.queue_frame(FT_PING, 0x1, 0, payload); }
            }
            FT_GOAWAY => {
                self.conn_error = Some("http2 error".to_string());
            }
            FT_RST => {
                if let Some(mut sj) = self.streams.remove(&sid) {
                    if let Some(reply) = sj.reply.take() { let _ = reply.send(Err(ReqError::Msg("http2 error".to_string()))); }
                }
            }
            FT_HEADERS | FT_PUSH => {
                // Extract header block fragment considering padding/priority
                let mut p = payload;
                let mut pad_len = 0usize;
                if flags & 0x8 != 0 { // PADDED
                    if p.is_empty() { self.conn_error = Some("http2 error".into()); return; }
                    pad_len = p[0] as usize; p = &p[1..];
                }
                if ty == FT_HEADERS && flags & 0x20 != 0 { // PRIORITY
                    if p.len() < 5 { self.conn_error = Some("http2 error".into()); return; }
                    p = &p[5..];
                }
                if ty == FT_PUSH {
                    if p.len() < 4 { self.conn_error = Some("http2 error".into()); return; }
                    p = &p[4..];
                }
                let frag_len = p.len().saturating_sub(pad_len);
                let frag = &p[..frag_len];
