                if !self.handshake_done && !handshake_error_sent {
                    if let Some(reply) = self.handshake_reply.take() { let _ = reply.send(Err(ReqError::Msg(errmsg.clone()))); }
                }
                self.fail_all(&ReqError::Msg(errmsg));
                break;
            }
