pub fn run_h2_with_tui(client: Arc<Client>, gen: &UrlGenerator, cancelled: Arc<AtomicBool>, opts: &Opts) -> anyhow::Result<(StatsData, Instant)> {
    run_tui_generic(client, gen, cancelled, opts, true)
}

fn run_tui_generic(client: Arc<Client>, gen: &UrlGenerator, cancelled: Arc<AtomicBool>, opts: &Opts, http2: bool) -> anyhow::Result<(StatsData, Instant)> {
    let use_color = !opts.no_color;
    let gen_addr = gen as *const UrlGenerator as usize;
    let opts_clone = opts.clone();
    let client_clone = client.clone();
    let cancelled_clone = cancelled.clone();
    let (live_tx, live_rx) = mpsc::channel::<Result<RequestResult, String>>();
    let (final_tx, final_rx) = mpsc::channel::<anyhow::Result<(StatsData, Instant)>>();
    // Terminal setup (before starting load like original)
    enable_raw_mode().ok();
    let mut stdout = std::io::stdout();
    let _ = stdout.execute(EnterAlternateScreen);
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    let _ = terminal.hide_cursor();
    let _ = terminal.clear();

    let monitor_start = Instant::now();
    std::thread::spawn(move || {
        let gen_ref: &UrlGenerator = unsafe { &*(gen_addr as *const UrlGenerator) };
        let res = if http2 {
            crate::http2::run_load_inner(client_clone, gen_ref, cancelled_clone, &opts_clone, Some(live_tx))
        } else {
            crate::run_load_http1(client_clone, gen_ref, cancelled_clone, &opts_clone, Some(live_tx))
        };
        let _ = final_tx.send(res);
    });

    let fps = if opts.fps == 0 { 16 } else { opts.fps };
    let frame_interval = Duration::from_secs(1) / (fps as u32);
    let mut mode = Mode::Auto;
    let mut data = MonitorData { success: Vec::new(), errors: BTreeMap::new() };
    let mut final_result: Option<anyhow::Result<(StatsData, Instant)>> = None;

    loop {
        // drain live results
        loop {
            match live_rx.try_recv() {
                Ok(Ok(r)) => data.success.push(r),
                Ok(Err(e)) => { *data.errors.entry(e).or_insert(0) += 1; }
                Err(_) => break,
            }
        }
        if let Ok(res) = final_rx.try_recv() {
            final_result = Some(res);
            break;
        }
        let elapsed_start = monitor_start;
        // draw
        let _ = terminal.draw(|frame| {
            draw_ui(frame, &data, opts, elapsed_start, &mut mode, use_color);
        });
        // event poll until next frame
        let poll_until = Instant::now() + frame_interval;
        loop {
            let remaining = poll_until.saturating_duration_since(Instant::now());
            if remaining.is_zero() { break; }
            match event::poll(remaining) {
                Ok(true) => {
                    if let Ok(Event::Key(key)) = event::read() {
                        if key.kind == KeyEventKind::Release { continue; }
                        let now_elapsed = monitor_start.elapsed();
                        let current_idx = match mode { Mode::Auto => auto_scale_idx(now_elapsed), Mode::Manual(i) => i };
                        match key.code {
                            KeyCode::Char('q') => { cancelled.store(true, Ordering::SeqCst); }
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => { cancelled.store(true, Ordering::SeqCst); }
                            KeyCode::Char('+') | KeyCode::Char('=') => {
                                mode = Mode::Manual(current_idx.saturating_sub(1));
                            }
                            KeyCode::Char('-') => {
                                mode = Mode::Manual((current_idx + 1).min(SCALES.len() - 1));
                            }
                            KeyCode::Char('a') => { mode = Mode::Auto; }
                            _ => {}
                        }
                        if cancelled.load(Ordering::Relaxed) { break; }
                    }
                }
                Ok(false) => break,
                Err(_) => break,
            }
        }
        if let Ok(res) = final_rx.try_recv() {
            final_result = Some(res);
            break;
        }
    }
    // restore terminal
    let _ = disable_raw_mode();
    let _ = terminal.backend_mut().execute(LeaveAlternateScreen);
    let _ = terminal.show_cursor();
    match final_result {
        Some(res) => res,
        None => {
            // Wait for final (should arrive after cancel)
            match final_rx.recv() {
                Ok(res) => res,
                Err(_) => Err(anyhow::anyhow!("connection error")),
            }
        }
    }
}

fn sorted_counts_desc<T: Clone + Ord>(map: &BTreeMap<T, usize>) -> Vec<(T, usize)> {
    let mut v: Vec<(T, usize)> = map.iter().map(|(k, v)| (k.clone(), *v)).collect();
    v.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    v
}

fn draw_ui(frame: &mut ratatui::Frame, data: &MonitorData, opts: &Opts, start: Instant, mode: &mut Mode, use_color: bool) {
    let area = frame.area();
    let now = Instant::now();
    let elapsed = now.duration_since(start);
    let scale_idx = match *mode { Mode::Auto => auto_scale_idx(elapsed), Mode::Manual(i) => i };
    let scale = SCALES[scale_idx];
    let is_auto = matches!(*mode, Mode::Auto);

    let err_height = (data.errors.len() as u16).saturating_add(2);
    let vertical = Layout::vertical([
        Constraint::Length(3),
        Constraint::Length(8),
        Constraint::Length(err_height),
        Constraint::Min(0),
    ]).split(area);

    // Progress
    let (ratio, label) = if let Some(dur) = opts.duration {
        let r = if dur.as_secs_f64() > 0.0 { (elapsed.as_secs_f64() / dur.as_secs_f64()).clamp(0.0, 1.0) } else { 1.0 };
        (r, format!("{}s / {}", elapsed.as_secs(), format_total_duration(dur)))
    } else {
        let done = data.success.len() + data.errors.values().sum::<usize>();
        let r = if opts.n_requests > 0 { (done as f64 / opts.n_requests as f64).clamp(0.0, 1.0) } else { 0.0 };
        (r, format!("{} / {}", done, opts.n_requests))
    };
    let gauge_style = if use_color { Style::default().fg(Color::Cyan) } else { Style::default() };
    let gauge = Gauge::default()
        .block(Block::bordered().title("Progress"))
        .gauge_style(gauge_style)
        .ratio(ratio)
        .label(label);
    frame.render_widget(gauge, vertical[0]);

    // Last-window subset
    let window_start = now.checked_sub(scale.dur).unwrap_or(start);
    let subset: Vec<&RequestResult> = data.success.iter().filter(|r| r.end > window_start && r.end <= now).collect();
    let subset_durs: Vec<f64> = subset.iter().map(|r| r.duration().as_secs_f64()).collect();
    let (slowest, fastest, average) = printer::slowest_fastest_avg(&subset_durs);
    let subset_data: usize = subset.iter().map(|r| r.len_bytes).sum();
    let (of_count, of_limit) = open_files();
    let fmt_secs = |v: f64| -> String { if v.is_nan() { "NaN".into() } else if v == f64::INFINITY { "inf".into() } else if v == f64::NEG_INFINITY { "-inf".into() } else { format!("{:.4}", v) } };
    let stats_text = format!(
        "Requests : {}\nSlowest: {} secs\nFastest: {} secs\nAverage: {} secs\nData: {}\nNumber of open files: {} / {}",
        subset.len(), fmt_secs(slowest), fmt_secs(fastest), fmt_secs(average), printer::fmt_bytes(subset_data as u64), of_count, of_limit
    );
    let middle = Layout::horizontal([Constraint::Percentage(50), Constraint::Percentage(50)]).split(vertical[1]);
    // Stats paragraph with per-line colors when enabled: build Text with styled lines
    {
        use ratatui::text::{Line, Span};
        let lines_src: Vec<&str> = stats_text.split('\n').collect();
        let mut lines: Vec<Line> = Vec::new();
        for (i, l) in lines_src.iter().enumerate() {
            let style = if use_color {
                match i { 1 => Style::default().fg(Color::Yellow), 2 => Style::default().fg(Color::Green), 3 => Style::default().fg(Color::Cyan), _ => Style::default() }
            } else { Style::default() };
            lines.push(Line::from(Span::styled(l.to_string(), style)));
        }
        let p = Paragraph::new(lines).block(Block::bordered().title(format!("Stats for last {}", scale.title)));
        frame.render_widget(p, middle[0]);
    }
    // Status distribution
    {
        let mut status_map: BTreeMap<u16, usize> = BTreeMap::new();
        for r in &data.success { *status_map.entry(r.status).or_insert(0) += 1; }
        let vec = sorted_counts_desc(&status_map);
        let text: Vec<String> = vec.iter().map(|(c, n)| format!("[{}] {} responses", c, n)).collect();
        let p = Paragraph::new(text.join("\n")).block(Block::bordered().title("Status code distribution"));
        frame.render_widget(p, middle[1]);
    }
    // Errors
    {
        let vec = sorted_counts_desc(&data.errors);
        let text: Vec<String> = vec.iter().map(|(msg, n)| format!("[{}] {}", n, msg)).collect();
        let p = Paragraph::new(text.join("\n")).block(Block::bordered().title("Error distribution"));
        frame.render_widget(p, vertical[2]);
    }
    if vertical[3].height == 0 { return; }
    let bottom = Layout::horizontal([Constraint::Percentage(50), Constraint::Percentage(50)]).split(vertical[3]);
    draw_requests_chart(frame, bottom[0], data, start, scale, is_auto, use_color);
    draw_histogram_chart(frame, bottom[1], &subset_durs, use_color);
}

fn draw_requests_chart(frame: &mut ratatui::Frame, area: Rect, data: &MonitorData, start: Instant, scale: Scale, is_auto: bool, use_color: bool) {
    let inner_w = area.width.saturating_sub(2) as usize;
    if inner_w == 0 { return; }
    let slot = scale.bar_width as usize + 1;
    let nbins = ((inner_w + 1) / slot).max(1);
    let mut counts = vec![0u64; nbins];
    for r in &data.success {
        let off = r.end.duration_since(start);
        let idx = (off.as_secs_f64() / scale.dur.as_secs_f64()) as usize;
        if idx < nbins { counts[idx] += 1; }
    }
    let bars: Vec<Bar> = counts.iter().enumerate().map(|(i, &c)| {
        let label = format!("{}{}", (i as u64) * scale.qty, scale.suffix);
        Bar::with_label(ratatui::text::Line::from(label), c)
    }).collect();
    let title = if is_auto {
        format!("Requests / past {} (auto). press -/+/a to change", scale.title)
    } else {
        format!("Requests / past {}. press -/+/a to change", scale.title)
    };
    let style = if use_color { Style::default().fg(Color::Green) } else { Style::default() };
    let chart = BarChart::vertical(bars)
        .block(Block::bordered().title(title).style(style))
        .bar_width(scale.bar_width)
        .bar_gap(1)
        .style(style)
        .bar_style(style);
    frame.render_widget(chart, area);
}

fn histogram_bins_n(durs: &[f64], nbins: usize) -> Vec<(f64, usize)> {
    if nbins == 0 { return vec![]; }
    let fastest = durs.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = durs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    if nbins == 1 { return vec![(fastest, durs.len())]; }
    let step = (slowest - fastest) / (nbins - 1) as f64;
    let mut bins = Vec::new();
    for i in 0..nbins {
        let boundary = fastest + step * i as f64;
        let count = if i == 0 {
            durs.iter().filter(|&&d| d <= boundary).count()
        } else {
            let prev = fastest + step * (i - 1) as f64;
            durs.iter().filter(|&&d| d > prev && d <= boundary).count()
        };
        bins.push((boundary, count));
    }
    bins
}

fn draw_histogram_chart(frame: &mut ratatui::Frame, area: Rect, durs: &[f64], use_color: bool) {
    let inner_w = area.width.saturating_sub(2) as usize;
    if inner_w == 0 { return; }
    let nbins = ((inner_w + 1) / 8).max(1);
    let bins = histogram_bins_n(durs, nbins);
    let bars: Vec<Bar> = bins.iter().map(|(b, c)| {
        let label = if b.is_nan() { "NaN".to_string() } else { format!("{:.4}", b) };
        Bar::with_label(ratatui::text::Line::from(label), *c as u64)
    }).collect();
    let style = if use_color { Style::default().fg(Color::Yellow) } else { Style::default() };
    let chart = BarChart::vertical(bars)
        .block(Block::bordered().title("Response time histogram").style(style))
        .bar_width(7)
        .bar_gap(1)
        .style(style)
        .bar_style(style);
    frame.render_widget(chart, area);
}
