        let lines_src: Vec<&str> = stats_text.split('\n').collect();
        let mut lines: Vec<Line> = Vec::new();
        for (i, l) in lines_src.iter().enumerate() {
            let style = if use_color {
                match i { 1 => Style::default().fg(Color::Yellow), 2 => Style::default().fg(Color::Green), 3 => Style::default().fg(Color::Cyan), _ => Style::default() }
            } else { Style::default() };
            lines.push(Line::from(Span::styled(l.to_string(), style)));
        }
        let p = Paragraph::new(lines).block(Block::bordered().title(format!("Stats for last {}", scale.title)));
        frame.render_widget(p, middle[0]);
    }
    // Status distribution
    {
        let mut status_map: BTreeMap<u16, usize> = BTreeMap::new();
        for r in &data.success { *status_map.entry(r.status).or_insert(0) += 1; }
        let vec = sorted_counts_desc(&status_map);
        let text: Vec<String> = vec.iter().map(|(c, n)| format!("[{}] {} responses", c, n)).collect();
        let p = Paragraph::new(text.join("\n")).block(Block::bordered().title("Status code distribution"));
        frame.render_widget(p, middle[1]);
    }
    // Errors
    {
        let vec = sorted_counts_desc(&data.errors);
        let text: Vec<String> = vec.iter().map(|(msg, n)| format!("[{}] {}", n, msg)).collect();
        let p = Paragraph::new(text.join("\n")).block(Block::bordered().title("Error distribution"));
        frame.render_widget(p, vertical[2]);
    }
    if vertical[3].height == 0 { return; }
    let bottom = Layout::horizontal([Constraint::Percentage(50), Constraint::Percentage(50)]).split(vertical[3]);
    draw_requests_chart(frame, bottom[0], data, start, scale, is_auto, use_color);
    draw_histogram_chart(frame, bottom[1], &subset_durs, use_color);
}

fn draw_requests_chart(frame: &mut ratatui::Frame, area: Rect, data: &MonitorData, start: Instant, scale: Scale, is_auto: bool, use_color: bool) {
    let inner_w = area.width.saturating_sub(2) as usize;
    if inner_w == 0 { return; }
    let slot = scale.bar_width as usize + 1;
    let nbins = ((inner_w + 1) / slot).max(1);
    let mut counts = vec![0u64; nbins];
    for r in &data.success {
        let off = r.end.duration_since(start);
        let idx = (off.as_secs_f64() / scale.dur.as_secs_f64()) as usize;
        if idx < nbins { counts[idx] += 1; }
    }
    let bars: Vec<Bar> = counts.iter().enumerate().map(|(i, &c)| {
        let label = format!("{}{}", (i as u64) * scale.qty, scale.suffix);
        Bar::with_label(ratatui::text::Line::from(label), c)
    }).collect();
    let title = if is_auto {
        format!("Requests / past {} (auto). press -/+/a to change", scale.title)
    } else {
        format!("Requests / past {}. press -/+/a to change", scale.title)
    };
    let style = if use_color { Style::default().fg(Color::Green) } else { Style::default() };
    let chart = BarChart::vertical(bars)
        .block(Block::bordered().title(title).style(style))
        .bar_width(scale.bar_width)
        .bar_gap(1)
        .style(style)
        .bar_style(style);
    frame.render_widget(chart, area);
}

fn histogram_bins_n(durs: &[f64], nbins: usize) -> Vec<(f64, usize)> {
    if nbins == 0 { return vec![]; }
    let fastest = durs.iter().cloned().fold(f64::INFINITY, f64::min);
    let slowest = durs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    if nbins == 1 { return vec![(fastest, durs.len())]; }
    let step = (slowest - fastest) / (nbins - 1) as f64;
    let mut bins = Vec::new();
    for i in 0..nbins {
        let boundary = fastest + step * i as f64;
        let count = if i == 0 {
            durs.iter().filter(|&&d| d <= boundary).count()
        } else {
            let prev = fastest + step * (i - 1) as f64;
            durs.iter().filter(|&&d| d > prev && d <= boundary).count()
        };
        bins.push((boundary, count));
    }
    bins
}

fn draw_histogram_chart(frame: &mut ratatui::Frame, area: Rect, durs: &[f64], use_color: bool) {
    let inner_w = area.width.saturating_sub(2) as usize;
    if inner_w == 0 { return; }
    let nbins = ((inner_w + 1) / 8).max(1);
    let bins = histogram_bins_n(durs, nbins);
    let bars: Vec<Bar> = bins.iter().map(|(b, c)| {
        let label = if b.is_nan() { "NaN".to_string() } else { format!("{:.4}", b) };
        Bar::with_label(ratatui::text::Line::from(label), *c as u64)
    }).collect();
    let style = if use_color { Style::default().fg(Color::Yellow) } else { Style::default() };
    let chart = BarChart::vertical(bars)
        .block(Block::bordered().title("Response time histogram").style(style))
        .bar_width(7)
        .bar_gap(1)
        .style(style)
        .bar_style(style);
    frame.render_widget(chart, area);
}
