use std::time::{Duration, Instant};

#[derive(Clone, Copy, PartialEq, Eq)]
struct Scale {
    dur: Duration,
    title: &'static str,
    suffix: &'static str,
    qty: u64,
    bar_width: u16,
}
const SCALES: [Scale; 6] = [
    Scale { dur: Duration::from_millis(1), title: "ms", suffix: "ms", qty: 1, bar_width: 6 },
    Scale { dur: Duration::from_secs(1), title: "sec", suffix: "s", qty: 1, bar_width: 5 },
    Scale { dur: Duration::from_secs(10), title: "10 sec", suffix: "s", qty: 10, bar_width: 6 },
    Scale { dur: Duration::from_secs(60), title: "min", suffix: "m", qty: 1, bar_width: 5 },
    Scale { dur: Duration::from_secs(600), title: "10 min", suffix: "m", qty: 10, bar_width: 6 },
    Scale { dur: Duration::from_secs(3600), title: "hr", suffix: "h", qty: 1, bar_width: 5 },
];

fn auto_scale_idx(elapsed: Duration) -> usize {
    let secs = elapsed.as_secs();
    if secs < 1 { 0 } else if secs < 10 { 1 } else if secs < 60 { 2 } else if secs < 600 { 3 } else if secs < 3600 { 4 } else { 5 }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode { Auto, Manual(usize) }

fn format_total_duration(d: Duration) -> String {
    // humantime-like with up to two units
    let secs = d.as_secs();
    let nanos = d.subsec_nanos();
    if secs == 0 {
        if nanos == 0 { return "0s".to_string(); }
        if nanos >= 1_000_000 { return format!("{}ms", nanos / 1_000_000); }
        if nanos >= 1_000 { return format!("{}us", nanos / 1_000); }
        return format!("{}ns", nanos);
    }
    let units: [(u64, &str); 6] = [(86400, "day"), (3600, "h"), (60, "m"), (1, "s"), (0, "ms"), (0, "us")];
    let days = secs / 86400;
    let rem = secs % 86400;
    let hours = rem / 3600;
    let minutes = (rem % 3600) / 60;
    let seconds = rem % 60;
    let mut parts: Vec<String> = Vec::new();
    if days > 0 { parts.push(format!("{}{}", days, if days == 1 { "day" } else { "days" })); }
    if hours > 0 && parts.len() < 2 { parts.push(format!("{}h", hours)); }
    if minutes > 0 && parts.len() < 2 { parts.push(format!("{}m", minutes)); }
    if seconds > 0 && parts.len() < 2 { parts.push(format!("{}s", seconds)); }
    if parts.len() < 2 && nanos >= 1_000_000 {
        parts.push(format!("{}ms", nanos / 1_000_000));
    }
    let _ = units;
    if parts.is_empty() { "0s".to_string() } else { parts.join(" ") }
}

fn open_files() -> (usize, u64) {
    let count = std::fs::read_dir("/proc/self/fd").map(|d| d.count()).unwrap_or(0);
    let mut rl: libc::rlimit = unsafe { std::mem::zeroed() };
    let limit = unsafe {
        if libc::getrlimit(libc::RLIMIT_NOFILE, &mut rl) == 0 { rl.rlim_cur as u64 } else { 0 }
    };
    (count, limit)
}

struct MonitorData {
    success: Vec<RequestResult>,
    errors: BTreeMap<String, usize>,
}

pub fn run_with_tui(client: Arc<Client>, gen: &UrlGenerator, cancelled: Arc<AtomicBool>, opts: &Opts) -> anyhow::Result<(StatsData, Instant)> {
    run_tui_generic(client, gen, cancelled, opts, false)
}

pub fn run_h2_with_tui(client: Arc<Client>, gen: &UrlGenerator, cancelled: Arc<AtomicBool>, opts: &Opts) -> anyhow::Result<(StatsData, Instant)> {
    run_tui_generic(client, gen, cancelled, opts, true)
}

fn run_tui_generic(client: Arc<Client>, gen: &UrlGenerator, cancelled: Arc<AtomicBool>, opts: &Opts, http2: bool) -> anyhow::Result<(StatsData, Instant)> {
    let use_color = !opts.no_color;
    let gen_addr = gen as *const UrlGenerator as usize;
    let opts_clone = opts.clone();
    let client_clone = client.clone();
    let cancelled_clone = cancelled.clone();
    let (live_tx, live_rx) = mpsc::channel::<Result<RequestResult, String>>();
    let (final_tx, final_rx) = mpsc::channel::<anyhow::Result<(StatsData, Instant)>>();
    // Terminal setup (before starting load like original)
    enable_raw_mode().ok();
    let mut stdout = std::io::stdout();
    let _ = stdout.execute(EnterAlternateScreen);
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    let _ = terminal.hide_cursor();
    let _ = terminal.clear();

    let monitor_start = Instant::now();
    std::thread::spawn(move || {
        let gen_ref: &UrlGenerator = unsafe { &*(gen_addr as *const UrlGenerator) };
        let res = if http2 {
            crate::http2::run_load_inner(client_clone, gen_ref, cancelled_clone, &opts_clone, Some(live_tx))
        } else {
            crate::run_load_http1(client_clone, gen_ref, cancelled_clone, &opts_clone, Some(live_tx))
        };
        let _ = final_tx.send(res);
    });

    let fps = if opts.fps == 0 { 16 } else { opts.fps };
    let frame_interval = Duration::from_secs(1) / (fps as u32);
    let mut mode = Mode::Auto;
    let mut data = MonitorData { success: Vec::new(), errors: BTreeMap::new() };
    let mut final_result: Option<anyhow::Result<(StatsData, Instant)>> = None;

    loop {
        // drain live results
        loop {
            match live_rx.try_recv() {
                Ok(Ok(r)) => data.success.push(r),
                Ok(Err(e)) => { *data.errors.entry(e).or_insert(0) += 1; }
                Err(_) => break,
            }
        }
        if let Ok(res) = final_rx.try_recv() {
            final_result = Some(res);
            break;
        }
        let elapsed_start = monitor_start;
        // draw
        let _ = terminal.draw(|frame| {
            draw_ui(frame, &data, opts, elapsed_start, &mut mode, use_color);
        });
        // event poll until next frame
        let poll_until = Instant::now() + frame_interval;
        loop {
            let remaining = poll_until.saturating_duration_since(Instant::now());
            if remaining.is_zero() { break; }
            match event::poll(remaining) {
                Ok(true) => {
                    if let Ok(Event::Key(key)) = event::read() {
                        if key.kind == KeyEventKind::Release { continue; }
                        let now_elapsed = monitor_start.elapsed();
                        let current_idx = match mode { Mode::Auto => auto_scale_idx(now_elapsed), Mode::Manual(i) => i };
                        match key.code {
                            KeyCode::Char('q') => { cancelled.store(true, Ordering::SeqCst); }
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => { cancelled.store(true, Ordering::SeqCst); }
                            KeyCode::Char('+') | KeyCode::Char('=') => {
                                mode = Mode::Manual(current_idx.saturating_sub(1));
                            }
                            KeyCode::Char('-') => {
                                mode = Mode::Manual((current_idx + 1).min(SCALES.len() - 1));
                            }
                            KeyCode::Char('a') => { mode = Mode::Auto; }
                            _ => {}
                        }
                        if cancelled.load(Ordering::Relaxed) { break; }
                    }
                }
                Ok(false) => break,
                Err(_) => break,
            }
        }
        if let Ok(res) = final_rx.try_recv() {
            final_result = Some(res);
            break;
        }
    }
    // restore terminal
    let _ = disable_raw_mode();
    let _ = terminal.backend_mut().execute(LeaveAlternateScreen);
    let _ = terminal.show_cursor();
    match final_result {
        Some(res) => res,
        None => {
            // Wait for final (should arrive after cancel)
            match final_rx.recv() {
                Ok(res) => res,
                Err(_) => Err(anyhow::anyhow!("connection error")),
            }
        }
    }
}

fn sorted_counts_desc<T: Clone + Ord>(map: &BTreeMap<T, usize>) -> Vec<(T, usize)> {
    let mut v: Vec<(T, usize)> = map.iter().map(|(k, v)| (k.clone(), *v)).collect();
    v.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    v
}

