fn canonical_header_value(v: &[u8]) -> String {
    let s = String::from_utf8_lossy(v);
    // Trim leading/trailing whitespace and collapse sequential spaces.
    let trimmed = s.trim_matches(|c| c == ' ' || c == '\t');
    let mut out = String::new();
    let mut last_space = false;
    for c in trimmed.chars() {
        if c == ' ' || c == '\t' {
            if !last_space { out.push(' '); }
            last_space = true;
        } else {
            out.push(c);
            last_space = false;
        }
    }
    out
}

pub fn sign_request(spec: &mut RequestSpec, aws: &AwsConfig, opts: &Opts) {
    let (amz_date, date_stamp) = utc_now_amz();
    let had_date_header = headers_get(&spec.headers, "x-amz-date").is_some();
    // Host to sign: an explicitly present Host header takes precedence;
    // otherwise the URI host (without port), matching SigV4 signers.
    let host_sign: String = match headers_get(&spec.headers, "host") {
        Some(v) => String::from_utf8_lossy(v).to_string(),
        None => match spec.url.host() {
            Some(url::Host::Ipv6(ip)) => format!("[{}]", ip),
            Some(url::Host::Ipv4(ip)) => ip.to_string(),
            Some(url::Host::Domain(d)) => d.to_string(),
            None => String::new(),
        },
    };
    let content_length = spec.body.len().to_string();
    let payload_hash = sha256_hex(&spec.body);
    let canonical_uri = if spec.url.path().is_empty() { "/".to_string() } else { spec.url.path().to_string() };
    let canonical_qs = {
        let q = spec.url.query().unwrap_or("");
        if q.is_empty() { String::new() } else {
            let mut pairs: Vec<(String, String)> = q.split('&').map(|pair| {
                let (k, v) = match pair.split_once('=') {
                    Some((k, v)) => (k, v),
                    None => (pair, ""),
                };
                (aws_uri_encode(&percent_decode(k), true), aws_uri_encode(&percent_decode(v), true))
            }).collect();
            pairs.sort();
            pairs.iter().map(|(k, v)| format!("{}={}", k, v)).collect::<Vec<_>>().join("&")
        }
    };

    // Collect headers to sign: everything present except the ignored set,
    // with host / x-amz-date / content-length overridden by signed values.
    let mut signed_map: std::collections::BTreeMap<String, String> = std::collections::BTreeMap::new();
    for (name, value) in &spec.headers {
        if IGNORED_HEADERS.contains(&name.as_str()) { continue; }
        signed_map.insert(name.clone(), canonical_header_value(value));
    }
    signed_map.insert("host".to_string(), canonical_header_value(host_sign.as_bytes()));
    signed_map.insert("x-amz-date".to_string(), amz_date.clone());
    signed_map.insert("content-length".to_string(), content_length.clone());
    if let Some(tok) = &aws.session {
        signed_map.insert("x-amz-security-token".to_string(), canonical_header_value(tok.as_bytes()));
    }
    let canonical_headers: String = signed_map.iter().map(|(k, v)| format!("{}:{}\n", k, v)).collect();
    let signed_headers = signed_map.keys().cloned().collect::<Vec<_>>().join(";");
    let canonical_request = format!("{}\n{}\n{}\n{}\n{}\n{}", spec.method, canonical_uri, canonical_qs, canonical_headers, signed_headers, payload_hash);
    let scope = format!("{}/{}/{}/aws4_request", date_stamp, aws.region, aws.service);
    let string_to_sign = format!("AWS4-HMAC-SHA256\n{}\n{}\n{}", amz_date, scope, sha256_hex(canonical_request.as_bytes()));
    let k_date = hmac_sha256(format!("AWS4{}", aws.secret_key).as_bytes(), date_stamp.as_bytes());
    let k_region = hmac_sha256(&k_date, aws.region.as_bytes());
    let k_service = hmac_sha256(&k_region, aws.service.as_bytes());
