            "host" => host_sign.clone().into_bytes(),
            "x-amz-date" => amz_date.clone().into_bytes(),
            "content-length" => content_length.clone().into_bytes(),
            "x-amz-security-token" => aws.session.clone().unwrap_or_default().into_bytes(),
            _ => orig.iter().find(|(n, _)| n == name).map(|(_, v)| v.clone()).unwrap_or_else(|| signed_map.get(name).cloned().unwrap_or_default().into_bytes()),
