    let signed_names: Vec<String> = signed_map.keys().cloned().collect();
    let mut front: Headers = Vec::new();
    let date_first = aws.session.is_some() || opts.host.is_some() || had_date_header;
    if date_first {
        front.push(("x-amz-date".to_string(), value_of("x-amz-date", &signed_map, &orig)));
        front.push(("host".to_string(), value_of("host", &signed_map, &orig)));
