            }
        }
        front.push(("x-amz-date".to_string(), value_of("x-amz-date", &signed_map, &orig)));
        if signed_names.iter().any(|n| n == "content-type") {
            front.push(("content-type".to_string(), value_of("content-type", &signed_map, &orig)));
        }
        front.push(("content-length".to_string(), value_of("content-length", &signed_map, &orig)));
