        }
    }
    let mut rest: Headers = orig.into_iter().filter(|(n, _)| IGNORED_HEADERS.contains(&n.as_str()) && n != "authorization").collect();
    front.append(&mut rest);
    front.push(("authorization".to_string(), auth.into_bytes()));
    spec.headers = front;
