fn spawn_tunnel_pump(mut remote: std::os::unix::net::UnixStream, from_actor: mpsc::Receiver<Vec<u8>>, to_actor: mpsc::Sender<Vec<u8>>) {
    std::thread::spawn(move || {
        let fd = remote.as_raw_fd();
        let mut write_buf: Vec<u8> = Vec::new();
        let mut from_actor_open = true;
        loop {
            if from_actor_open {
                loop {
                    match from_actor.try_recv() {
                        Ok(bytes) => write_buf.extend_from_slice(&bytes),
                        Err(mpsc::TryRecvError::Empty) => break,
                        Err(mpsc::TryRecvError::Disconnected) => { from_actor_open = false; break; }
                    }
                }
            }
            let (readable, writable) = crate::netio::poll_once(fd, true, !write_buf.is_empty(), 5);
            if writable && !write_buf.is_empty() {
                match remote.write(&write_buf) {
                    Ok(n) => { write_buf.drain(..n); }
                    Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {}
                    Err(_) => break,
                }
            }
            if readable {
                let mut buf = vec![0u8; 16384];
                match remote.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => { buf.truncate(n); if to_actor.send(buf).is_err() { break; } }
                    Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {}
                    Err(_) => break,
                }
            }
            if !from_actor_open && write_buf.is_empty() {
                let _ = remote.shutdown(std::net::Shutdown::Write);
                break;
            }
        }
        let _ = remote.shutdown(std::net::Shutdown::Both);
    });
}

pub fn establish_h2_tunnel(client: &Client, target_url: &Url, authority: &str, ctx: &TimeCtx) -> Result<crate::client::RawEstablish, ReqError> {
    let mut connect_ctx = ctx.clone();
    connect_ctx.deadlines.push((Instant::now() + client.opts.connect_timeout, DeadlineKind::Timeout));
    let est = client.establish_proxy_stream(true, &connect_ctx)?;
    let dns_lookup = est.dns_lookup;
    let key = est.key.clone();
    let handle = create_handle_from_est(est, &connect_ctx)?;
    // socketpair: local end is returned as the tunneled byte stream.
    let (local, remote) = std::os::unix::net::UnixStream::pair().map_err(ReqError::from)?;
    local.set_nonblocking(true).ok();
    remote.set_nonblocking(true).ok();
    let (actor_to_pump_tx, actor_to_pump_rx) = mpsc::channel::<Vec<u8>>();
    let (pump_to_actor_tx, pump_to_actor_rx) = mpsc::channel::<Vec<u8>>();
    spawn_tunnel_pump(remote, actor_to_pump_rx, pump_to_actor_tx);
    let spec = RequestSpec {
        method: "CONNECT".to_string(),
        uri_display: authority.to_string(),
        version: HttpVersion::V2,
        headers: client.opts.proxy_headers.iter().map(|h| (h.name.clone(), h.value.clone())).collect(),
        body: Arc::new(Vec::new()),
        url: target_url.clone(),
    };
    let (reply_tx, reply_rx) = mpsc::channel();
    let job = Job {
        spec, ctx: connect_ctx.clone(), collect_body: false, reply: reply_tx,
        connect_authority: Some(authority.to_string()),
        tunnel_to_pump: Some(actor_to_pump_tx),
        tunnel_from_pump: Some(pump_to_actor_rx),
    };
    if handle.tx.send(job).is_err() {
        return Err(ReqError::Msg("connection error".to_string()));
    }
    match reply_rx.recv() {
        Ok(Ok(_raw)) => Ok(crate::client::RawEstablish {
            stream: AnyStream::Unix(local),
            key,
            dns_lookup,
            dns_dialup: handle.dns_dialup,
            initial: Vec::new(),
        }),
        Ok(Err(e)) => Err(e),
        Err(_) => Err(ReqError::Msg("connection error".to_string())),
    }
}

