pub fn stream_to_unix(mut outer: AnyStream) -> UnixStream {
    let (local, mut remote) = UnixStream::pair().expect("socketpair");
    local.set_nonblocking(true).ok();
    remote.set_nonblocking(true).ok();
    std::thread::spawn(move || {
        let mut to_remote: Vec<u8> = Vec::new();
        let mut to_outer: Vec<u8> = Vec::new();
        let mut outer_eof = false;
        let mut remote_eof = false;
        loop {
            // Poll both directions briefly.
            let mut fds = [
                libc::pollfd { fd: outer.fd(), events: libc::POLLIN | if !to_outer.is_empty() { libc::POLLOUT } else { 0 }, revents: 0 },
                libc::pollfd { fd: remote.as_raw_fd(), events: libc::POLLIN | if !to_remote.is_empty() { libc::POLLOUT } else { 0 }, revents: 0 },
            ];
            unsafe { libc::poll(fds.as_mut_ptr(), 2, 5); }
            // Always try reading from outer (TLS may have buffered plaintext).
            if !outer_eof {
                let mut buf = vec![0u8; 16384];
                match outer.try_read_some(&mut buf) {
                    Ok(Some(0)) => { outer_eof = true; }
                    Ok(Some(n)) => { to_remote.extend_from_slice(&buf[..n]); }
                    Ok(None) => {}
                    Err(_) => { outer_eof = true; }
                }
            }
            if !remote_eof {
                let mut buf = vec![0u8; 16384];
                match remote.read(&mut buf) {
                    Ok(0) => { remote_eof = true; }
                    Ok(n) => { to_outer.extend_from_slice(&buf[..n]); }
                    Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => {}
                    Err(_) => { remote_eof = true; }
                }
            }
            if !to_outer.is_empty() {
                match outer.try_write_some(&to_outer) {
                    Ok(Some(n)) => { to_outer.drain(..n); }
                    Ok(None) => {}
                    Ok(Some(0)) => {}
                    Err(_) => { break; }
                }
            }
            if !to_remote.is_empty() {
                match remote.write(&to_remote) {
                    Ok(n) => { to_remote.drain(..n); }
                    Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => {}
                    Err(_) => { break; }
                }
            }
            if outer_eof && to_remote.is_empty() {
                let _ = remote.shutdown(std::net::Shutdown::Write);
                if remote_eof { break; }
                // Keep reading local until it closes so actor-side EOF propagates promptly;
                // if the local side has already closed its read end, read above returns 0.
                if to_outer.is_empty() && remote_eof { break; }
            }
            if remote_eof && to_outer.is_empty() {
                break;
            }
        }
        outer.shutdown();
        let _ = remote.shutdown(std::net::Shutdown::Both);
    });
    local
