        (3_600u64, "h", "h"),
        (60u64, "m", "m"),
        (1u64, "s", "s"),
    ] {
        if rem >= unit_secs {
            let v = rem / unit_secs;
            rem %= unit_secs;
            parts.push(format!("{}{}", v, if v == 1 { singular } else { plural }));
        }
    }
    if nanos > 0 {
        let ms = nanos / 1_000_000;
        let us = (nanos % 1_000_000) / 1_000;
